P.transportVersion = 1
P.transport = {}
P.transport["npc:abercrombie"] = {
  hash = "1b0038",
  fullHash = "1b0038",
  text = "Abercrombie. Near Raven Hill Cemetery, Abercrombie asks travelers to bring supplies from Darkshire. In western Duskwood, the old hermit seems worn and troubled by the woods. Abercrombie lives in a ruined shack near Raven Hill Cemetery. Duskwood's decay has left him looking like a broken old man. He says he is trying to survive the terrors of the woods, and asks travelers to bring supplies, herbs, and thread from Darkshire. To anyone who does not know the region's history, he seems another unfortunate soul left behind as the province fell into ruin.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_abercrombie-fc5f05d0e740dd50364b/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["npc:alanndarian-nightsong"] = {
  hash = "e1fb77",
  fullHash = "e2aded",
  text = "Alanndarian Nightsong. In Auberdine, Alanndarian Nightsong tends to Darkshore's sickened wildlife. She works with travelers to ease the afflictions spreading through the region, especially among its deer. From the coastal settlement of Auberdine, Alanndarian Nightsong watches over Darkshore's wildlife. Taints in the soil and water have left creatures of the ancient woods sick and strangely aggressive. She seeks ways to ease their suffering and restore their strength. Alanndarian Nightsong searches for what is making Darkshore's animals ill. She gathers plants and studies the region's water sources, then prepares salves and healing draughts. Travelers help her apply these cures to ailing creatures, hoping to stop the corruption from overtaking the wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_alanndarian-nightsong-df2615e9ee2b84b3bdf3/1-0000.mp3", duration = 43.8857143, start = 0},
  },
}
P.transport["npc:althea-ebonlocke"] = {
  hash = "9ae60d",
  fullHash = "739347",
  text = "Althea Ebonlocke. In Darkshire, Althea Ebonlocke leads the Night Watch against Duskwood’s horrors. A relative of Mayor Ello Ebonlocke, she guards an isolated region left without Stormwind’s regular troops. Althea Ebonlocke directs Darkshire’s defense while Mayor Ello Ebonlocke, her relative, governs from the town hall. Stormwind sent no royal troops to guard Duskwood, so the townspeople formed the Night Watch. Under Althea’s firm command, its volunteers patrol the foggy roads and keep undead skeletons, fierce wolves, and spiders from overrunning the town’s edge. Althea knows her militia cannot face the dangers alone. Recruits are scarce and the Watch keeps losing them, so she enlists passing mercenaries and travelers to thin the threats near Darkshire. She directs efforts against ghouls and skeletons in the forest’s quiet, sorrowful graveyards. All the while, she watches for darker rumors from deep in the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_althea-ebonlocke-13e152a6bb073eed4bd4/1-0000.mp3", duration = 56.3461224, start = 0},
  },
}
P.transport["npc:asterion"] = {
  hash = "145b72",
  fullHash = "a87e25",
  text = "Asterion. At Bashal'Aran, Asterion remains bound to a moonstone seal. The ancient Highborne once served governor Athrikus Narassin, and now his spirit waits among the ruins for release. Before the Great Sundering, Bashal'Aran and Ameth'Aran were sister cities blessed by Queen Azshara. She appointed Athrikus Narassin to govern them, and Asterion served as his right hand. Renowned for physical combat and arcane sorcery, Asterion lived among Bashal'Aran's people. He often traveled between the sister cities to see to their citizens' needs. For reasons lost to time, Asterion fell out of favor with Athrikus Narassin. His master fashioned a powerful moonstone seal, an inescapable magical cage meant to confine him in Bashal'Aran. The centuries of confinement brought Asterion agony. Even death offered no release: his spirit remained bound to the ruined shrine after the world cracked open and demons overran the settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_asterion-07c08707da0f85484f9b/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["npc:athridas-bearmantle"] = {
  hash = "b2434d",
  fullHash = "0b93f6",
  text = "Athridas Bearmantle. In Dolanaar, Athridas Bearmantle calls young adventurers to defend the settlement and its wilds. The night elf druid sends them to investigate corruption among local wildlife and the nearby Gnarlpine furbolgs. Athridas Bearmantle helps defend night elves arriving from Shadowglen in Dolanaar. Teldrassil, the newly grown world tree, shows unnatural signs of decay and unrest. So Athridas organizes local scouting and guards the township against threats from the surrounding wilds. Athridas Bearmantle worries over the nearby Gnarlpine furbolgs. Once peaceful neighbors, the tribe has fallen to spreading madness and corruption. The taint poisons their shamans and chieftains, driving them to violence against the Kaldorei. Athridas calls on willing champions to contain the danger and investigate the deeper corruption taking root in the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_athridas-bearmantle-019bd17142746f5efe96/1-0000.mp3", duration = 53.4726531, start = 0},
  },
}
P.transport["npc:auntie-bernice-stonefield"] = {
  hash = "250781",
  fullHash = "250781",
  text = "\"Auntie\" Bernice Stonefield. At the Stonefield homestead in south-central Elwynn Forest, “Auntie” Bernice Stonefield keeps watch over the neighborhood. Widowed by the kingdom’s military campaigns, she lives beside Ma Stonefield and is known across the valley for her pork belly pies. She remains deeply suspicious of the rival Maclure family. War took Bernice’s husband in the Kingdom of Stormwind’s military campaigns. She now lives with her kin at the family homestead. There, she helps Ma Stonefield manage the farm’s daily affairs and keeps the household fed and running. Her pork belly pies have made her famous throughout the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_auntie-bernice-stonefield-8169135bc4a45507ccda/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["npc:balthule-shadowstrike"] = {
  hash = "0d5383",
  fullHash = "0d5383",
  text = "Balthule Shadowstrike. Near the Tower of Althalaxx, Balthule Shadowstrike keeps watch over northern Darkshore. He scouts for Delgren the Purifier, watching the dark practitioners in ancient elven ruins. West of the Tower of Althalaxx, Balthule Shadowstrike keeps watch alone. Restless spirits haunt northern Darkshore, and shadowed ruins fill its coast. Yet the tower poses a special danger. Under Delgren the Purifier’s direction, Balthule watches the dark casters who have entered the ancient Highborne ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_balthule-shadowstrike-c7f6776102eb4fed435d/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["npc:baros-alexston"] = {
  hash = "b62f5c",
  fullHash = "b62f5c",
  text = "Baros Alexston. In Stormwind City Hall, Baros Alexston tends the capital he helped rebuild. He was once close to Edwin VanCleef in the Stonemasons Guild, but stayed loyal to the crown when the guild split. Baros grew up at the Alexston Farmstead in Westfall's rolling grasslands. Thieves overran and burned his family's home while he was young. Before they fled, his father hid their cherished heirlooms across the grounds.\n\nBaros later went to the capital and joined the Stonemasons Guild. For years, he worked beside Guildmaster Edwin VanCleef as they raised Stormwind anew from the ashes of the First War.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_baros-alexston-49aeac65efd01573d92b/1-0000.mp3", duration = 35.7093878, start = 0},
  },
}
P.transport["npc:billy-maclure"] = {
  hash = "cb3fc3",
  fullHash = "cb3fc3",
  text = "Billy Maclure. At Maclure Vineyards, Billy Maclure's pranks stir trouble between two neighboring farms. The young human boy dodges chores and joins the feud between his family and the Stonefields, though fresh pastries can win his help. Billy Maclure spends his days outside the barn at Maclure Vineyards, near farmer Gerard Tiller. He grows up among the grapevines in southern Elwynn Forest, often slipping away from chores to roam the meadows. The Maclures and Stonefields have long been hostile toward each other. Billy turns their feud into a chance for pranks and petty theft.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_billy-maclure-5626b23d64b6cd2807eb/1-0000.mp3", duration = 33.1755102, start = 0},
  },
}
P.transport["npc:blind-mary"] = {
  hash = "29016c",
  fullHash = "f1f0db",
  text = "Blind Mary. In a ruined farmhouse southeast of Darkshire, Blind Mary wanders as a tormented banshee. Once a vain and beautiful woman, she was slain when the undead swept through Duskwood and rose in a form she could not bear. Before the shadows fell across Duskwood, Mary was known for her beauty. She took great pride in it and rarely went without her treasured looking glass. When the undead swept through the region, Mary and many of her neighbors were slain. Her spirit found no rest in the earth. She became an ethereal banshee, condemned to wander the mortal realm in a ghastly, translucent form. Sorrow, horror, and fury overwhelmed Mary when she awoke among the undead. Unable to bear her monstrous reflection, she clawed out her own eyes with her bare hands. She cast away her beloved looking glass and drifted through her abandoned home, blind and weeping. Faint memories of the mortal life she lost were all she could cling to.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_blind-mary-bcd72bc8cf42403ebdb6/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["npc:bolvar-fordragon"] = {
  hash = "749898",
  fullHash = "749898",
  text = "Bolvar Fordragon. In Stormwind Keep, Bolvar Fordragon holds the crown and armies while King Varian is missing. As Regent and Supreme Commander of Stormwind’s armed forces, he stands beside young King Anduin and struggles to hold the kingdom together. Troubles at home grow, while Lady Katrana Prestor’s counsel often delays his military decisions. King Varian vanished while traveling to a peace summit on Theramore Isle, leaving Stormwind in disarray. Ten-year-old Prince Anduin was crowned to preserve continuity, and Highlord Bolvar Fordragon took up the work of ruling as Regent.\n\nA venerated paladin devoted to the crown, Bolvar now faces a kingdom under strain. Stormwind’s soldiers are spread thin across Westfall, Redridge, and Duskwood. Lady Katrana Prestor dismisses his concerns and repeatedly blocks him from sending royal troops to frontier towns.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bolvar-fordragon-f52f13dc62d915a715d8/1-0000.mp3", duration = 53.1069388, start = 0},
  },
}
P.transport["npc:calor"] = {
  hash = "db2b71",
  fullHash = "cb4b07",
  text = "Calor. In Darkshire, Calor directs the fight against worgen stalking Duskwood. Under Jonathan Carevin, he helps the Carevin family hunt the beasts threatening the forests. In Darkshire, Calor helps the Carevin family fight the horrors closing in on town. He works under Jonathan Carevin, one of Darkshire's defenders. Together they seek to destroy the supernatural threats before the remaining townsfolk are slaughtered. Calor sends fighters after the worgen prowling Duskwood, especially near the Rotting Orchard. These wolf-men are more dangerous than common beasts. They slaughter travelers and patrols alike. So Calor calls on capable fighters to thin their ranks and investigate where they came from, hoping to stem their attacks.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_calor-94fa19cca8bae05b34fa/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["npc:captain-grayson"] = {
  hash = "becc07",
  fullHash = "e32fc1",
  text = "Captain Grayson. At Westfall Lighthouse, Captain Grayson keeps watch over the beacon that failed him. His ship struck the dark coast, and now he tends the light so other sailors do not share his fate. Captain Grayson once sailed the southern seas of the Eastern Kingdoms as a ship’s captain. One night, the lighthouse fire went dark as his vessel neared Westfall’s jagged shoals. The ship struck the rocks, and Grayson died with it. He awoke as an earthbound phantom, bound to the coast. After death, Captain Grayson went to Westfall Lighthouse, hoping to learn what waited beyond life. There he saw Old Murk-Eye, a notorious murloc, drive away the keeper and his family. The brave keepers returned to rekindle the flame. But Old Murk-Eye rallied the surrounding murlocs and led a second, brutal slaughter. Grayson could only watch as the family was butchered. With the keepers dead and Westfall crumbling under neglect, Captain Grayson bears the beacon’s solemn burden on his spectral shoulders. He asks passing travelers to gather fuel for the great flame. He also seeks vengeance for the slaughtered family: hunt down Old Murk-Eye and drive back the coastal murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-grayson-f07d5a010bcc0f7d8dbe/1-0000.mp3", duration = 71.7061224, start = 0},
  },
}
P.transport["npc:captain-stoutfist"] = {
  hash = "41d02e",
  fullHash = "4f2d60",
  text = "Captain Stoutfist. At Menethil Harbor, Captain Stoutfist rallies the defense against Dragonmaw attacks. The dwarf officer coordinates the garrison and its counterstrikes to keep the Alliance port from falling. Menethil Harbor is the principal deepwater port joining Ironforge and Stormwind to the Wetlands and the sea beyond. Captain Stoutfist commands the town’s defense and guards its docks, people, and garrison from the dangers around them. The marshlands are hazardous, but the greatest danger is an organized advance by renegade orcs. The Dragonmaw clan has held strongholds in the Wetlands since the Second War and now presses toward its roads and mountain passes. The orcs infiltrate Dun Algaz, threatening the overland route between Loch Modan, Ironforge, and Menethil Harbor. Stoutfist has too few troops, so he relies on Alliance volunteers sent by Mountaineer Valstag Ironjaw to hold them back.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-stoutfist-fa74479ab45caca11330/1-0000.mp3", duration = 53.0285714, start = 0},
  },
}
P.transport["npc:chief-engineer-hinderweir-vii"] = {
  hash = "d25286",
  fullHash = "d25286",
  text = "Chief Engineer Hinderweir VII. Atop the Stonewrought Dam, Chief Engineer Hinderweir the Seventh watches over its workings and defenses. The veteran dwarf keeps the great structure and its machinery sound as grave dangers threaten it. Chief Engineer Hinderweir the Seventh tends the Stonewrought Dam, whose stonework holds back Loch Modan's waters. Along the crest, he watches the waterways and sluice gates. He also checks for strain from the elements and local hazards. The dam's workings need constant care.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chief-engineer-hinderweir-vii-7c599ed6c0561955b2f6/1-0000.mp3", duration = 30.3804082, start = 0},
  },
}
P.transport["npc:clerk-daltry"] = {
  hash = "9c0766",
  fullHash = "3d2ae2",
  text = "Clerk Daltry. In Darkshire Town Hall, Clerk Daltry keeps the village’s records and searches its past with them. Ledgers and registry books fill his care, though the archives have fallen behind and are often neglected. Clerk Daltry keeps Darkshire’s records as beasts, undead horrors, and supernatural gloom press against the town. He works in Darkshire Town Hall with Lord Ello Ebonlocke and the local council. His ledgers hold the town’s history, property rolls, and census data. After disaster broke the region apart, these records remain among the few links to the days before Grand Hamlet fell into shadow. Since Darkshire was cut off from regular Stormwind administration, Clerk Daltry’s records have suffered. Documents go missing, ledgers fall behind, and town files are often misplaced or damaged. Those investigating old cases or searching for residents come to him for help. Answers may lie in overlooked notes, or in papers lost in the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_clerk-daltry-422ac9347e815d19cb98/1-0000.mp3", duration = 58.644898, start = 0},
  },
}
P.transport["npc:cliffwatcher-longhorn"] = {
  hash = "f85960",
  fullHash = "f85960",
  text = "Cliffwatcher Longhorn. At Freewind Post, Cliffwatcher Longhorn watches over the Horde's isolated hold in Thousand Needles. He directs its defense against the Galak centaur and keeps an eye on the Grimtotem tribe's dealings. Cliffwatcher Longhorn guards Freewind Post, an isolated settlement atop the rock spires of Thousand Needles. He oversees its daily security and gathers reports from scouts on the canyon floor and nearby ridges. Hostile forces are gathering around the post, so his steady leadership guides its defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cliffwatcher-longhorn-a0412bfbde0fe7383fd7/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["npc:collin-mauren"] = {
  hash = "c0384b",
  fullHash = "703b85",
  text = "Collin Mauren. In Stormwind's Mage Quarter, Collin Mauren studies practical magic and shapes useful spells from natural reagents. He also makes arcane scrolls for Gaxim Rustfizzle, his gnome friend and fellow explorer. In Stormwind's Mage Quarter, Collin Mauren studies how magic can solve practical problems. He shapes arcane formulas with natural anomalies and raw components gathered across Azeroth. Their properties help him make useful scrolls and reagents for friends and travelers. Collin Mauren is helping his friend Gaxim Rustfizzle set off NG-5 explosives from afar. Gaxim, a gnome tinkerer, needed a remote trigger, so Collin devised a messaging spell for a scroll. To impress the spell upon it, Collin uses debris from Westfall's erratic Dust Devils. Now he awaits word on how Gaxim's scheme fares. Collin Mauren's studies reach from Stormwind across the Great Sea to Kalimdor's Stonetalon Mountains. He seeks scales from the region's basilisks, whose resilient hides interest him as materials for new spells. Travelers bound for Kalimdor often receive his requests for these rare hides. The scales help him study how primal creature anatomy can steady complex enchantments.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_collin-mauren-ccee1804e939205f1cdf/1-0000.mp3", duration = 74.004898, start = 0},
  },
}
P.transport["npc:corithras-moonrage"] = {
  hash = "5ccf39",
  fullHash = "245ea0",
  text = "Corithras Moonrage. In Dolanaar, Corithras Moonrage teaches newcomers about Teldrassil and its moonwells. His lessons reveal the tree’s place in kaldorei life and the burdens its people bear. In Dolanaar, Corithras Moonrage teaches travelers about Teldrassil. Young kaldorei begin exploring the tree beyond Shadowglen, and he explains the history of their new home. He also speaks of the care its wilderness demands. In this changing era, survival calls for vigilance and respect for the natural order. Corithras gathers moonwell water for the druids in Darnassus. He sends travelers to draw pure water from moonwells across Teldrassil in specially crafted phials, then deliver it to Fandral Staghelm. This work helps him watch over the World Tree and preserve the wilderness against creeping corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_corithras-moonrage-409e34493bbbdf175d98/1-0000.mp3", duration = 50.0506122, start = 0},
  },
}
P.transport["npc:daphne-stilwell"] = {
  hash = "673add",
  fullHash = "417595",
  text = "Daphne Stilwell. On Westfall’s cliffs, Daphne Stilwell keeps watch over her orchard and home. She and her husband Jordan fled the north and now aid the Church of the Holy Light while guarding their land from nearby outlaws. West of Moonbrook and the Deadmines exit, Daphne Stilwell tends a homestead and apple orchard on the bluffs. The Longshore lies below, while gryphon routes to Stranglethorn Vale pass high above. The farm may look quiet from either way, but bandits and scavengers roam nearby. Daphne works among the trees and keeps watch over her isolated land. Before they came to Westfall, Daphne and her husband Jordan lived near Pyrewood Village in Lordaeron. They worked in what is now Shadowfang Keep. Darkness and disaster drove them south with thousands of other human refugees. Near Stormwind, Jordan’s renowned skill as a craftsman and Daphne’s steady presence brought them close to the Church of the Holy Light. They support the church and provide holy arms to paladins of the Silver Hand.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_daphne-stilwell-599c0fb2c27bfecd8fd4/1-0000.mp3", duration = 57.2342857, start = 0},
  },
}
P.transport["npc:delgren-the-purifier"] = {
  hash = "a4139c",
  fullHash = "9c8c07",
  text = "Delgren the Purifier. At Maestra's Post, Delgren the Purifier helps the night elves resist demonic and shadow magic on Ashenvale's northern edge. He stands watch with Balthule Shadowstrike and Feero Ironhand. Delgren the Purifier watches the road south from Auberdine. Human paladins are rare in Kalimdor's ancient forests, yet he came west with holy warriors of the Argent Dawn. They set out to help the Alliance's new night elf allies face demons and undead remnants left by the Third War. Delgren now guards the border of Darkshore and Ashenvale, where danger reaches the road. Delgren's devotion to the Holy Light has not kept him from studying Kalimdor's tangled politics. He learned Orcish, to the annoyance and disdain of his conservative superiors. The language helps him understand the enemies and neighbors who share this untamed continent, beyond his order's teachings.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_delgren-the-purifier-fe21f9ecc99f2600b449/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["npc:denalan"] = {
  hash = "f98110",
  fullHash = "32a485",
  text = "Denalan. At Lake Al'Ameth, Denalan studies Teldrassil's strange plants and seeks a remedy for its corruption. From his small lakeside plot, he asks young adventurers to gather samples, examine timberlings, and test enchanted soil. On Lake Al'Ameth's eastern shore, Denalan studies the plants that have taken root since Teldrassil's planting. Beneath a cloth awning, he keeps field tools and rows of planter boxes close at hand. While many kaldorei watch for danger or tend to high druidic rites, Denalan gives his days to herbalism. He chose this plot over Darnassus's grand barrows to study the World Tree's unusual flora. Denalan investigates the unrest among Teldrassil's native wildlife. Timberlings, usually docile woodland beings of wood and sprout, have grown more aggressive. He enchants soil to nurture wild seeds in captivity and study how corruption seeps into root systems. Among the specimens he examines are shimmering fronds, glowing fruit, and moss-twined growths. He seeks the taint troubling the forest boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_denalan-1d1d218a0e5d6df8a316/1-0000.mp3", duration = 66.037551, start = 0},
  },
}
P.transport["npc:dirania-silvershine"] = {
  hash = "58d518",
  fullHash = "c99711",
  text = "Dirania Silvershine. In Shadowglen, Dirania Silvershine keeps watch over the grove and worries for Iverron. Loyal and observant, she looks out for her companion when his reckless ventures put him in peril. Dirania watches over Shadowglen, a quiet vale beneath Teldrassil's boughs. Young night elves begin their service to Kalimdor and the Alliance here. While others in the barrow mounds and sanctuaries tend to wider spiritual duties, Dirania keeps her attention on those closest to her. Even in Teldrassil's heart, quiet dangers stir. Dirania's chief concern is her companion Iverron. Eager and careless around the poisonous creatures that creep through the glen, he often gets into trouble. When a webwood spider's venomous bite fells him, Dirania seeks willing hands to gather ingredients and prepare a remedy before the venom causes lasting harm.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dirania-silvershine-4a5c5079fea6d83c601f/1-0000.mp3", duration = 52.2187755, start = 0},
  },
}
P.transport["npc:dorn-plainstalker"] = {
  hash = "b82730",
  fullHash = "64da14",
  text = "Dorn Plainstalker. At the Weathered Nook, Dorn Plainstalker tests travelers who seek to prove their character and fortitude. The tauren elder guides Horde adventurers through rites of faith, endurance, strength, and lore, judging whether they are worthy servants of the Earth Mother and their people. Dorn Plainstalker lives in a shallow cave high on the Weathered Nook’s canyon ridges, apart from Freewind Post. Follow the northern cliffs above the towering mesas to reach his shelter. From this quiet vantage, he keeps ancient customs and judges those who seek guidance in the harsh southern barrens. Dorn Plainstalker guides pilgrims through four tests of a tauren champion: faith, endurance, strength, and lore. The trials ask aspirants to face fear, leap into the unknown, outlast cunning wilderness predators, and reflect on Kalimdor’s sacred history. Only then can they claim their final passage.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dorn-plainstalker-9859c56e1e1aea3bca1f/1-0000.mp3", duration = 53.1853061, start = 0},
  },
}
P.transport["npc:duthorian-rall"] = {
  hash = "3eadf2",
  fullHash = "d083e8",
  text = "Duthorian Rall. In Stormwind's Cathedral of Light, Duthorian Rall guides new holy warriors through their trials. A respected human knight of the Silver Hand, he is one of the Alliance's most influential paladins. He oversees their training and spiritual tests, teaching charity, valor, and devotion as they prepare to defend Azeroth from the Scourge and threats within the kingdom. In the Cathedral of Light, Duthorian Rall upholds the traditions of the Knights of the Silver Hand. The kingdom is unsettled by strife within its borders, and King Varian Wrynn is missing. Duthorian bears the duty of teaching discipline to new initiates. Respected paladins in the field send promising recruits to him: Brother Wilhelm in Goldshire and Brandur Ironhammer in Ironforge. There, the recruits begin their sacred trials. Duthorian teaches that martial power without a moral foundation is hollow. In the Tome of Divinity trials, he tests an initiate's empathy through acts of mercy and selfless service across Stormwind. Only then does he entrust candidates with deeper mysteries.\n\nNear Heroes' Vigil, he tests them with the Symbol of Life. Then he sends them to aid wounded allies and learn to channel the Light's power, restoring fallen comrades from death.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_duthorian-rall-62875db5bac6eb582fd5/1-0000.mp3", duration = 72.6465306, start = 0},
  },
}
P.transport["npc:elling-trias"] = {
  hash = "ecbf2b",
  fullHash = "e7089e",
  text = "Elling Trias. In Stormwind's Trade District, Elling Trias welcomes customers to his family cheese shop. Behind its easy talk, his work as an information broker reaches across continents. Elling Trias sells fine cheese in the Trade District beside his wife Elaine and son Ben. He offers wheels to customers and chats cheerfully with townsfolk. Yet those who know the shop well understand that Trias' Cheese is also one of Stormwind's most reliable fronts. The city's steady trade lets operatives, courtiers and adventurers exchange quiet words beyond the city watch's notice. Elling Trias keeps informants and allies far beyond the reach of most shopkeepers. His ties include Master Mathias Shaw of SI:7, Church contacts such as Bishop DeLavey, and agents in Darkshire, Theramore Isle and the distant Plaguelands near Hearthglen. So when rumors rise of highway bandits or quiet movements in the countryside, Trias often pieces them together before the royal court takes notice.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elling-trias-7bebd5a7a4ead343c52d/1-0000.mp3", duration = 57.4693878, start = 0},
  },
}
P.transport["npc:fandral-staghelm"] = {
  hash = "283e85",
  fullHash = "286930",
  text = "Fandral Staghelm. From the Cenarion Enclave in Darnassus, Fandral Staghelm leads the druids of the Cenarion Circle. With Malfurion Stormrage gone into the Emerald Dream, Fandral championed Teldrassil and a forceful Kaldorei resurgence, often clashing with High Priestess Tyrande Whisperwind. After the Third War, the night elves lost their immortality and sacred sanctuary when Nordrassil was sacrificed atop Mount Hyjal. When Malfurion Stormrage vanished, Fandral took up leadership of the druids. He persuaded the Circle of Ancients that their people must rebuild and regain their immortality.\n\nWith the Circle's approval, Fandral led the druids in raising Teldrassil off the coast of Kalimdor. He meant its great bough to honor Kaldorei endurance and restore their lost supremacy. The Dragon Aspects withheld their blessings from the endeavor. A millennium before the First War, Fandral served as the Kaldorei field commander in Silithus during the War of the Shifting Sands. The qiraji knew him as Kar'sis, the Hand of Earth. His beloved only son, Valstann, fought beside him on the front lines.\n\nThe qiraji General Rajaxx exploited Fandral's devotion with a feint against Southwind Village. Valstann was captured and executed before the horrified Archdruid. Grief broke Fandral's spirit and drove a devastating retreat. His bitter hatred of the swarm endures. In Darnassus, Fandral governs Kaldorei affairs with a haughty, unyielding hand. High Priestess Tyrande Whisperwind is a spiritual leader who favors preservation and cautious diplomacy. Fandral instead sees military expansion and decisive strength as vital to his people's survival.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fandral-staghelm-40c2d7a74cc869c2c62c/1-0000.mp3", duration = 103.88898, start = 0},
  },
}
P.transport["npc:farthing"] = {
  hash = "014af8",
  fullHash = "38437d",
  text = "Farthing. At Stormwind's Cathedral of Light, Farthing guides the faithful and directs aid across the kingdom. This kind and wise human clergyman tends to parishioners and those in need. Bishop Farthing tends to Stormwind City's spiritual needs from the Cathedral of Light. He serves alongside Archbishop Benedictus and the gathered clergy. There, he counsels travelers, aids those pursuing the holy arts, and carries out the Church of the Holy Light's civic and pastoral duties. From the capital, Farthing directs earnest travelers toward parts of the kingdom in need of holy aid. Reports tell of the necromancer Morbent Fel and an undead blight spreading through Duskwood. Farthing advises on ways to overcome dark sorceries and cleanse the blighted frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_farthing-571b914cd4f4968059cf/1-0000.mp3", duration = 45.9755102, start = 0},
  },
}
P.transport["npc:first-mate-fitzsimmons"] = {
  hash = "5ea774",
  fullHash = "ec921a",
  text = "First Mate Fitzsimmons. Outside Menethil Harbor's Deepwater Tavern, First Mate Fitzsimmons drinks away his days. He once served aboard the Wave Mistress in Kul Tiras's Third Fleet. After the fleet's destruction in the Second War, he is its sole known living survivor. Now he asks travelers to face the restless spirits of his drowned comrades. First Mate Fitzsimmons drinks alone outside the Deepwater Tavern in Menethil Harbor. His unwashed stench keeps many patrons away, and most see a broken old sailor drowning his memories. Sit and listen, though, and he tells how a proud fleet fell to fire and claw. During the Second War, Fitzsimmons served as first mate aboard the Wave Mistress. The ship sailed with Kul Tiras's Third Fleet to fight the Horde. Off the Wetlands coast, Dragonmaw orcs ambushed the fleet with enslaved red dragons. Fire consumed the ships, which broke apart and sank. Fitzsimmons alone reached shore alive.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_first-mate-fitzsimmons-2125dae116f703f8e181/1-0000.mp3", duration = 58.0963265, start = 0},
  },
}
P.transport["npc:foreman-oslow"] = {
  hash = "82e2b8",
  fullHash = "68904f",
  text = "Foreman Oslow. At Lakeshire, Foreman Oslow works to rebuild the Everstill Bridge, shattered by Blackrock orcs. Lost tools and stolen supplies have halted the repairs, leaving the town's trade route broken. Foreman Oslow works beside the broken Everstill Bridge, trying to reconnect Lakeshire. The span crosses Lake Everstill, joining western roads toward Elwynn to the eastern shore. Blackrock orcs descended from Stonewatch's crags and struck the crossing to cripple Lakeshire's trade and military movement. Now the town is split and exposed. Foreman Oslow has lost the tools and materials needed for repairs. Replacement tools came overland from Goldshire, then went aboard a lake ferry. Blackrock orc catapults struck the vessel, sending Oslow's heavy iron toolbox to Lake Everstill's muddy bed.\n\nGnolls in Redridge also seized a caravan carrying new materials from Stormwind. They took the iron pikes and rivets needed to raise the bridge's arches.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_foreman-oslow-144ad52222cd7295c8a3/1-0000.mp3", duration = 58.5665306, start = 0},
  },
}
P.transport["npc:furen-longbeard"] = {
  hash = "c59646",
  fullHash = "da3980",
  text = "Furen Longbeard. In Stormwind’s Dwarven District, warriors seek Furen Longbeard’s skill with battle-ready armor. Apprenticed to Grimand Elmore, he is known for his skill with metal and heavy protective gear. Furen Longbeard works far from Ironforge’s great forges, in Stormwind’s Dwarven District. Like many dwarves, he brought the old ways of working metal south to help rebuild and defend the kingdom. His craft connects him with artisans across the city and beyond. Grimand Elmore taught Furen Longbeard his craft. Furen has perfected ways to treat heavy mail and plate so they can withstand the blows of battle. Young warriors turn to him for durable protection. To make his fire-hardened armor, he needs rare ores, special components and exotic reagents from distant corners of the world.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_furen-longbeard-d413a641bddac93a3f8e/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["npc:gakin-the-darkbinder"] = {
  hash = "1d2b80",
  fullHash = "278b11",
  text = "Gakin the Darkbinder. Beneath The Slaughtered Lamb in Stormwind, Gakin the Darkbinder tests those who seek the warlock arts. He teaches aspiring Alliance warlocks to summon and bind demons. Below The Slaughtered Lamb's taproom, a cellar gathers those who study shadow and fel. Summoning circles and grim tomes fill the crypt-like room, kept from the eyes that watch Stormwind's open mage sanctuaries. There, Gakin teaches young warlocks discipline and restraint before they call forces they may not control. Gakin teaches demonology and the rites for binding demons. Those who earn his notice travel across the kingdom for rare things, among them stolen bloodstone talismans and corrupt wood from dark forests. When all is gathered, Gakin watches over their work in the crypt's summoning circle. There, novices face voidwalkers and succubi in trials that test their will and risk their lives.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gakin-the-darkbinder-36c775a86f4f6f5537f4/1-0000.mp3", duration = 54.7004082, start = 0},
  },
}
P.transport["npc:gaxim-rustfizzle"] = {
  hash = "5dcb1f",
  fullHash = "9fe273",
  text = "Gaxim Rustfizzle. On the Webwinder Path, Gaxim Rustfizzle seeks to win Stonetalon’s night elves to his cause. The ambitious gnome scholar and tinker represents the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. He hopes artifice and alchemy can preserve their woodland realm, and bears a fierce grudge against the Venture Company’s destructive operations. In Stonetalon’s craggy passes, Gaxim Rustfizzle offers the night elves another way to defend the wilds. He represents the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences.\n\nGaxim believes careful mechanisms and chemical solutions can defend and restore Kalimdor’s wilderness as well as prayers to Elune. Alongside the sentinel Kaela Shadowspear, he camps on the Webwinder Path and seeks to convince his tall, reclusive allies that engineering can protect the living forest. The Venture Company’s clear-cutting and industrial greed scar nearby Windshear Crag. Much of Gaxim’s effort goes toward resisting them. He believes their crude goblin machinery deserves neither respect nor mercy, and coordinates covert operations and volatile chemical sabotage against their logging. He also coordinates efforts to cripple the shredders and steal their schematics, hoping to show that gnomish intellect can defeat careless corporate plunder.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gaxim-rustfizzle-7001fbf00c8c03471539/1-0000.mp3", duration = 79.4122449, start = 0},
  },
}
P.transport["npc:gelbin-mekkatorque"] = {
  hash = "802145",
  fullHash = "802145",
  text = "Gelbin Mekkatorque. In Tinker Town, Gelbin Mekkatorque leads the gnomes who live in exile in Ironforge. His inventions include the mechanostrider and the Deeprun Tram, and he guides the effort to reclaim Gnomeregan. Gelbin Mekkatorque earned the title of High Tinker through inventive skill. Among the gnomes, leadership rests on intellect and merit, not bloodlines. He built the first working mechanostrider, changing how gnomes travel. He also helped the Bronzebeard dwarves develop siege engines and played a key part in building the Deeprun Tram between Ironforge and Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gelbin-mekkatorque-7896a97b6e741081f789/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["npc:glorin-steelbrow"] = {
  hash = "375759",
  fullHash = "375759",
  text = "Glorin Steelbrow. At the Deepwater Tavern in Menethil Harbor, Glorin Steelbrow aids Bishop Farthing from afar. He directs travelers to sacred relics and metals lost with the Third Fleet, joining Duskwood’s troubles to the wrecks off the Wetlands coast. Bishop Farthing works from Stormwind’s Cathedral of Light, aiding the people of Duskwood against its creeping terrors. In Menethil Harbor, Glorin Steelbrow keeps the bishop’s ties to the north from inside the Deepwater Tavern. He offers travelers direction as they seek sacred metals and forgotten relics. Through Glorin, the troubled forest in the south is linked to the sunken wreckage off the Wetlands coast.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_glorin-steelbrow-5827fba2c58ffc66ecd0/1-0000.mp3", duration = 37.12, start = 0},
  },
}
P.transport["npc:grelin-whitebeard"] = {
  hash = "a10bb3",
  fullHash = "d2dc43",
  text = "Grelin Whitebeard. In Coldridge Valley, Grelin Whitebeard keeps watch over the Frostmane threat by royal decree. Ironforge is busy fighting troggs, so his isolated camp depends on local recruits. Grelin Whitebeard and his brother Senir came to Coldridge Valley under orders from the Senate of Ironforge and King Magni Bronzebeard. Their charge was to assess and quell the threat from the native Frostmane trolls. Ironforge's soldiers are busy fighting trogg outbreaks across Dun Morogh, leaving the brothers short of supplies. So Grelin made camp in the snowy hills and relies on local recruits and passing initiates to do the work. From his camp, Grelin watches the Frostmane tribe press south from Coldridge Valley. The trolls grow bolder and raid beyond their mountain caverns. During one raid, Grik'nir the Cold, a heavily painted troll, slipped into the unattended camp and stole Grelin's field journal of observations.\n\nGrelin will not fail the King. He sends travelers into the Frostmane caves to recover his writings and carry his final report to Senir in Kharanos.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grelin-whitebeard-3999f36ff6d5e3861df6/1-0000.mp3", duration = 64.235102, start = 0},
  },
}
P.transport["npc:grif-wildheart"] = {
  hash = "8a3f66",
  fullHash = "504471",
  text = "Grif Wildheart. Outside the Thunderbrew Distillery in Kharanos, Grif Wildheart guides young hunters toward life with a beast companion. He teaches tracking, marksmanship, and how to tame beasts to hunters arriving from Coldridge Valley. Grif Wildheart has spent his life in Dun Morogh’s frozen wilds. While many Ironforge dwarves choose the forge or the mines, local mountaineers say he spends too much time among four-legged beasts. Still, none question his command of the wild. Years spent tracking snowbound ridges with seasoned hunting companions have taught him the ways of the predators among the crags. Young dwarf hunters finish their first trials in Coldridge Valley, then travel to Kharanos for Grif’s guidance. He sharpens their aim and teaches them to survive in the wild. His deepest craft, though, is joining hunter and beast. He sends his pupils into Dun Morogh’s freezing wastes with a taming rod to face Large Crag Boars, Snow Leopards, and Ice Claw Bears. Once a hunter has calmed three kinds of wild beasts, Grif’s training in Kharanos is complete. A hunter must also learn to feed, discipline, and train a new companion. So Grif sends his graduates up the mountainside to Ironforge. Beneath the capital’s vaulted roofs, they report to master beast trainers and learn to care for a companion meant to stay with them for life.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grif-wildheart-e80230c10af5938a3fc6/1-0000.mp3", duration = 82.6514286, start = 0},
  },
}
P.transport["npc:gryan-stoutmantle"] = {
  hash = "ed4bcb",
  fullHash = "f527c3",
  text = "Gryan Stoutmantle. At Sentinel Hill in Westfall, Gryan Stoutmantle leads the People's Militia. A paladin of the Silver Hand, he came home from Lordaeron to defend his birthplace after Stormwind's crown left it to banditry. Gryan Stoutmantle first served far from Westfall. As a young man, he traveled north to Lordaeron and took vows as a Knight of the Silver Hand. He endured the horrors of the Third War there. Then word reached him that his native province was falling into lawlessness, overrun by organized brigands and abandoned by the crown. Gryan left the northern fronts to defend honest farmers, resolved that Westfall would not fall as the north had. When Gryan returned, Westfall had almost no defenders. Royal neglect and political paralysis in the House of Nobles kept Stormwind from sending garrison troops. So Gryan formed the People's Militia at Sentinel Hill, gathering local farmers, sentries, and traveling mercenaries into a volunteer defense corps.\n\nThe militia holds a precarious line against the Defias Brotherhood, riverpaw gnolls, and hostile mechanoids. Even when nearby Lakeshire pleads for aid, Gryan cannot spare reinforcements.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gryan-stoutmantle-d0efd7f99964a591d522/1-0000.mp3", duration = 68.1534694, start = 0},
  },
}
P.transport["npc:guard-thomas"] = {
  hash = "93d9d7",
  fullHash = "93d9d7",
  text = "Guard Thomas. At the bridge west of Eastvale Logging Camp, Guard Thomas watches Elwynn’s eastern frontier. He guards local workers from wild predators and murlocs for the Stormwind Army. Guard Thomas holds a quiet but exposed post at the stone bridge over the river toward Eastvale Logging Camp. Aggressive creatures shelter in the woods nearby, and the logging workers depend on Stormwind’s guard for protection. With the army stretched thin, Thomas relies on travelers to help keep order and carry messages to central command.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_guard-thomas-4c982e51749aed95a632/1-0000.mp3", duration = 31.3991837, start = 0},
  },
}
P.transport["npc:gwennyth-bly-leggonde"] = {
  hash = "35d7c2",
  fullHash = "5fe1f3",
  text = "Gwennyth Bly'Leggonde. Along Darkshore's coast, Gwennyth Bly'Leggonde watches the tides and what they leave behind. From Auberdine, the night elf sends travelers to examine strange sea creatures and massive turtles found dead on the northern beaches. Gwennyth Bly'Leggonde keeps watch over the coast from her home in Auberdine. While others in town tend to the forest or shipping across the Veiled Sea, she follows the shoreline. Lately, the tides have carried the remains of huge sea creatures onto the sands.\n\nShe asks travelers to search the beaches and bring back skeletal samples. With them, she hopes to learn what is happening in the waters offshore. North and south of Auberdine, more sea creatures and ancient sea turtles are washing ashore. Gwennyth asks travelers to inspect the bodies and bones. She hopes to learn what drove the creatures onto the beaches or killed them, and to understand the danger in the waters off northern Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gwennyth-bly-leggonde-58742b8ce3a41bb59438/1-0000.mp3", duration = 54.4914286, start = 0},
  },
}
P.transport["npc:high-executor-darthalia"] = {
  hash = "bbc7c6",
  fullHash = "356b19",
  text = "High Executor Darthalia. At Tarren Mill, High Executor Darthalia directs the Forsaken war in Hillsbrad. Under Lady Sylvanas Windrunner and Varimathras, she targets Southshore and the Syndicate. From Tarren Mill, High Executor Darthalia commands Forsaken forces. She works to contain the human forces in Southshore and hunt Syndicate brigands across the Hillsbrad Foothills. Every Forsaken offensive in southern Hillsbrad passes through her command. High Executor Darthalia follows orders from Lady Sylvanas Windrunner and Varimathras, the Undercity's leaders. She directs the war across Hillsbrad through scouting and strikes against human leaders. Bounties target outlaws who threaten Forsaken control of northern Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_high-executor-darthalia-bb7ac7fb0eec53a2d400/1-0000.mp3", duration = 43.8073469, start = 0},
  },
}
P.transport["npc:high-priestess-laurena"] = {
  hash = "7a8e40",
  fullHash = "7e2ff7",
  text = "High Priestess Laurena. At Stormwind's Cathedral of Light, High Priestess Laurena trains human priests in devotion and arcane wards. High Priestess Laurena holds senior rank in the Church of the Holy Light. She serves in Stormwind City's Cathedral of Light, the heart of the faith. Archbishop Benedictus leads the Church. Behind the central altar in the cathedral sanctuary, High Priestess Laurena mentors aspiring priests. Acolytes who show dedication and piety come to her for deeper study. She teaches sacred boons such as Desperate Prayer and defensive spells that turn enemy arcane magic against its wielders. When her students have learned all she can teach, she sends them to other master priests across the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_high-priestess-laurena-5c2c05c250d6702ff822/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["npc:illiyana"] = {
  hash = "fbcce9",
  fullHash = "6f1dd7",
  text = "Illiyana. Near the Shrine of Aessina, Illiyana patrols the woods of southwestern Ashenvale. This ancient dryad guards the woodland against corruption and calls on Alliance champions to drive back the satyrs. Illiyana, one of Cenarius's daughters, patrols the woods of southwestern Ashenvale. Dryads live in peace, yet defend wild lands fiercely. As corruption spreads through the woodland, she guards sacred relics and groves. She keeps watch over nature's primal sanctity. Satyrs threaten the glades and Illiyana's dryad sisters. Twisted by demonic corruption, these creatures seek to taint the woods. Illiyana calls on travelers to slay them and recover lost relics, including the Branch of Cenarius. So the woodland may remain free of demonic taint.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_illiyana-3f605c566c3281262cca/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["npc:iverron"] = {
  hash = "5cc0e2",
  fullHash = "5cc0e2",
  text = "Iverron. In Shadowglen, Iverron lies stricken by spider venom. His plight points to a growing corruption within Teldrassil. Webwood spiders bit Iverron beneath Shadowglen’s quiet canopies. Their venom left the young night elf unable to reach safety alone. Once, the spiders shared the glade in peace. Now they grow more aggressive.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_iverron-5991a112ecf829fff1b9/1-0000.mp3", duration = 21.3942857, start = 0},
  },
}
P.transport["npc:jaina-proudmoore"] = {
  hash = "775d87",
  fullHash = "1d0d4c",
  text = "Jaina Proudmoore. On Theramore Isle, Jaina Proudmoore works to preserve peace between the Alliance and the New Horde. Once a gifted student of Dalaran’s Kirin Tor, she led Lordaeron’s survivors across the Great Sea and now rules the island as its most powerful human sorceress. Jaina Proudmoore, daughter of Grand Admiral Daelin Proudmoore of Kul Tiras, showed an early gift for magic. In Dalaran, she studied under Archmage Antonidas. During the Third War, she investigated the Plague of Undeath with Prince Arthas Menethil and witnessed Lordaeron’s fall.\n\nThen the Prophet Medivh warned her of the coming danger, and she gathered human survivors to sail west for Kalimdor. There, Jaina’s forces joined Thrall’s Horde and the night elves. Together they stood at Mount Hyjal, defeated Archimonde, and broke the Burning Legion’s invasion. After the Legion’s defeat, Jaina founded Theramore, an island citadel off the coast of Dustwallow Marsh. It became the Alliance’s main stronghold in southern Kalimdor. Her commitment to peace faced its greatest test when her father came seeking vengeance against the orcs.\n\nJaina would not join his war. She stood aside as Thrall’s forces killed the Grand Admiral, preventing another devastating conflict in Kalimdor. Now Jaina rules Theramore and speaks for coexistence. She works closely with Warchief Thrall while holding the Alliance’s ground amid rising local tensions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jaina-proudmoore-a04ae857731b305228a6/1-0000.mp3", duration = 87.3012245, start = 0},
  },
}
P.transport["npc:je-neu-sancrea"] = {
  hash = "000978",
  fullHash = "000978",
  text = "Je'neu Sancrea. At Zoram'gar Outpost, Je'neu Sancrea watches the Ashenvale coast for signs of dark unrest. This Darkspear shaman sends Horde adventurers to seek corruption beneath the waves at Blackfathom Deeps. From Zoram'gar Outpost, Je'neu Sancrea keeps watch over the dangerous Zoram Strand. The Earthen Ring works to keep Kalimdor's elements in harmony, while he watches this coast. Dark tremors and unnatural tides stir near the ruined temple of Blackfathom Deeps. His shamanic duties bind him to the Earthen Ring, yet his Darkspear ties and loyalty to Thrall's Horde lead him to work only with Horde champions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_je-neu-sancrea-68fc22937e1c8b9b52b5/1-0000.mp3", duration = 39.8367347, start = 0},
  },
}
P.transport["npc:jern-hornhelm"] = {
  hash = "cefa88",
  fullHash = "696607",
  text = "Jern Hornhelm. In Thelsamar, Jern Hornhelm keeps the Explorers' League supplied and its messages moving. He coordinates deliveries between the town, Ironforge, and Loch Modan's deeper dig site, while travelers carry supplies and progress reports across the region. From Thelsamar, Jern Hornhelm sends supplies to Loch Modan's dig sites. Dwarven scholars and field teams search the wilderness for their ancestral past, and their work depends on steady deliveries of resources and tools. Jern also makes sure messages reach the active digs. Jern Hornhelm connects field archaeologists with the Explorers' League leadership in Ironforge's Hall of Explorers. Ironband's Excavation needs blasting powder, equipment, and regular dispatches to keep its work moving. Jern asks trusted travelers to carry supplies and reports along trogg-infested roads, so the dig can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jern-hornhelm-b756aeecab70e735e404/1-0000.mp3", duration = 53.0285714, start = 0},
  },
}
P.transport["npc:jitters"] = {
  hash = "6f0f03",
  fullHash = "6f0f03",
  text = "Jitters. In western Duskwood, Jitters shelters alone among Raven Hill's ruins. He depends on travelers for food and watches the shadows for danger. At Raven Hill, Jitters fears the predators along Duskwood's western trails. He depends on travelers for food and keeps watch for danger. Long ago, his habit of flinching and leaping clear of sudden threats earned him his name. The fear comes from horrors he faced himself.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jitters-f88edb543f6c433f2af6/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["npc:jonathan-carevin"] = {
  hash = "8a87dd",
  fullHash = "8a87dd",
  text = "Jonathan Carevin. In Darkshire, Jonathan Carevin leads his family against the dangers gathering in Duskwood. They hunt undead, worgen, demons, and heretics beyond the Night Watch's patrols. The Night Watch guards Darkshire and patrols its roads. Jonathan Carevin believes defense alone cannot keep the township safe. So he hunts the unholy creatures roaming Duskwood with his family and allies such as Calor. In the name of the Light, they pursue demons, undead, and heretics across the region.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jonathan-carevin-fff6bddf3863876fff07/1-0000.mp3", duration = 28.8130612, start = 0},
  },
}
P.transport["npc:jordan-stilwell"] = {
  hash = "d0b3a0",
  fullHash = "b0a7c4",
  text = "Jordan Stilwell. Outside Ironforge’s gates, Jordan Stilwell tends his forge in Dun Morogh. Once expected to join the Church of the Holy Light, he followed his father into smithing and learned from Bailor Stonehand. Now his craft arms paladins across the Alliance. Jordan Stilwell was expected to take holy vows and become a paladin in the Church of the Holy Light. Instead, he followed his father into smithing and took up his father’s enchanted hammer. Bailor Stonehand, a dwarven blacksmith, helped him refine his craft. Jordan remains deeply faithful to the Light and puts his skill to work for champions who fight in its name. Jordan once worked as a smith at Baron Silverlaine’s keep in Silverpine Forest. Then Archmage Arugal unleashed feral worgen upon the fortress and made it Shadowfang Keep. Jordan escaped the bloodshed, leaving his forge and former home behind. In time, he found refuge among the dwarves of Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jordan-stilwell-501d5705ce1f7bad6a1c/1-0000.mp3", duration = 55.1444898, start = 0},
  },
}
P.transport["npc:kaela-shadowspear"] = {
  hash = "3bcc5f",
  fullHash = "2a41cd",
  text = "Kaela Shadowspear. Southwest of Windshear Crag, Kaela Shadowspear watches the Stonetalon wilderness as tensions rise. She works with fellow sentinels while new disruptions trouble the land. Kaela Shadowspear watches the passes southwest of Windshear Crag. The Horde presses into the Stonetalon Mountains, while goblin operations exploit the land's natural bounty. Beside Gaxim Rustfizzle, a gnome, she tracks threats reaching farther into night elf ancestral territory. Violence against nature has stirred the elementals and harmed the forest's ancient guardians. Kaela sends travelers to face the raging spirits and seeks what has corrupted the wounded treants who once guarded the Vale. She strives to restore peace before the land is scarred beyond repair.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kaela-shadowspear-6b1993389c9def0fde18/1-0000.mp3", duration = 45.9755102, start = 0},
  },
}
P.transport["npc:laurna-morninglight"] = {
  hash = "10684d",
  fullHash = "1ff054",
  text = "Laurna Morninglight. In Dolanaar, Laurna Morninglight guides young priests as threats gather in Teldrassil. Devoted to the Sisterhood of Elune, she teaches acolytes from Shadowglen healing and the rites of Elune. In Dolanaar, Laurna Morninglight guides young priests from Shadowglen. As the new initiates travel farther into Teldrassil, she helps them deepen their bond with Elune. Her lessons join healing with defensive rites, skills needed as the wild grows more hostile. Among the kaldorei, priests follow Elune rather than the Holy Light revered by humans and dwarves. Laurna sends her students for sacred robes and to heal a wounded Sentinel. Through these rites, acolytes learn that the Mother Moon grants power to preserve and mend the kaldorei people.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_laurna-morninglight-62997d0dade54e6d105c/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["npc:lieutenant-farren-orinelle"] = {
  hash = "fb6a56",
  fullHash = "87b4fe",
  text = "Lieutenant Farren Orinelle. At Southshore's inn, Lieutenant Farren Orinelle leaves his duties to others and longs for a transfer south. Marshal Redpath has sent him to deal with the murlocs along the coast. Lieutenant Farren Orinelle spends his days at Southshore's inn, far from the Stormwind he favors. Sent north from Stormwind City, he finds Hillsbrad's contested shores a poor fit. He drinks and grumbles instead of patrolling the fields or planning defenses with Marshal Redpath. He waits for orders that will send him south. Marshal Redpath has tasked Lieutenant Farren Orinelle with clearing murlocs from the nearby shoreline. Orinelle leaves the muddy coast to passing travelers, asking them to kill the creatures and bring proof. He hopes their work will satisfy his superiors and speed his return to Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lieutenant-farren-orinelle-dad4ef69241c61c2f2b2/1-0000.mp3", duration = 47.2555102, start = 0},
  },
}
P.transport["npc:lord-ello-ebonlocke"] = {
  hash = "7891a4",
  fullHash = "ee883d",
  text = "Lord Ello Ebonlocke. At Darkshire's Town Hall, Lord Ello Ebonlocke works to keep order as danger grows. Stormwind gives little aid, and horrors press in from the surrounding woods. Lord Ello Ebonlocke governs Darkshire from the Town Hall as danger closes around the settlement. Darkshire was once part of the prosperous rural haven called Grand Hamlet. Now perpetual shadow hangs over it, while ravenous ghouls, skeletal abominations, and feral beasts press against its borders. Ello leads the Council of Darkshire and struggles to keep the remnants of civic life working. Stormwind offers little help as the town fights to endure. Darkshire depends on local volunteer militias like the Night Watch because Stormwind's garrison will not spare soldiers for the borderlands. His relative, Althea Ebonlocke, commands the Night Watch. Magistrate Solomon of Lakeshire asks for reinforcements against Blackrock orcs, but Lord Ebonlocke cannot spare a single blade. He explains to messengers from Redridge that sending guards beyond the forest's edge would leave Darkshire's homes open to the surrounding evils.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-ello-ebonlocke-6fbda3016995968bdf80/1-0000.mp3", duration = 67.3436735, start = 0},
  },
}
P.transport["npc:madame-eva"] = {
  hash = "bbe24c",
  fullHash = "fb6287",
  text = "Madame Eva. In Darkshire, Madame Eva reads the cards for those troubled by Duskwood’s dark mysteries. She practices ancient divination and cartomancy, and is often the first in town to sense unnatural disturbances. Townspeople and travelers seek her help and the occult charms she makes against the creeping dark. Madame Eva reads cards and keeps ancient folk rituals in Darkshire. Many in Stormwind’s cathedral would look on her ways with suspicion. Yet Duskwood is troubled by feral beasts, the undead, and darker horrors. Desperate townspeople and visiting adventurers come to her for eerie insight. Madame Eva is devoted to her family, including her granddaughter Alyssa Eva and young Lohgan. When her cards warn of dark omens threatening Alyssa, Eva calls on passing wanderers to search the woods. They must uncover long-buried tragedies before history can repeat itself. Madame Eva’s knowledge reaches beyond cards to ritual craft and warding. She spins Ghost Hair Thread from a spirit’s hair and makes folk relics such as the Totem of Infliction. Few in town understand the strange twilight logic of Duskwood’s restless spirits as well as Eva does.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_madame-eva-4be1e9301b06b34c90db/1-0000.mp3", duration = 71.1836735, start = 0},
  },
}
P.transport["npc:maggran-earthbinder"] = {
  hash = "8ab025",
  fullHash = "84f7ec",
  text = "Maggran Earthbinder. At Sun Rock Retreat in the Stonetalon Mountains, Maggran Earthbinder leads the camp's defense. Cairne Bloodhoof sent the battle-worn tauren there to guard the Horde outpost. High Chieftain Cairne Bloodhoof sent Maggran Earthbinder to the Stonetalon Mountains to lead Sun Rock Retreat. Countless skirmishes and bloody campaigns have hardened him, taking from him some of the gentleness natural to his people.\n\nThe outpost was also meant to give Maggran respite. Its warm winds and mountain sunshine might ease his battle-worn spirit. Peace remains scarce in Stonetalon. From Sun Rock Retreat, Maggran coordinates defenses against Bloodfury harpies nesting in the peaks and gathers fighters to face predators across the crags.\n\nMaggran once survived an ambush by the giant spider Besseleth, and knows how deadly the wilderness can be. He often enlists travelers to kill regional predators before they overrun the outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maggran-earthbinder-f59e70103408823701dd/1-0000.mp3", duration = 55.4057143, start = 0},
  },
}
P.transport["npc:magistrate-solomon"] = {
  hash = "202af0",
  fullHash = "079f5e",
  text = "Magistrate Solomon. In Lakeshire, Magistrate Solomon pleads for help as gnolls and orcs close in. From the town hall, he governs local affairs, but Stormwind is distracted and sends no aid. Magistrate Solomon governs Lakeshire as danger closes around the town. Redridge and Shadowhide gnolls prowl the hills, while Blackrock orcs descend from the north in organized warbands. Solomon and Marshal Marris work to keep order and gather a defense. Yet Lakeshire's guards and militia are stretched to their limit. Magistrate Solomon has sent messengers to Westfall, Darkshire, and Stormwind, pleading for aid. The replies bring little hope. Westfall struggles under the Defias Brotherhood, and Duskwood faces its own creeping terrors. Stormwind City refuses to send troops to the eastern frontier. Lakeshire must defend itself.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magistrate-solomon-8aa31e73f3e8de307d40/1-0000.mp3", duration = 52.1142857, start = 0},
  },
}
P.transport["npc:magni-bronzebeard"] = {
  hash = "5cea49",
  fullHash = "af70df",
  text = "Magni Bronzebeard. In Ironforge, Magni Bronzebeard bears his people's grief and political strain. Lord of Ironforge, Thane of the Bronzebeard clan, and ruler of Khaz Modan, he is a veteran of the Second War who champions dwarven archaeology across Azeroth. Magni Bronzebeard grew up the eldest of three brothers, knowing the mountain would one day be his to rule. When the Horde invaded during the Second War, he held Ironforge behind its impenetrable gates. Once the siege broke, he pledged Khaz Modan to the Alliance of Lordaeron. In the peace that followed, Magni welcomed his gnomish allies after Gnomeregan fell. He gave High Tinker Gelbin Mekkatorque and the refugees sanctuary beneath the mountain.\n\nMagni then sought to unite the fractured northern and southern kingdoms. He asked Mekkatorque to build the Deeprun Tram, an unprecedented route beneath the earth that connects Ironforge directly to Stormwind. Magni carries deep sorrow beneath his regal bearing. During the Third War, word came from Northrend that his beloved younger brother, Muradin, had perished on Prince Arthas Menethil's expedition. Grief overwhelmed Magni, but he and his youngest brother, Brann, remained steadfast in their duty to the dwarven people. Magni still rules wisely, with that loss weighing upon him. Magni has turned dwarven society from commercial mining toward the unearthing of ancient history. Strange titan relics found deep beneath the earth inspired him to found the explorers' league with his surviving brother, Brann Bronzebeard. Dwarven dig sites now span the continents, from Dun Morogh to Kalimdor, as the League seeks the truth of the dwarves' fabled origins.\n\nPeace at home remains fragile. Magni's daughter, Princess Moira, has gone missing, believed kidnapped by the hated Dark Iron clan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magni-bronzebeard-ad07615f9275e9dcdc9e/1-0000.mp3", duration = 109.505306, start = 0},
  },
}
P.transport["npc:makaba-flathoof"] = {
  hash = "60580d",
  fullHash = "60580d",
  text = "Makaba Flathoof. At Camp Aparaje, Makaba Flathoof grieves for the home the Grimtotem took from him. Now he seeks Horde champions to strike back and keep his family safe. Makaba Flathoof grieves for Camp Aparaje, his home in the Stonetalon Mountains. Without warning, the Grimtotem clan struck and laid the settlement low. Many tauren seek peace and unity under Cairne Bloodhoof. Yet the Grimtotem spread discord and violence, leaving Makaba among the displaced and grieving survivors.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_makaba-flathoof-7ab207b2dfcbde054b22/1-0000.mp3", duration = 30.6677551, start = 0},
  },
}
P.transport["npc:malfurion-stormrage"] = {
  hash = "39207b",
  fullHash = "a6f4e8",
  text = "Malfurion Stormrage. In Darnassus, the kaldorei wait for Malfurion Stormrage to wake from his coma in the Emerald Dream. First among mortal druids, he helped defeat the Burning Legion in the War of the Ancients and the Third War. His people honor him as Shan'do, their honored teacher, and look to his return for guidance. Ten thousand years ago, Malfurion Stormrage turned from the arcane to nature. Before the Great Sundering broke ancient Kalimdor, he studied under Cenarius, the demigod. As Queen Azshara and her Highborne delved into the Well of Eternity's power, Malfurion became Azeroth's first mortal druid. He feared what that power could bring. His fears proved true when Azshara's sorcery opened a way for Sargeras and the Burning Legion, beginning the War of the Ancients. Malfurion Stormrage fought to drive the demons back and close the portal above the Well of Eternity. Cenarius, Tyrande Whisperwind, and his twin brother Illidan fought beside him. After the world shattered, he led the druids into the Emerald Dream to rebuild and protect Azeroth's living world.\n\nTen thousand years later, Tyrande woke Malfurion to face Archimonde in the Third War. At Mount Hyjal, he rallied the forest spirits and shattered the Burning Legion once more. After the Third War, Malfurion Stormrage returned to sleep in Moonglade, seeking the Emerald Dream and strength for his spent power. His spirit never returned to his body, leaving him in an unnatural coma. In Darnassus, Archdruid Fandral Staghelm carries the Cenarion Circle's duties of leadership. Tyrande and the sisterhood wait for their Shan'do to wake.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_malfurion-stormrage-449ea69183574bef4e84/1-0000.mp3", duration = 100.466939, start = 0},
  },
}
P.transport["npc:marshal-dughan"] = {
  hash = "4f65b1",
  fullHash = "4bcf42",
  text = "Marshal Dughan. In Goldshire, Marshal Dughan holds the roads against threats from the mines and woods. He commands Stormwind's small army detachment, stretched thin by kobolds, gnolls, and bandits. To guard the town and nearby farms, he depends on independent adventurers. From Goldshire, Marshal Dughan directs Elwynn Forest's defense outside the Lion's Pride Inn. Stormwind's soldiers are tied up elsewhere as trouble grows in the woods. Kobolds crowd the mines, gnolls gather along the riverbanks, and highwaymen harass travelers on the King's Road. With too few footmen, Dughan sends new recruits to reinforce outposts and scout dangerous ground. Kobolds overrun Fargodeep and Jasperlode Mines, threatening Goldshire's mineral supply. West of town, Hogger's Riverpaw gnolls press against Westbrook Garrison. Eastward, Guard Thomas reports vicious murlocs killing patrols along the river. Dughan has too few soldiers to meet each threat, so he needs capable mercenaries to help contain them.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marshal-dughan-067eab35359f4aa5f0b2/1-0000.mp3", duration = 61.1787755, start = 0},
  },
}
P.transport["npc:marshal-marris"] = {
  hash = "f98ee4",
  fullHash = "7603d8",
  text = "Marshal Marris. At Lakeshire's bridge, Marshal Marris rallies a thin guard against the Blackrock advance. With Stormwind's army absent, he calls on visiting fighters to slow the orcs in the Redridge Mountains. Gnolls press from the west and the Blackrock clan from the east. Marshal Marris holds the guard line at Lakeshire's main bridge, though supplies run low and his soldiers are stretched thin. Stormwind has sent no royal reinforcements, so Marris must keep the town from being overrun. Marshal Marris knows defense alone cannot save Redridge. He orders strikes on the orc camps, sending fighters against Blackrock warriors and shadowcasters. Then they must face Tharil'zun, the commander holding the ruins of Stonewatch Keep. Marris means to break the orcs' command before they overwhelm Lakeshire.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marshal-marris-0a4c197bf8218ddf1175/1-0000.mp3", duration = 48.1959184, start = 0},
  },
}
P.transport["npc:marshal-mcbride"] = {
  hash = "25c67b",
  fullHash = "3f62df",
  text = "Marshal McBride. At Northshire Abbey, Marshal Douglas McBride turns to new recruits as kobolds threaten the valley's farms and mines. He commands Stormwind's garrison there, the army's authority in Northshire. Marshal McBride has only a handful of sworn guards to keep the valley peaceful and protect its food and resources. Unrest across the kingdom has left military garrisons short of soldiers. Green recruits arrive seeking training under the abbey's masters, so McBride puts them to work defending the valley. Kobolds grow more aggressive around Northshire. They spread through the woods and seize Echo Ridge Mine, an important local resource. With regular soldiers scarce, McBride calls on paladins, warriors, and other novices to drive back the tunneling kobolds. He needs them to learn how far the infestation reaches before the valley is cut off.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marshal-mcbride-aa2a1828b5c43bb57c2d/1-0000.mp3", duration = 51.3828571, start = 0},
  },
}
P.transport["npc:mathias-shaw"] = {
  hash = "43d149",
  fullHash = "1d3977",
  text = "Mathias Shaw. In Old Town, Mathias Shaw directs SI:7, Stormwind’s covert intelligence agency. He sends spies and scouts from the shadows to guard the realm against conspiracies within and horrors beyond. Mathias Shaw leads Stormwind’s spies and assassins from SI:7’s hidden headquarters behind the barracks in Old Town. His covert network reaches across the Eastern Kingdoms and beyond. Loyal to the House of Wrynn, Shaw weighs each threat with care. Unseen daggers and stolen messages defend Stormwind as surely as armor and palace guards. Mathias Shaw watches threats beyond the unrest in Westfall and Elwynn. Reports of strange Forsaken operations in the Eastern Plaguelands led him to send five of his finest agents to investigate. Only one returned alive, babbling about “Nathanos” and a “Blightcaller” before dying in his sleep days later. Shaw now depends on trusted champions to go where his scouts vanish and uncover the dangers gathering at the kingdom’s borders.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mathias-shaw-30ef571f998f31058784/1-0000.mp3", duration = 59.2718367, start = 0},
  },
}
P.transport["npc:mathrengyl-bearwalker"] = {
  hash = "9779ca",
  fullHash = "f6465b",
  text = "Mathrengyl Bearwalker. From Darnassus, Mathrengyl Bearwalker guides Alliance druids through spiritual trials and the art of shapeshifting. Once Fandral Staghelm's direct assistant, he now helps young druids serve across Kalimdor. In the Cenarion Enclave of Darnassus, Mathrengyl Bearwalker guides Alliance druids through their first rites. A respected elder of the Cenarion Circle, he sends initiates to commune with Moonglade and judges when they are ready to take animal forms. He remembers his own bewildering communion with the Great Bear Spirit. Before they enter the path of the Druid of the Claw, he asks each initiate to test their spirit against Lunaclaw, the sacred moonkin. For many years, Mathrengyl has served as Fandral Staghelm's second. He tends the Cenarion Circle's daily affairs and finds recruits for the Archdruid's plans. When Fandral sought great stores of morrowgrain, Mathrengyl arranged for returning adventurers to gather it. In private, he admitted unease about the plant's unnatural essence.\n\nMathrengyl also coordinates Alliance responses to calls from Moonglade and handles the Circle's delicate politics. Meanwhile, Fandral turns his attention to southern Kalimdor. Mathrengyl thinks more openly than Fandral Staghelm, whose pride and disdain for other races are well known. Relics from Mulgris Deepriver reached Darnassus after the druid died fighting the Scourge in the Western Plaguelands. Mathrengyl was moved to learn that the investigator was a tauren. The Cenarion Circle shares one mission, he reflected, and tauren may not have strayed as far from Cenarius's teachings as Fandral claims.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mathrengyl-bearwalker-6190d3e535aa53f1ae0b/1-0000.mp3", duration = 97.5934694, start = 0},
  },
}
P.transport["npc:motega-firemane"] = {
  hash = "3326d7",
  fullHash = "3326d7",
  text = "Motega Firemane. At Whitereach Post, Motega Firemane studies the beasts of Thousand Needles. A serpent spirit’s vengeance and his young assistant’s mishaps keep drawing him from his work. Motega Firemane came south to Thousand Needles four years after the Third War. He studies the beasts that survive among its towering mesas. His young assistant, Pao'ka Swiftmountain, came with him, though Pao'ka’s protective father had been reluctant to let him leave Mulgore. Motega made camp at Whitereach Post with Kanati Greycloud. He hoped to observe nature in peace, but dangers on the canyon floor often force him to fight for survival.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_motega-firemane-3f08296a423871f5205a/1-0000.mp3", duration = 36.9893878, start = 0},
  },
}
P.transport["npc:onyxia"] = {
  hash = "3dd29c",
  fullHash = "3dd29c",
  text = "Onyxia. In Dustwallow Marsh, Onyxia tends her brood and schemes to bring the mortal realms under black dragonflight rule. She is Deathwing’s daughter, while her brother Nefarian gathers armies in Blackrock Spire.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_onyxia-cebdc01b29f10adb7827/1-0000.mp3", duration = 11.8595918, start = 0},
  },
}
P.transport["npc:orgrim-doomhammer"] = {
  hash = "5d6780",
  fullHash = "f63856",
  text = "Orgrim Doomhammer. During the Second War, Orgrim Doomhammer led the Old Horde as its supreme Warchief. He became one of history’s greatest orc warriors. He died freeing the internment camps in the Arathi Highlands, but his legacy lives on in Orgrimmar and through Thrall, who inherited his warhammer and black plate armor. Orgrim Doomhammer rose from second-in-command to become Chieftain of the Blackrock clan. Gul'dan offered him demonic blood, but Orgrim refused and kept his doubts hidden beneath fierce loyalty. Near the end of the First War, he turned against the Shadow Council after its treachery and the murder of his childhood friend Durotan.\n\nOrgrim slew Blackhand in honorable combat and took the mantle of Warchief. He purged Gul'dan's warlocks and led the Horde across the Eastern Kingdoms during the Second War. A devastating strategist, he drove human kingdoms to the brink of ruin. Gul'dan's betrayal split his forces, and Orgrim was defeated and captured outside Blackrock Spire. Orgrim Doomhammer escaped human captivity and lived in hiding until he met Thrall, Durotan's orphaned son. The young shaman's vision gave Orgrim new purpose, and he rallied the remaining orcish clans to storm the internment camps and free their people.\n\nDuring a fierce battle at an encampment in the Arathi Highlands, a lance struck the Warchief from behind. As he lay dying, Orgrim gave Thrall his black plate armor, his ancestral weapon, the Doomhammer, and the title of Warchief. The liberated outpost was renamed Hammerfall in his honor, and the newly founded capital in Durotar was named Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orgrim-doomhammer-5bb480612b6f9c1e0aae/1-0000.mp3", duration = 96.0522449, start = 0},
  },
}
P.transport["npc:ozzie-togglevolt"] = {
  hash = "f63baa",
  fullHash = "b2ac14",
  text = "Ozzie Togglevolt. In Kharanos, Ozzie Togglevolt works with Razzle Sprysprocket to find a cure for the leper gnomes of Gnomeregan. Their research continues among the snowy hills of Dun Morogh. Ozzie Togglevolt was deep inside Gnomeregan when catastrophe struck. Toxic fallout filled the corridors to stem the trogg invasion. Ozzie stood beside Gnoarn when a sudden radioactive discharge changed Gnoarn forever. Ozzie escaped to the surface and reached Dun Morogh alive, but the disaster stayed with him. In Kharanos, Ozzie spends his days tinkering with Razzle Sprysprocket. Their work is personal. They seek a way to reverse the mutagenic fallout from their lost home and cure the suffering leper gnomes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ozzie-togglevolt-c33796ccb0024c510dde/1-0000.mp3", duration = 43.8857143, start = 0},
  },
}
P.transport["npc:pelturas-whitemoon"] = {
  hash = "43b038",
  fullHash = "43b038",
  text = "Pelturas Whitemoon. In Astranaar, Pelturas Whitemoon is fighting to save his gravely ill daughter, Relara. He seeks aid from herbalist Orendil Broadleaf and Alliance travelers, who search Ashenvale for sacred remedies. Pelturas Whitemoon lives in Astranaar with his young daughter, Relara. Father and daughter often gather moonstones at Fallen Sky Lake. Then Relara falls critically ill with a mysterious affliction, and Pelturas turns from their quiet days to the urgent work of saving her. Astranaar faces dangers on many fronts, but all his thoughts are on his daughter.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pelturas-whitemoon-d9512c704b39ffc3671e/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["npc:priestess-alathea"] = {
  hash = "df6c07",
  fullHash = "25b7e0",
  text = "Priestess Alathea. In Darnassus, Priestess Alathea guides night elf priests at the Temple of the Moon. Devoted to Elune, she teaches sacred rites and prepares acolytes for healing, protection, and celestial magic. Within Darnassus's Temple of the Moon, Priestess Alathea teaches and guides the Sisterhood of Elune. After leaving Shadowglen, night elf initiates come to deepen their bond with the Goddess. Alathea shares sacred knowledge with those devoted to healing, protection, and divine light. Night elf priests draw on Elune's grace, while human and dwarven priests follow the Holy Light. Alathea teaches blessings such as Stars of Elune and Elune's Grace. Under her guidance, acolytes shape starlight into swift, protective shields against the dangers facing Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_priestess-alathea-045c69a64fb541f3f8ed/1-0000.mp3", duration = 48.1959184, start = 0},
  },
}
P.transport["npc:raene-wolfrunner"] = {
  hash = "1f5ce7",
  fullHash = "163225",
  text = "Raene Wolfrunner. In Astranaar, Raene Wolfrunner directs the Sentinels as Ashenvale faces threats from the Horde and corrupted furbolg tribes. Korra, her saber cat, and Dagri, her wolf, remain close at hand. Raene Wolfrunner keeps watch in Astranaar with Korra, her saber cat, and Dagri, her wolf. As a Sentinel officer, she oversees patrols throughout Ashenvale and gathers intelligence from beyond the forest. She sends scouts such as Kaela Shadowspear into neighboring regions, including the Stonetalon Mountains. Raene works to halt the corruption spreading among Ashenvale’s native denizens. She directs campaigns against hostile furbolg tribes, including strikes on Foulweald camps that harass travelers and efforts to remove rising Thistlefur leaders. Her scouts watch for changes in furbolg behavior. Under her command, they guard local settlements and passing travelers against coordinated ambushes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_raene-wolfrunner-982bd57b7b8f192eba4e/1-0000.mp3", duration = 56.7118367, start = 0},
  },
}
P.transport["npc:rejold-barleybrew"] = {
  hash = "75d011",
  fullHash = "72cd5a",
  text = "Rejold Barleybrew. At Brewnall Village, Rejold Barleybrew keeps working toward the perfect mountain spirit. He gathers ingredients from western Dun Morogh and tests each recipe. Dwarves in Dun Morogh take brewing seriously. Rejold works in Brewnall Village, near the frozen lake of the Iceflow River. He keeps refining his blends with rare hops, mountain minerals, and pristine ice water. His aim is a stout hearty enough to warm even the stoutest dwarven warriors. Rejold seeks the right flavors for drinks such as Shimmer Stout. He sends travelers across Dun Morogh for ingredients and trades favors with the siege pilots of Steelgrill's Depot. He also arranges deliveries to thirsty patrons. So hearty ale keeps flowing along Dun Morogh's cold, trogg-plagued roads.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rejold-barleybrew-02bbe6534b2a42000184/1-0000.mp3", duration = 47.3338776, start = 0},
  },
}
P.transport["npc:rethiel-the-greenwarden"] = {
  hash = "cc96d3",
  fullHash = "cc96d3",
  text = "Rethiel the Greenwarden. In the Wetlands, Rethiel the Greenwarden calls travelers to the Green Belt. He seeks help to ease the threats disturbing the marsh’s balance. Rethiel calls on travelers who pity the Wetlands to help ease its suffering. Mosshide gnolls ravage the wildlife and burn the marsh’s living trees with crude flints. He urges travelers to hunt them and take those flints away.\n\nDiseased fen creepers also fester in the marsh waters. Rethiel asks that they be thinned, in the hope that these efforts will bring peace back to the wounded soil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rethiel-the-greenwarden-714a1de70cf9bde2bc21/1-0000.mp3", duration = 32.3657143, start = 0},
  },
}
P.transport["npc:rorian-the-dayseeker"] = {
  hash = "56d04e",
  fullHash = "840228",
  text = "Rorian the Dayseeker. In Thendal Village, young Skyborne look to Rorian the Dayseeker as they approach adulthood. He teaches them to survive, honor tradition, and serve their island home. In Thendal Village on Zephras Isle, Rorian the Dayseeker guides young Skyborne through the passage into adulthood. Under his calm instruction, fledglings face a traditional rite that marks their readiness to defend and support their island home. Rorian also directs promising fledglings toward callings suited to their talents. Aspiring warriors, hunters, rogues, mages, shamans, and druids find trainers across the isle through his guidance. When elemental disturbances trouble the island, he alerts them and teaches them to preserve its balance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rorian-the-dayseeker-2a1933dbe5fd5567c8ef/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["npc:senani-thunderheart"] = {
  hash = "720529",
  fullHash = "d1766d",
  text = "Senani Thunderheart. At Splintertree Post in Ashenvale, Senani Thunderheart tests hunters sent against the forest’s fiercest predators. Her trials hone their skill and thin the beasts near Horde territory. At Splintertree Post, Senani Thunderheart keeps the tauren hunting traditions alive in Ashenvale. Far from Mulgore’s open plains, she sends Horde hunters after the forest’s great beasts. The trials test their skill at tracking and fighting. For Senani, the hunt is an honorable challenge and a way to survive in a wild, contested land. Senani sends hunters after three feared predators: Ursangous the bear, Shadumbra the cat, and Sharptalon the hippogryph. Their tokens are a paw, a head, and a claw. Claiming them marks a hunter’s passage. It also shows respect for the land and mastery of its fiercest beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_senani-thunderheart-3d4ea13a4dfa7e12d1c4/1-0000.mp3", duration = 51.6702041, start = 0},
  },
}
P.transport["npc:senir-whitebeard"] = {
  hash = "b6272c",
  fullHash = "a18908",
  text = "Senir Whitebeard. Outside the Thunderbrew Distillery in Kharanos, Senir Whitebeard watches the threats growing across Dun Morogh. The Senate of Ironforge sent him to assess the Frostmane troll offensive and report their movements to the dwarven leadership. Senir Whitebeard brings the Senate of Ironforge's authority to Kharanos. The city's halls watch as unrest grows across Dun Morogh. Senir carries news from scouts on the snowy frontier to the lawmakers behind Ironforge's stone gates. The Frostmane trolls grow more aggressive, pressing close to dwarven settlements and roads from the frozen crags where they are displaced and desperate. Senir gathers reports on their positions, especially around their stronghold, for Ironforge's military commanders. His work is to gather intelligence, not charge into battle.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_senir-whitebeard-88b86fa726b9099011a7/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["npc:shael-dryn"] = {
  hash = "cf873a",
  fullHash = "cf873a",
  text = "Shael'dryn. At the Moonwell of Purity, Shael'dryn watches corruption spread through Ashenvale. East of Iris Lake, she gives night elf scouts and Astranaar's sentinels relics tainted by demonic and foul influences. Shael'dryn keeps watch with the night elf sentinels over Ashenvale's eastern approaches. When corruption reaches local wildlife or tainted relics threaten the land's harmony, she draws on her knowledge of nature. Her guidance helps adventurers restore spiritual balance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shael-dryn-3edfb67bbda399c4b750/1-0000.mp3", duration = 29.1004082, start = 0},
  },
}
P.transport["npc:sprite-jumpsprocket"] = {
  hash = "e8f25f",
  fullHash = "db0599",
  text = "Sprite Jumpsprocket. In Stormwind's Dwarven District, Sprite Jumpsprocket works beside gnomish and dwarven artisans. Like many gnomes who sought refuge after Gnomeregan fell, she learns engineering among fellow tinkers. In Stormwind's Dwarven District, Sprite Jumpsprocket trains as an apprentice engineer. Gnomes and dwarves work side by side there, forging metal and shaping intricate devices. The capital gives apprentice tinkers room to learn from experienced masters. Their work keeps the Alliance's everyday mechanisms and marvels in good order. After Gnomeregan fell, displaced gnomes carried their skills in tinkering, chemistry, and mechanics across Alliance lands. In Stormwind, the Dwarven District offered them a welcome refuge, with blast furnaces and workbenches at hand. Sprite Jumpsprocket shares their resolve to master engineering despite the hardships her kin have faced.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sprite-jumpsprocket-a3c03e5b6ae45af8120d/1-0000.mp3", duration = 52.9240816, start = 0},
  },
}
P.transport["npc:sten-stoutarm"] = {
  hash = "b56036",
  fullHash = "264dc1",
  text = "Sten Stoutarm. Outside Anvilmar, Sten Stoutarm keeps recruits equipped and messages moving through Coldridge Valley. Winter blizzards cut off the valley, and dangers nearby make warmth, food, and clear instructions vital. Near the tavern outside Anvilmar, Sten Stoutarm meets new dwarven and gnomish recruits. Winter blizzards cut off Coldridge Valley, and dangers lie close at hand. So Sten gives green apprentices sturdy gear to face the snow prepared. Sten gathers wolf hides for winter clothing and carries messages through Coldridge Valley. He takes dispatches through dangerous Coldridge Pass, then brings official runes, memoranda, and orders to class trainers across the basin. Troggs block the tunnels, yet young warriors, priests, and mages still need their instructions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sten-stoutarm-9ae2e57a3959ff90bd0a/1-0000.mp3", duration = 48.2220408, start = 0},
  },
}
P.transport["npc:sven-yorgen"] = {
  hash = "31c507",
  fullHash = "c97910",
  text = "Sven Yorgen. At the Hushed Bank, Sven Yorgen grieves his murdered family and seeks vengeance. With Lars, he camps on the bank’s northern edge in western Duskwood and searches for the one who ruined his home. Sven Yorgen remembers Duskwood before Medivh’s fall brought gloom to the region. Born before the First War, he worked the soil at Yorgen Farmstead in southern Duskwood for years with his wife and children. Their quiet life ended when mysterious Dark Riders raided the homestead while Sven was away. They butchered his family and left the farm a graveyard. Unable to return to his ruined home, Sven made a secluded refuge on the Hushed Bank with his friend Lars. He distrusts outsiders and asks travelers to prove their loyalty before he shares his burden. Near the devastated farmstead, Sven saw a figure skulking about. He became convinced the stranger was responsible for the massacre or tied to the sinister horsemen who destroyed his life.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sven-yorgen-2762e1ae8b4168919963/1-0000.mp3", duration = 56.6334694, start = 0},
  },
}
P.transport["npc:tallonkai-swiftroot"] = {
  hash = "14b2dd",
  fullHash = "bcf8ed",
  text = "Tallonkai Swiftroot. From Dolanaar, Tallonkai Swiftroot watches corruption spread beneath Teldrassil’s boughs. He sends young adventurers to recover enchanted relics and confront the foul forces troubling the forest. Tallonkai Swiftroot watches the woods from Dolanaar, a settlement in Teldrassil’s canopy. Like many night elves beneath the newly grown World Tree, he fears the changes around them. Wildlife acts in unnatural ways, and shadows gather at the edges of their homes. Tallonkai sends adventurers against the foul beings disturbing Teldrassil’s peace. Corrupted dream catchers threaten the druids’ sleep, while a dark malaise has made the gnarlpine furbolgs vicious. Ferocitas the Dream Eater leads corrupted Gnarlpine mystics. Tallonkai seeks to cleanse these threats and defend the Kaldorei’s fragile home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tallonkai-swiftroot-6c32abd4ea1ea208f263/1-0000.mp3", duration = 50.9126531, start = 0},
  },
}
P.transport["npc:tavernkeep-smitts"] = {
  hash = "5c14be",
  fullHash = "5c14be",
  text = "Tavernkeep Smitts. At the Scarlet Raven in Darkshire, Tavernkeep Smitts hears the town’s gossip and remembers its unsolved tragedies. His keen eye makes him a valuable contact for those seeking Duskwood’s dark history. Tavernkeep Smitts tends the Scarlet Raven’s hearth and pours drinks for weary travelers, townsfolk, and nervous Night Watch guards facing Duskwood’s perils. For years, he has been a familiar face in Darkshire, where rumors pass through his tavern each day.\n\nWhile other townsfolk stay behind locked shutters, Smitts watches who comes and goes. He notices strange patrons, hurried departures, and behavior that does not fit the town.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tavernkeep-smitts-6c2cc77238237a16eefb/1-0000.mp3", duration = 39.0269388, start = 0},
  },
}
P.transport["npc:terenthis"] = {
  hash = "4eaf43",
  fullHash = "4eaf43",
  text = "Terenthis. In Auberdine, Terenthis tracks corruption spreading into Darkshore. The Cenarion Circle sent the night elf druid from Teldrassil to learn how far it has reached and seek help from travelers and local allies. Terenthis searches Darkshore for Fel Moss and other signs of corruption. The Cenarion Circle sent him to Auberdine to follow the blight spreading from Teldrassil. Night elves fear it may break the balance of northern Kalimdor. He seeks the rot's cause and a way to stop it before it consumes the forests.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_terenthis-077ad0089c61d92e5d15/1-0000.mp3", duration = 30.1714286, start = 0},
  },
}
P.transport["npc:theocritus"] = {
  hash = "9eca2f",
  fullHash = "ca5adf",
  text = "Theocritus. At the Tower of Azora in eastern Elwynn, Theocritus watches over Stormwind's kingdom and opposes Morganth. The eccentric human archmage lives independently, apart from everyday concerns, with servants and magical scrying devices. Archmage Theocritus keeps his own stronghold in Stormwind's kingdom. He lives in the Tower of Azora, near the eastern road to Redridge. Eccentric in his habits, he enjoys a comfortable life with a large household staff. Among them are gnomish attendants and his clothier, Morley Eberlein. Though apart from local villagers' everyday concerns, his magic guards eastern Elwynn. The fallen mage Morganth is Theocritus's greatest concern. Morganth works from the Tower of Ilgalar in the nearby Redridge Mountains. Theocritus sees him as both a personal enemy and a danger to Stormwind. For months, arcane research has helped Theocritus undermine him.\n\nWith scrying devices such as the Eye of Azora, he watches Morganth's actions and probes his thoughts. He also studies the magical pendants worn by Morganth's Shadowhide gnolls, hoping an arcane pulse can turn their master's creations against him and immobilize the entire pack.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_theocritus-b72582e7910f09a8cd28/1-0000.mp3", duration = 72.3591837, start = 0},
  },
}
P.transport["npc:thyn-tel-bladeweaver"] = {
  hash = "9b1e73",
  fullHash = "9b1e73",
  text = "Thyn'tel Bladeweaver. On Darnassus's Warrior's Terrace, Thyn'tel Bladeweaver searches for the vanished Priestess Velinde Starsong. She sends trusted Alliance adventurers to seek clues to Velinde's whereabouts and the mystery of the Scythe of Elune. On Darnassus's Warrior's Terrace, Thyn'tel Bladeweaver keeps watch as a night elf sentinel. Priestess Velinde Starsong vanished without a word, and Thyn'tel will not let her trail go cold. She fears grave forces may be involved, so she sends trusted adventurers to search Velinde's belongings and learn where her journey led.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thyn-tel-bladeweaver-30538d4a8bb602f61505/1-0000.mp3", duration = 34.3510204, start = 0},
  },
}
P.transport["npc:tirion-fordring"] = {
  hash = "ef1889",
  fullHash = "e9f13d",
  text = "Tirion Fordring. Beside the Thondroril River, Tirion Fordring watches Lordaeron's tragedy unfold from exile. Once a paladin and lord of Mardenholde Keep, he lost his title and lands for honoring an oath to an enemy orc. Now he worries for his son. Before Lordaeron fell, Tirion Fordring was among its finest knights. He served as a paladin of the Knights of the Silver Hand, founded by Archbishop Alonsus Faol during the Second War. With plate, hammer, and faith in the Holy Light, he fought the Old Horde. His fellow knights revered him as a steadfast example of the Light's power. After the Second War, Tirion governed Hearthglen from Mardenholde Keep with his wife Karandra and their young son Taelan. Then he met Eitrigg, an aged orc warrior living as a hermit, and saw honor in him. Tirion promised to protect Eitrigg.\n\nWhen Alliance authorities found the orc, Tirion fought his own countrymen to keep that oath. The Alliance of Lordaeron stripped Tirion of his nobility, and the Silver Hand cast him out. He was banished, while Uther spared Karandra and Taelan from the sentence.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tirion-fordring-fe490f3e074293dd445b/1-0000.mp3", duration = 64.0522449, start = 0},
  },
}
P.transport["npc:tiza-battleforge"] = {
  hash = "0bb70b",
  fullHash = "0bb70b",
  text = "Tiza Battleforge. In Ironforge, Tiza Battleforge guides young paladins through the ways of the Holy Light. She teaches virtue, charity, and self-sacrifice, then tests initiates before they may wield its gift of resurrection. Tiza Battleforge guides paladins in Ironforge's Hall of Mysteries. Tutors across the Alliance send initiates to her for deeper study of the Light. Brandur Ironhammer sends them from Ironforge, Azar Stronghammer from Dun Morogh, and Lord Grayson Shadowbreaker from Stormwind.\n\nTiza teaches that the Holy Light asks more than skill in battle. Its servants must offer humble service, show compassion, and stand firm against the Scourge and other threats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tiza-battleforge-fe41ed72b42a2930f37c/1-0000.mp3", duration = 41.0383673, start = 0},
  },
}
P.transport["npc:tyrande-whisperwind"] = {
  hash = "d7d5ff",
  fullHash = "618a40",
  text = "Tyrande Whisperwind. From Darnassus, Tyrande Whisperwind watches over the night elves. As Elune’s High Priestess, she leads her people, who endured the War of the Ancients and the ten thousand years of the Long Vigil under her guidance with Malfurion Stormrage. Now she commands the Sisterhood of Elune and directs the Sentinel army in Kalimdor’s defense. Tyrande Whisperwind now leads the night elves as Elune’s High Priestess. Born in the ancient kaldorei empire, she grew up with the twin brothers Malfurion and Illidan Stormrage. They turned to druidism and sorcery, while she became a priestess of Elune.\n\nWhen the Burning Legion first invaded Azeroth in the War of the Ancients, she stood against it beside Malfurion. The Moon Goddess favored her, and Tyrande made the Sisterhood a fighting force. Its priestesses wielded divine healing and lunar wrath as the kaldorei faced annihilation. After the Great Sundering and the sealing of the Well of Eternity, Malfurion and the druids entered the Emerald Dream for long hibernations. Tyrande took up the lonely task of defending their recovering realm.\n\nShe formed the Sentinels, an elite band of warrior-women who patrolled Kalimdor’s forests through ten thousand years. During the Long Vigil, they watched over ancient evils and lingering demonic remnants. Tyrande kept faith in Elune as centuries passed between brief reunions with Malfurion. Tyrande now governs the kaldorei from Darnassus as the night elves take their place in the Alliance. When the Burning Legion returned during the Third War, she woke the sleeping druids to face the danger. Though she mistrusted the newly arrived orcs and humans, she helped forge a desperate coalition at Mount Hyjal. The night elves gave up their immortality at Nordrassil to destroy Archimonde.\n\nMount Hyjal still bears the scars of that battle, and Malfurion is again occupied with guarding the Emerald Dream. From the grand Temple of the Moon, Tyrande watches for Horde incursions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tyrande-whisperwind-479d5189577b3e61de26/1-0000.mp3", duration = 121.077551, start = 0},
  },
}
P.transport["npc:verner-osgood"] = {
  hash = "3bf52d",
  fullHash = "4686f1",
  text = "Verner Osgood. Outside Lakeshire’s smithy, Verner Osgood keeps the forge at work. He must meet the Stormwind Guard’s need for horseshoes, weapons, and armor while gnolls raid the hills. Verner Osgood keeps Lakeshire’s forge working, making horseshoes and other supplies for the town. The Stormwind Guard continually requisitions his stock for weapons and armor. With the kingdom’s forces stretched thin and local garrisons short on supplies, Verner bears much of the burden of equipping Redridge’s defenders. Gnoll raids threaten Verner’s work and the town’s horses. Packs ambush livestock in the Redridge hills and seize working horses that stray beyond Lakeshire. Verner recruits travelers to hunt the marauders and their packleader, Yowler.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_verner-osgood-d718139fcac81ce9be73/1-0000.mp3", duration = 44.4342857, start = 0},
  },
}
P.transport["npc:viktori-prism-antras"] = {
  hash = "9b35d0",
  fullHash = "bd7164",
  text = "Viktori Prism'Antras. Above Darkshire, Viktori Prism'Antras keeps watch on the stars. In Duskwood's gloom, he hopes a telescope will bring them into clear view. Beyond the gryphon roost, up the slope, Viktori Prism'Antras peers into Duskwood's gloom. Undead incursions, ravenous spiders, and creeping shadows surround him. Yet he looks past the suffocating canopy, hoping to build a fine telescope that brings the stars into clear focus. In the heavens, he seeks quiet refuge from the dread engulfing the hamlet. Building a delicate telescope takes work in this cursed forest. Viktori follows blueprints from his gnomish friend, Cog Glitzspinner. He asks passersby to find rare materials for crafting lenses and mechanical housings. Finely cut glass and metal lenses lie scattered across perilous ground.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_viktori-prism-antras-fe2981fc1fe6722a249f/1-0000.mp3", duration = 49.7893878, start = 0},
  },
}
P.transport["npc:warden-thelwater"] = {
  hash = "3e7700",
  fullHash = "3e7700",
  text = "Warden Thelwater. At the Stockade entrance in Stormwind, Warden Thelwater faces a prison riot. He calls for capable adventurers to stop the Defias prisoners before the uprising reaches the city above. Beneath Stormwind's canals, the Stockade holds the kingdom's most dangerous miscreants, petty thieves, and political conspirators. Warden Thelwater was charged with keeping them locked away. Then an organized revolt caught the guards off guard. The prisoners overwhelmed security and seized the cells, leaving Thelwater barricaded at the entrance as he struggles to contain an armed uprising beneath the capital's streets.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_warden-thelwater-7b3fb3839fbe414dc497/1-0000.mp3", duration = 35.6571429, start = 0},
  },
}
P.transport["npc:william-pestle"] = {
  hash = "78ce20",
  fullHash = "d7f394",
  text = "William Pestle. At the Lion's Pride Inn in Goldshire, William Pestle gathers supplies for Stormwind's apothecary. He and his brother Morgan run the shop in the Trade District. William hires travelers to find candles, kelp, and herbs. William works from the Lion's Pride Inn in Goldshire. His brother Morgan Pestle tends the counter at Pestle's Apothecary in Stormwind City's Trade District. In Elwynn Forest, William works with local gatherers to secure raw materials for the city's shops. He sends regular shipments to Stormwind, where citizens rely on restorative salves, draughts, and powders. Common garden herbs do not always meet William's needs. He hires newcomers to gather wax candles carried by Elwynn's kobolds and crystal kelp from the murlocs of Crystal Lake, just east of Goldshire. The ingredients may seem strange to those unfamiliar with alchemy. William believes they have potent virtues in a mixture.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_william-pestle-711b46a41c0937ed1336/1-0000.mp3", duration = 55.6146939, start = 0},
  },
}
P.transport["npc:wizbang-cranktoggle"] = {
  hash = "4c2b14",
  fullHash = "a7cadb",
  text = "Wizbang Cranktoggle. In Auberdine, Wizbang Cranktoggle keeps Darkshore’s buzzboxes working. The eccentric gnome engineer lives upstairs at the inn, far from the halls of Gnomeregan and Ironforge. Wizbang Cranktoggle brings Alliance ingenuity to Auberdine. The gnome engineer works on the inn’s upper floor, among tools and spare parts. The night elves here seek harmony with nature and follow ancient customs. Wizbang tackles practical mechanical problems instead, far from Kalimdor’s solemn druidic traditions. Along Darkshore’s rugged coast, Wizbang maintains a network of buzzboxes. The devices send automated reports and carry messages over long distances. Coastal weather and hostile wildlife often damage them. So Wizbang asks travelers to find parts, salvage tools such as gaffer jacks, and recover electropellers to keep the network working.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wizbang-cranktoggle-aa8172239f5beb660eda/1-0000.mp3", duration = 53.4465306, start = 0},
  },
}
P.transport["subzone:addle-s-stead"] = {
  hash = "2fbf8d",
  fullHash = "2fbf8d",
  text = "Addle's Stead. In southwestern Duskwood, Addle's Stead lies abandoned south of Raven Hill. Its first homesteaders fled long ago. Now the Defias Brotherhood uses the farm as a hidden staging ground. Addle's Stead lies in ruin beneath Duskwood's darkness. The Defias Brotherhood now uses the old farm. Agents watch the perimeter and lurk in the farmhouse, while supplies fill the barn. Shadows in southwestern Duskwood help them evade the Night Watch and Stormwind authorities.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_addle-s-stead-2cf608ee4bbcdfebf240/1-0000.mp3", duration = 27.8204082, start = 0},
  },
}
P.transport["subzone:aldrassil"] = {
  hash = "938881",
  fullHash = "938881",
  text = "Aldrassil. Young kaldorei gather beneath Aldrassil’s vast boughs in Shadowglen. Its hollowed trunk shelters trainers, merchants, and local leaders. Aldrassil shelters young night elves in Shadowglen. Ramps wind through its immense trunk, past trainers and artisans, and climb to the high roost. Tenaron Stormgrip watches over the glade’s protection from there. Beyond the tree, Teldrassil stretches across the horizon. Beneath Aldrassil’s canopy, novices learn their arts before venturing into Kalimdor’s troubled wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_aldrassil-2acd0d212fb8a316d029/1-0000.mp3", duration = 33.1755102, start = 0},
  },
}
P.transport["subzone:alexston-farmstead"] = {
  hash = "32969a",
  fullHash = "9e4a62",
  text = "Alexston Farmstead. Wild Harvest Watchers prowl the ruined fields at Alexston Farmstead. Baros Alexston grew up here before becoming Stormwind's city architect. You find Alexston Farmstead among Westfall's dry plains, abandoned like the neighboring estates. Its caretakers fled as banditry spread across the countryside. The fields have gone wild, and Harvest Watchers left to tend the crops now attack anyone near the barren farmhouse. Baros Alexston worked these fields in his youth, then left to pursue masonry and construction. He became one of Stormwind's most prominent citizens and helped design parts of the rebuilt capital. Something from his early life remains among the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_alexston-farmstead-be9f534827c4d434b137/1-0000.mp3", duration = 40.7771429, start = 0},
  },
}
P.transport["subzone:algaz-station"] = {
  hash = "4b2fd6",
  fullHash = "4b2fd6",
  text = "Algaz Station. At Algaz Station, Mountaineers keep watch over the northern road from Loch Modan to the Wetlands. South of Dun Algaz, the outpost guards the mountain pass. Dwarven Mountaineers watch the road north from Loch Modan at Algaz Station. East of North Gate Pass and south of Dun Algaz, the post guards the route between Ironforge and the northern lowlands. Trade and troops travel through the mountain tunnels, though beasts and troggs threaten the hills. The Mountaineers keep the way open and give weary travelers a place to rest, make repairs, and find martial support before entering the pass.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_algaz-station-1bbb5d0fd61a94ef2ab9/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["subzone:alterac-mountains"] = {
  hash = "851809",
  fullHash = "cd070c",
  text = "Alterac Mountains. In the Alterac Mountains, ruined settlements and bandits claim the slopes above Hillsbrad’s pastures. Once the heart of a proud human kingdom, the highlands now offer travelers little safety. The Alterac highlands once held a sovereign human nation, one of seven kingdoms born from ancient Arathor. During the Second War, King Aiden Perenolde secretly made a pact with the Old Horde. He let orcish forces cross the peaks in return for his kingdom’s safety. The Alliance of Lordaeron uncovered the betrayal and deposed him. Martial law and territorial disputes left the region divided. The Third War’s devastation left the mountains lawless. Disinherited nobles formed the Syndicate, which works from Strahnbrad’s ruins and plots to reclaim its lost dominion through sabotage and assassination. Crushridge ogres hold the shattered capital. Gnolls roam the slopes, and the magical ruins around Dalaran lie shattered. Alterac’s passes remain among Lordaeron’s most perilous paths.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_alterac-mountains-bf5961fce155642d7b54/1-0000.mp3", duration = 61.2310204, start = 0},
  },
}
P.transport["subzone:alther-s-mill"] = {
  hash = "81875d",
  fullHash = "77bf7d",
  text = "Alther's Mill. Northeast of Lakeshire, Alther's Mill lies in ruins, its old grounds haunted by scavengers and predators. Travelers bound east for Stonewatch pass this grim mark of the frontier. Alther's Mill once supplied timber to Lakeshire and nearby settlements. Its clearing northeast of Lake Everstill gave the millers access to timber in the mountains. As trouble spread through Stormwind's kingdom, the Blackrock clan descended from the heights of Stonewatch. The millers abandoned their work, leaving the timber buildings and wheel to decay. Monstrous tarantulas, carrion vultures, and raiders took the mill after its workers left. Travelers on the path to the eastern passes must skirt the shadowed grounds with care. Shadowy operatives and thieves also use the abandoned compound. Its discarded storage boxes and hidden corners give them room to practice lockpicking and carry out covert trades beyond the Lakeshire Town Watch's gaze.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_alther-s-mill-02e837fac70c174dafb9/1-0000.mp3", duration = 53.237551, start = 0},
  },
}
P.transport["subzone:amberstill-ranch"] = {
  hash = "435d18",
  fullHash = "435d18",
  text = "Amberstill Ranch. North of Gol'Bolar Quarry, Amberstill Ranch stands along the snowy road to Loch Modan. The Amberstill family tends its mountain rams and guards them from hungry predators. Across Khaz Modan, Amberstill Ranch is known for its strong mountain rams. The Amberstill family tends the stables and paddocks, training the sure-footed beasts for snowy passes and steep cliffs. The ranch supplies riding mounts and livestock. Wendigos drawn to the flock threaten the herd, and the family must fend them off.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_amberstill-ranch-4ea815bec3494386c7c4/1-0000.mp3", duration = 30.5110204, start = 0},
  },
}
P.transport["subzone:ameth-aran"] = {
  hash = "c20187",
  fullHash = "c20187",
  text = "Ameth'Aran. Broken colonnades rise from Ameth'Aran in southern Darkshore, where restless ghosts haunt the stones. Once a great Highborne city, it fell when the Well of Eternity collapsed and shattered the ancient world. Before the Great Sundering, Ameth'Aran and Bashal'Aran were twin centers of Highborne influence along the ancient coastline. Queen Azshara favored Ameth'Aran, where its ruling nobles pursued unrestrained arcane experiments. Their sorcerer, Athrikus Narassin, governed from afar in the Tower of Althalaxx. The city flourished until the Well of Eternity collapsed and tore the Kaldorei Empire apart.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ameth-aran-cda1aba3070376e5fb45/1-0000.mp3", duration = 37.6163265, start = 0},
  },
}
P.transport["subzone:angerfang-encampment"] = {
  hash = "f3e6d6",
  fullHash = "f3e6d6",
  text = "Angerfang Encampment. At Angerfang Encampment, Dragonmaw orcs gather in the central Wetlands and threaten nearby dwarven settlements. Chieftain Nek'rosh Skullcrusher leads the renegades as they prepare to strike Menethil Harbor. Dragonmaw warriors hold the marsh around Angerfang Encampment in the central Wetlands. Barricades and watchtowers guard their camp, where warriors, bonewarders, and dark spellcasters loyal to the old ways gather. From there, the clan raids travelers on the roads and menaces nearby dwarven digs, including Whelgar's Excavation Site.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_angerfang-encampment-43020756792ff9d71aae/1-0000.mp3", duration = 33.6457143, start = 0},
  },
}
P.transport["subzone:anvilmar"] = {
  hash = "f07758",
  fullHash = "8e3204",
  text = "Anvilmar. In Coldridge Valley, Anvilmar gathers young Bronzebeard dwarves and displaced gnomes to train for the road ahead. Snowy Dun Morogh surrounds the fortified outpost and its great stone forge. A great forge burns inside Anvilmar's sturdy stone walls in the northern crags of Coldridge Valley. Class mentors and supply vendors serve the outpost, while veteran mountain mountaineers drill recruits before they set out across the kingdom. Snowdrifts shelter the walls, but Frostmane trolls and wild beasts prowl the frozen valley, keeping the defenders alert. Anvilmar may take its name from High King Modimus Anvilmar. He ruled the dwarven clans before the War of the Three Hammers. Today, the garrison keeps watch and tends the forge fires as trolls and beasts roam the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_anvilmar-96737394f001c4c61071/1-0000.mp3", duration = 46.837551, start = 0},
  },
}
P.transport["subzone:astranaar"] = {
  hash = "495cf6",
  fullHash = "2f3c7a",
  text = "Astranaar. Across its island in central Ashenvale, Astranaar offers refuge to Alliance travelers as threats gather in the forest. The old forest road runs beside the settlement, where furbolgs, satyrs, and the Horde endanger the Night Elves’ hold. Wooden footbridges lead from Astranaar’s island to the mainland across the forest lake. This is Ashenvale’s largest night elven settlement, where sentinels, priests, and artisans watch over the woodland. Travelers can find an inn, traders, and an expert leatherworker. From the high perches, a flight master sends hippogryphs to distant outposts across Kalimdor. Lanterns shine over Astranaar’s quiet waters, yet the town stays ready for attack. Raene Wolfrunner and other local leaders direct patrols and defenses against the corrupted Thistlefur furbolgs advancing from the north. The Sentinels fear the furbolgs may assault the settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_astranaar-aaa73d154827548c9536/1-0000.mp3", duration = 52.715102, start = 0},
  },
}
P.transport["subzone:auberdine"] = {
  hash = "7a49b2",
  fullHash = "b034d4",
  text = "Auberdine. Ships crowd Auberdine's docks, carrying travelers between Darkshore, Teldrassil, and the Eastern Kingdoms. The night elven town is the Alliance's main port in northern Kalimdor, between the Veiled Sea and pine-covered bluffs. Auberdine stands on the Veiled Sea, the only major settlement still thriving in Darkshore. Ships sail to Stormwind Harbor and, by way of Southshore, to Menethil Harbor. Ferries cross to Rut'theran Village beneath the boughs of the World Tree. Unlike Teldrassil's secluded treetop cities, Auberdine welcomes travelers from across the sea. Lamps light its stone streets, where dwarves and gnomes mingle with merchants among low, arched timber houses. Elder Thundris Windweaver and the Auberdine Village Council govern the town. They coordinate Darkshore's defense with the local Sentinels. Auberdine is a vital trade hub, though Darnassus rarely speaks its name; memory there dwells on the great cities lost to the Sundering. Trouble presses from every side. Aggressive murlocs raid fishing boats along the strand, corrupted Blackwood furbolgs push from the south, and foul magic drifting down from Felwood agitates the wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_auberdine-068ef8b6dbd1eada0fa6/1-0000.mp3", duration = 70.922449, start = 0},
  },
}
P.transport["subzone:azurelode-mine"] = {
  hash = "98170d",
  fullHash = "d3b233",
  text = "Azurelode Mine. Southshore's militia guards the human laborers at Azurelode Mine, whose iron feeds the Alliance war effort in southwestern Hillsbrad. Just west of Southshore, Azurelode Mine cuts into the coastal ridges, beyond the open farmland. Human miners work deep underground under Foreman Bonds's watch, drawing iron for arms and armor. That iron helps Alliance defenders hold the region against the Undercity. Southshore's garrisons and town militia rely on Azurelode Mine for most of their raw iron. So Tarren Mill targets the workers and guards, seeking to break the supply lines that sustain Hillsbrad's human strongholds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_azurelode-mine-802aebdd58d36bfe1b7d/1-0000.mp3", duration = 39.1836735, start = 0},
  },
}
P.transport["subzone:ban-ethil-barrow-den"] = {
  hash = "f5f16b",
  fullHash = "de5a05",
  text = "Ban'ethil Barrow Den. Beneath Teldrassil's roots, Gnarlpine furbolgs have overrun Ban'ethil Barrow Den. The sacred chambers were made for the sleeping Druids of the Talon, whose spirits commune with the Emerald Dream. Now the den is a dangerous warren, and the druids within are at risk. Ban'ethil Barrow Den lies beneath Teldrassil's roots, with chambers above and below. Barrow dens shelter night elf druids as they sleep and send their spirits into the Emerald Dream. This den was made for the Druids of the Talon to commune with nature. Its halls once held quiet meditation, but corruption spreading through Teldrassil's wildlife reached the Gnarlpine furbolgs. They invaded and made the hollowed chambers a fortified warren. The Gnarlpine tribe has gone mad under a mysterious corruption spreading across the World Tree. Its furbolgs drove out or endangered the sleeping druids, and now guard the winding tunnels fiercely. Any night elf who approaches is attacked. Teldrassil's defenders must drive the furbolgs back to protect the vulnerable druids and the sacred relics trapped in the den's lower depths.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ban-ethil-barrow-den-26a483daded321912b14/1-0000.mp3", duration = 67.0040816, start = 0},
  },
}
P.transport["subzone:ban-ethil-hollow"] = {
  hash = "185306",
  fullHash = "185306",
  text = "Ban'ethil Hollow. Furbolgs threaten travelers in Ban'ethil Hollow, south of the road between Dolanaar and Darnassus. At the ravine's far end, a hidden entrance leads to Ban'ethil Barrow Den. Furbolgs roam the rocky descent into Ban'ethil Hollow. A strange affliction has driven them mad, and they stalk the nearby road to ambush couriers and wandering sentinels. The hollow lies just south of the road between Dolanaar and Darnassus. Here, Teldrassil's woods are not wholly safe.\n\nAt the ravine's back stands the entrance to Ban'ethil Barrow Den. Slumbering druids and ancient tunnels lie within, threatened by the maddened beasts outside.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ban-ethil-hollow-adb299c73c5082970adb/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["subzone:baradin-bay"] = {
  hash = "ab75bd",
  fullHash = "c8210d",
  text = "Baradin Bay. Baradin Bay's reefs and wrecks make every crossing perilous. The waters lie between Khaz Modan, the Wetlands, the Arathi Highlands, and southern Lordaeron. During the Second War, Kul Tiras patrolled the bay with a powerful navy. Baradin Bay joins the harbors of the Eastern Kingdoms. Menethil Harbor stands on the Wetlands shore, while Southshore lies in the Hillsbrad Foothills. Sandbanks and jagged shoals hide beneath the water. Murlocs, crocolisks, and deep-sea sharks make the passage more dangerous. Kul Tiras and the Horde fought across Baradin Bay during the Second War. Along the Wetlands coast, the broken hulls of the Kul Tiran Third Fleet lie half-submerged. They are known as the Lost Fleet. Other ships sank at Drowned Reef. Hostile spirits, salvagers, and sea beasts haunt the waters around the ruined ships.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_baradin-bay-5c1ea21c1ac9c7f25bbc/1-0000.mp3", duration = 51.8791837, start = 0},
  },
}
P.transport["subzone:bashal-aran"] = {
  hash = "fa9330",
  fullHash = "87be68",
  text = "Bashal'Aran. In northern Darkshore, Bashal'Aran's ruins draw satyrs and grells to lingering magic. A lone elven ghost remains bound by a curse centuries old. Before the Great Sundering shattered ancient Kalimdor ten thousand years ago, Queen Azshara settled favored Highborne in Bashal'Aran and its twin, Ameth'Aran. The mage Athrikus Narassin governed both towns. Their splendid markets and temples honored Elune.\n\nWhen the Well of Eternity collapsed, the cataclysm destroyed both settlements. For reasons lost to time, Athrikus used his arcane mastery to bind his second-in-command, the mage Asterion, inside a moonstone seal in Bashal'Aran. Asterion's body perished, but his ghost remained shackled to the ruined shrine. Deth'ryll satyrs and grells claim Bashal'Aran's crumbled stones. Drawn by magic lingering in the ancient masonry, they feed on its energy to strengthen their foul arts. They swarm the broken courtyards and terrorize travelers on Darkshore's forest paths.\n\nYet the creatures keep clear of the central shrine, where Asterion endures his endless vigil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bashal-aran-08e067cbc60aa4f61e3f/1-0000.mp3", duration = 70.2955102, start = 0},
  },
}
P.transport["subzone:bathran-s-haunt"] = {
  hash = "8faa1f",
  fullHash = "cb6847",
  text = "Bathran's Haunt. Forsaken herbalists harvest rare plants at Bathran's Haunt, east of the Zoram Strand in northwestern Ashenvale. Their work is withering the woodland around the ancient kaldorei ruin. Crumbling night elf pillars rise north of the Ruins of Ordil'Aran, caught in Ashenvale's thick foliage. Once a tranquil kaldorei relic, Bathran's Haunt now shelters Forsaken herbalists and their enforcers. They work among broken marble in an open-air laboratory, gathering rare woodland reagents for experiments. As they harvest, grass rots brown and blossoms wilt. Decay creeps through the grove, blighting the ancient soil. Bathran's Hair grows only among these stones, and it is a unique remedial herb. Night elf and Alliance scouts see its harvest as desecration of sacred elven soil. Forsaken herbalists seek the plant's potent properties, and the Horde has an interest in its yield. Yet the Forsaken keep their methods secret. The corrupted earth draws suspicion from outsiders and allies alike.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bathran-s-haunt-72f31d614344d44b6f92/1-0000.mp3", duration = 60.1861224, start = 0},
  },
}
P.transport["subzone:beggar-s-haunt"] = {
  hash = "534809",
  fullHash = "78505c",
  text = "Beggar's Haunt. Forsaken agents watch the eastern approaches from Beggar's Haunt, an old Stormwind tower. It stands on a hillside in northeastern Duskwood, near the mountain road to Deadwind Pass. Beggar's Haunt looks over the hills east of Manor Mistmantle. Stormwind once kept guards here to watch the kingdom's eastern approaches. As Duskwood sank into gloom, the patrols withdrew to Darkshire and left the tower to weather and ruin. Now Forsaken agents study the region from within Alliance territory. Among them are members of the Royal Apothecary Society and the Deathstalkers. A winding path behind Beggar's Haunt descends to Knight's Hollow, where a secluded pool lies beneath a waterfall. An unmarked grave rests between two hooded stone statues, like the guardians beside the Dark Portal. Nearby graves include the resting place of an Unknown Soldier. These graves recall forgotten clashes along the frontier, fought long before the Forsaken took the watchtower.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_beggar-s-haunt-27adfd35a10acd486114/1-0000.mp3", duration = 55.8497959, start = 0},
  },
}
P.transport["subzone:blackwolf-river"] = {
  hash = "544ef0",
  fullHash = "544ef0",
  text = "Blackwolf River. Through Windshear Crag, Blackwolf River carries runoff from the Venture Company's logging and industrial work. Its waters flow down from Cragpool Lake. Fed by Cragpool Lake, Blackwolf River runs through Windshear Crag. Venture Company loggers cut the surrounding woods with heavy machinery and buzzsaws. Sludge, oil, and logging waste drain into the current, carrying the cost of the company's work through the basin.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_blackwolf-river-ff1b1398bdceee6920e1/1-0000.mp3", duration = 25.5216327, start = 0},
  },
}
P.transport["subzone:blackwood-den"] = {
  hash = "02e68e",
  fullHash = "02e68e",
  text = "Blackwood Den. In southern Darkshore, Blackwood Den has fallen to the Blackwood furbolgs’ corruption. Their cave and camps, once a peaceful home near Ashenvale, now echo with madness. Volcor, a night elf scout, is trapped inside and awaits aid from Auberdine. Near the southern border of Darkshore and Ashenvale, Blackwood furbolgs hold a rocky cave and crude camps. Corruption has taken hold of the tribe, and its members attack outsiders. Deep inside the cave, the night elf Volcor is pinned down and in danger. Scouts and travelers from Auberdine are needed to help him.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_blackwood-den-065cfff0f203cc228d5b/1-0000.mp3", duration = 36.2318367, start = 0},
  },
}
P.transport["subzone:bloodtooth-camp"] = {
  hash = "55e097",
  fullHash = "55e097",
  text = "Bloodtooth Camp. In central Ashenvale, Bloodtooth Camp lies west of the Falfarren River. Ran Bloodtooth leads the corrupted furbolgs, who attack anyone approaching. Alliance scouts seek to cleanse the surrounding woodlands. Bloodtooth Camp lies southwest of the southern Moonwell and west of the Falfarren River. The furbolgs were once bound to Kalimdor’s sacred wilderness, but lingering spiritual corruption has consumed their tribe. Ran Bloodtooth commands the crude settlement. His followers attack travelers and night elven protectors alike.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bloodtooth-camp-cce979e5d5420dd2930f/1-0000.mp3", duration = 31.1640816, start = 0},
  },
}
P.transport["subzone:bough-shadow"] = {
  hash = "fcc48c",
  fullHash = "fcc48c",
  text = "Bough Shadow. In northeastern Ashenvale, Bough Shadow lies east of Forest Song beneath a colossal Great Tree. Its roots surround an ancient portal into the Emerald Dream. At Bough Shadow, the Great Tree’s roots wind around a natural crossing into the Emerald Dream. The Green Dragonflight guards the quiet grove. Emerald drakes such as Phantim and Dreamstalker circle above the canopy. Emeraldon dragonspawn and oracles patrol the swirling green portal at the tree’s base. Mortals who approach without permission are turned away.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bough-shadow-0acce133e0ce2eda3bff/1-0000.mp3", duration = 30.6416327, start = 0},
  },
}
P.transport["subzone:boulderslide-cavern"] = {
  hash = "7b4c82",
  fullHash = "7b4c82",
  text = "Boulderslide Cavern. Boulderslide kobolds dig deep in Boulderslide Cavern, at the far end of Boulderslide Ravine. They search the stone for glowing mineral formations. Boulderslide kobolds have carved a stronghold into the Stonetalon crags. They dig frantically for resonite, a rare purple crystal embedded in the stone. Its glow carries traces of earthen magic, and the kobolds turn fiercely against anyone who approaches their excavation.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_boulderslide-cavern-87cc1b194bcdeb70d8f4/1-0000.mp3", duration = 26.2530612, start = 0},
  },
}
P.transport["subzone:boulderslide-ravine"] = {
  hash = "3c8a0f",
  fullHash = "f07006",
  text = "Boulderslide Ravine. Along Webwinder Path, Boulderslide Ravine cuts through the central peaks of the Stonetalon Mountains. Horde and Alliance fighting rarely reaches this quiet pass. Rocky slopes lead toward Boulderslide Cavern, while wild mountain beasts roam the heights. Boulderslide Ravine is a narrow pass leading to a subterranean lair deep in the mountains. Loggers, night elves, and the Horde fight over timber and sacred glades elsewhere in the region, but soldiers rarely enter this narrow pass. Mountain rams and crag beasts roam its ledges and sheer walls. Cliff Stormers are among them. Prospectors watch the slopes for rich mineral veins on the way toward the deeper cavern network. Across from Boulderslide Cavern's entrance, a small cave looks over the ravine. Rough torches light weathered supply barrels and primitive tribal paintings. The designs resemble ancient tauren art. They suggest native tribes once traveled through these crags or took shelter here, long before modern conflict reached the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_boulderslide-ravine-6cc25fd2c5e5988a956b/1-0000.mp3", duration = 60.7085714, start = 0},
  },
}
P.transport["subzone:brackwell-pumpkin-patch"] = {
  hash = "91fd3a",
  fullHash = "91fd3a",
  text = "Brackwell Pumpkin Patch. Defias brigands hold Brackwell Pumpkin Patch in southeastern Elwynn Forest. The farm belonged to the Brackwell family, but now conspirators meet in its cottage and fields, where stolen mine gold arrives. Southeast of the Stonefield homestead, Brackwell's fields lie untended. The family vanished as crime spread through the area, driven away or worse. The Defias Brotherhood now occupies the sturdy cottage and overgrown fields. Beyond the reach of Goldshire's patrols, brigands regroup here. Morgan the Collector and other prominent conspirators use the isolated farm to receive illicit gold from the forest's mines.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brackwell-pumpkin-patch-4924db5946f65a921691/1-0000.mp3", duration = 36.8587755, start = 0},
  },
}
P.transport["subzone:brewnall-village"] = {
  hash = "c3ef67",
  fullHash = "c3ef67",
  text = "Brewnall Village. In Chill Breeze Valley, the Barleybrew family works on new brews and guards against wild beasts. Their camp lies near the entrance to Gnomeregan. The Barleybrew clan brews in Chill Breeze Valley, among the gnomish reaches of western Dun Morogh. They work to perfect old recipes and make the finest stout. Tents and brewing gear fill the camp, with no permanent stone buildings. As the Barleybrews test new ales, wolves and bears threaten the valley. Wandering mountaineers gather rare ingredients and help keep the area safe.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brewnall-village-a03be51650f17d332507/1-0000.mp3", duration = 32.3134694, start = 0},
  },
}
P.transport["subzone:brightwood-grove"] = {
  hash = "80ff85",
  fullHash = "80ff85",
  text = "Brightwood Grove. West of Darkshire, ruined farms and overgrown clearings shelter savage Nightbane worgen in Brightwood Grove. Brightwood Grove lies within sight of Darkshire, where ruined farms and fences mark the town's edge. Nightbane worgen make crude camps among the overgrown clearings and prowl close to town. Their presence threatens Darkshire. So the Night Watch and travelers passing through keep their numbers down to protect the settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brightwood-grove-9e8e21499d86278d0926/1-0000.mp3", duration = 27.1412245, start = 0},
  },
}
P.transport["subzone:calmbreeze-inn"] = {
  hash = "8baf22",
  fullHash = "8baf22",
  text = "Calmbreeze Inn. In Shen'dar Village and Valaanar, Calmbreeze Inns offer travelers rest on Zephras Isle. Both provide shelter and local services. Travelers can rest at the Calmbreeze Inns on Zephras Isle. Coriella Calmbreeze runs the inn in Shen'dar Village, where island tradesfolk gather. There, you can find mentors in herbalism, skinning, and enchanting.\n\nAcross the way, the Valaanar inn welcomes local wayfarers and shelters rare curios. Upstairs, an audio crystal holds a recording of the ancient rebellion in Eldre'Thalas.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_calmbreeze-inn-0e00128cacaa99604076/1-0000.mp3", duration = 32.6791837, start = 0},
  },
}
P.transport["subzone:camp-aparaje"] = {
  hash = "a70dcc",
  fullHash = "534ccc",
  text = "Camp Aparaje. Grimtotem warriors now hold Camp Aparaje in the eastern heights of the Stonetalon Mountains. They slaughtered the peaceful tauren who settled there and claimed the outpost. Peaceful tauren once made their home among the Stonetalon crags, seeking a quiet life in the highlands. Then raiders from nearby Grimtotem Post struck under Grundig Darkcloud's lead. The attackers butchered some villagers and drove others away. Survivors such as Makaba Flathoof mourn their lost home and fear for kin taken captive. Grimtotem warriors now occupy Camp Aparaje as a forward base for their aggressive tribe in the region. Many Grimtotem settlements bear blue markings, but the great totem here is painted deep crimson.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_camp-aparaje-464d9cee8921b46a558a/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["subzone:canals-stormwind-city"] = {
  hash = "34363d",
  fullHash = "d9a214",
  text = "Canals (Stormwind City). Walkers and anglers share the paths beside Stormwind's Canals, winding between the city's districts. You can follow the Canals from the Trade District's markets to Old Town's aged alleys, the cathedral gardens, and the Dwarven District. Stone bridges and archways cross the water, while paths pass the Gallina Winery, tailor shops, and quiet homes. Merchants and fishermen use these waterways. Beneath the streets, the fortified Stockade entrance holds Stormwind's most dangerous criminals and rebels. The Horde sacked Stormwind during the First War, leaving the Canals in ruins. The waterways were restored as the capital rose again after the Second War. Now they are clean and repaired, though rumors speak of a massive albino crocolisk beneath the docks.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_canals-stormwind-city-fcc3fa85053a24c014e7/1-0000.mp3", duration = 46.7591837, start = 0},
  },
}
P.transport["subzone:cathedral-of-light"] = {
  hash = "39f342",
  fullHash = "b7f0f8",
  text = "Cathedral of Light. In Cathedral Square, the Cathedral of Light is the Church of the Holy Light’s chief sanctuary. It is Stormwind’s spiritual heart and the center of human priesthood and the Knights of the Silver Hand. Archbishop Benedictus leads the faithful from the Cathedral of Light, rebuilt after the First War’s devastation. Archbishop Alonsus Faol and Bishop Benedictus guided its restoration. Its towering form still recalls the city’s resilience.\n\nAfter the Scourge took Lordaeron during the Third War, the Church moved its seat south to Stormwind. From the great hall, Benedictus gives spiritual guidance to the Alliance. The Cathedral of Light is a place of prayer and healing. It is also the Knights of the Silver Hand’s main headquarters in the southern kingdoms.\n\nLord Grayson Shadowbreaker and Duthorian Rall train promising squires in the sacred trials of the Tome of Valor and the Tome of Divinity. High Priestess Laurena teaches acolytes the deepest tenets of the Light. She prepares holy champions to defend the realm from the growing threats of the Defias Brotherhood and the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cathedral-of-light-fd5fdefa26653eee7cc0/1-0000.mp3", duration = 65.6718367, start = 0},
  },
}
P.transport["subzone:cathedral-square"] = {
  hash = "3e5388",
  fullHash = "741fca",
  text = "Cathedral Square. In Cathedral Square, faith and civic life gather beneath the Cathedral of Light. City Hall, the orphanage, and the Argent Dawn's Stormwind headquarters are here. Northwest of the Trade District and southeast of the Dwarven District, Cathedral Square draws the faithful from across the Kingdom of Stormwind. The Cathedral of Light rises above the square, foremost sanctuary of the Holy Light across Azeroth. Priests, paladins, and healers come to study, pray, and train. Citizens and pilgrims mingle with schoolchildren led by School Mistress Danna. Prayer shares Cathedral Square with the kingdom's work. City Hall and the Stormwind Orphanage anchor its civic life. Along the avenues, armorers and weaponsmiths serve holy crusaders, including Righteous Plates and Just Maces. The Argent Dawn keeps its Stormwind base here. Its recruiters and representatives coordinate relief and rally champions against the Scourge in the northern kingdoms.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cathedral-square-9f86a8fdc5c231196f24/1-0000.mp3", duration = 57.1297959, start = 0},
  },
}
P.transport["subzone:cenarion-enclave"] = {
  hash = "72c55e",
  fullHash = "7906f5",
  text = "Cenarion Enclave. In Darnassus, the Cenarion Circle gathers beneath Fandral Staghelm's leadership of the night elven druids. The Cenarion Enclave is their meeting place and seat of power, set among the capital's great hollows and living boughs. High above the Temple Gardens, the Cenarion Enclave brings the Cenarion Circle together beneath ancient oaks and ashes whose bark bears runes. Its halls are shaped from living wood and stone. With Malfurion Stormrage absent in the Emerald Dream, Archdruid Fandral Staghelm oversees the Circle's affairs here. His ambitious vision for Teldrassil meets political friction with High Priestess Tyrande Whisperwind.\n\nDruids meditate beside the streams, and the capital's hunters gather here as well. At the stables, skilled riders learn to tame Darnassian nightsabers. Known as a tranquil sanctuary, the Cenarion Enclave also shelters quiet work beneath its westernmost bough. Under the hollowed roots lies a refuge where Darnassus's clandestine rogues work, shielded by the canopy above.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cenarion-enclave-14e367fbdbd253686b74/1-0000.mp3", duration = 64.8620408, start = 0},
  },
}
P.transport["subzone:champions-hall"] = {
  hash = "306303",
  fullHash = "306303",
  text = "Champions' Hall. In Stormwind's guarded Champions' Hall, Alliance officers gather to discuss campaigns across Azeroth. Its quartermasters supply proven veterans with specialized weapons, plate, and regalia. Only Alliance soldiers who have earned the rank of Knight or higher in battle pass the guarded entrance to Champions' Hall. Commanders gather around maps of Azeroth to discuss ongoing campaigns, among arms and the insignias of rank. Quartermasters supply battle-hardened soldiers with elite weapons and armor to aid them against the Horde in contested lands, along with mounts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_champions-hall-e9bc7627bfca90722b4e/1-0000.mp3", duration = 33.8808163, start = 0},
  },
}
P.transport["subzone:charred-vale"] = {
  hash = "0b7e2b",
  fullHash = "6e3e57",
  text = "Charred Vale. In southwestern Stonetalon, fire and smoke still consume the Charred Vale. The Venture Company's logging left the woodland in ruins, and fire elementals roam while Bloodfury harpies defend their territory. Once, trees filled the basin in southwestern Stonetalon, and treants guarded the woodland. Native chimaeras and harpies lived among them. Then the Venture Company's goblins arrived with explosive machinery and cut down the forest. Their work corrupted the treants and woke chaotic fire elementals.\n\nThe treants drove the goblins back, but the loggers left a broken land scarred by fire. Whatever foul devices they used as they fled also tainted the valley. Blackened ancients wander blindly through smoke and ash, while enraged elementals roam nearby. Bloodfury harpies roost in skeletal snags and defend what remains of their territory.\n\nDruids from Sun Rock Retreat will not abandon the valley. They send travelers to sow enchanted seeds and tend the corrupted ancients as they work to reclaim the scorched earth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_charred-vale-4ce72093c56fe9d8b2c3/1-0000.mp3", duration = 64.8097959, start = 0},
  },
}
P.transport["subzone:chill-breeze-valley"] = {
  hash = "03cf29",
  fullHash = "03cf29",
  text = "Chill Breeze Valley. In western Dun Morogh, travelers cross Chill Breeze Valley between Kharanos and Gnomeregan. Refugees and young travelers follow the main trail, while dangerous beasts haunt the secluded reaches. A T-shaped trench cuts through the mountains, its main trail running east to west. Young dwarves and gnomes travel between Kharanos and the outskirts of Gnomeregan. The north-south branch leads into dangerous ground. Blood stains the snow, and mangled carcasses lie nearby.\n\nSavage wendigos make dens in deep ice caves. They prey on anyone who wanders into their hunting grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_chill-breeze-valley-9d7e34f3671410727c54/1-0000.mp3", duration = 36.2318367, start = 0},
  },
}
P.transport["subzone:clean-zone"] = {
  hash = "eb67fa",
  fullHash = "e80253",
  text = "Clean Zone. Gnomes hold the Clean Zone as a refuge inside ruined Gnomeregan. Beyond the upper Hall of Gears, this fortified enclave stays safe amid the irradiated city. Medics, technicians, and Sparklematic machines support its defenders and salvage work. The Clean Zone remains untainted while most of Gnomeregan fell to Mekkatorque's disastrous venting of radioactive waste. It lies between the trogg-infested Dormitory below and the contested Hall of Gears above. Gnome defenders, technicians, and field medics hold its barricades day and night. Alliance expeditions regroup here, tend wounds, and maintain their machinery. The Clean Zone also supports salvage from Gnomeregan's ruined capital. Gnomish engineers installed Sparklematic 5200 units to scrub and wash grime-encrusted relics brought up from the city's radioactive depths. Technicians and merchants such as Tink Sprocketwhistle process reclaimed gears and baubles, outfit adventurers, and study the toxic fallout in the deep tunnels.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_clean-zone-b6fdb57a88b459194316/1-0000.mp3", duration = 62.4326531, start = 0},
  },
}
P.transport["subzone:cleft"] = {
  hash = "404e97",
  fullHash = "404e97",
  text = "Cleft. Northwest of Dolanaar, Gnarlpine furbolgs ambush travelers in the Cleft. Off the road between Dolanaar and Darnassus, Gnarlpine furbolgs have made their den in the Cleft. Teldrassil’s spreading corruption has driven them mad, and they have fortified the hollow. From there, they threaten travelers on the main road and may cut Dolanaar off from Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cleft-acada7a6f227bf10aa9b/1-0000.mp3", duration = 22.0734694, start = 0},
  },
}
P.transport["subzone:cliffspring-falls"] = {
  hash = "557b58",
  fullHash = "557b58",
  text = "Cliffspring Falls. At Cliffspring Falls, water pours from Darkshore’s eastern cliffs into the forest below. The falls feed the Cliffspring River and once supplied nearby night elf settlements. Now a foul taint spreads through the river basin. Cliffspring Falls rises from caves high in Darkshore’s eastern bluffs and feeds the Cliffspring River. The river winds west through the woods before emptying into the sea. Its clear waters once gave nearby night elf settlements their purest drinking water.\n\nNow the water runs murky and foul, carrying sickness and decay through the river basin. Naturalists who investigate the falls find naga and cultists overrunning the caves. They plot in the shadows as demonic corruption from neighboring Felwood threatens to seep through the highland bedrock.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cliffspring-falls-3b0b1028cb35dab468a6/1-0000.mp3", duration = 44.8783673, start = 0},
  },
}
P.transport["subzone:coldridge-pass"] = {
  hash = "1e03b4",
  fullHash = "1e03b4",
  text = "Coldridge Pass. Troggs now bar the road through Coldridge Pass, the way out of Coldridge Valley. Recruits leave Coldridge Valley through Coldridge Pass and travel toward Kharanos. The tunnel cuts through Dun Morogh’s southern mountain ridge, carrying them from sheltered training grounds into the wider kingdom. Troggs have overrun the passage, threatening anyone who crosses between the valley and the rest of Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_coldridge-pass-faf30a410f68c6514eca/1-0000.mp3", duration = 22.7004082, start = 0},
  },
}
P.transport["subzone:command-center"] = {
  hash = "eb026d",
  fullHash = "7671a1",
  text = "Command Center. Stormwind's army is thinned by campaigns abroad, and recruits drill in the Command Center. Also called the Stormwind Barracks, it houses the city's officers and a seasoned crew focused on training recruits and local militia. In Old Town, Stormwind's Command Center trains the kingdom's soldiers. Much of the royal army serves abroad, leaving its halls quieter than usual. Veteran instructors Ander Germaine and martial artist Wu Shen drill fresh warriors to strengthen the city's defenses. When you seek instruction in heavy arms or tactical combat, Stormwind's guards may direct you to the Barracks. It stands near the Pig and Whistle Tavern and Old Town's shadowy operations. The training ground helps keep order in a district known for tavern brawls and roguish activity.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_command-center-24e891011b72948aef0f/1-0000.mp3", duration = 45.8710204, start = 0},
  },
}
P.transport["subzone:commons"] = {
  hash = "14242a",
  fullHash = "a7627a",
  text = "Commons. Travelers and traders fill the Commons just inside Ironforge's gates. From here, the mountain city's great caverns open before them, and merchants, travelers, and bankers arrive from across the Alliance. The Commons greets you just northeast of the Gates of Ironforge. Its market street is cut from mountain stone, with the Alliance Auction House, Stonefire Tavern, and the central bank in the Vault of Ironforge. Broad roads lead to the Great Forge, the Mystic Ward, and the Military Ward. Nearly everyone crossing the city passes its shops. Trade reaches the Commons from across the Eastern Kingdoms. Ironforge's central position and the underground Deeprun Tram to Stormwind bring travelers and merchants through its streets. Adventurers trade goods from across Azeroth, buy weapons at Steelfury's Weapon Emporium, or purchase reagents from Barim. Some gather beneath the inn's warm lanterns before setting out into the snows of Khaz Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_commons-0bf6695954794e749cd0/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["subzone:craftsmen-s-terrace"] = {
  hash = "176469",
  fullHash = "5dcbb1",
  text = "Craftsmen's Terrace. Workshops and visitors gather along Darnassus's northern edge at Craftsmen's Terrace. Its trainers, inn, and Argent Dawn embassy serve artisans and travelers. Woodworkers, leathercrafters, alchemists, and other artisans work along Darnassus's northern edge. Their shops gather the trades that keep the city running, with night elven methods put to practical use. An inn, a guild master, and guild petition vendors serve visitors here. Bridges lead west to the Cenarion Enclave and south to the Warrior's Terrace. The Argent Dawn keeps an embassy in the Craftsmen's Terrace and coordinates with northern allies against the Scourge. Scattered scholarly volumes rest among the workshops. They include histories of the War of the Ancients, chronicles of the Second War, and treatises on the Old Gods.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_craftsmen-s-terrace-a438d50ec3d7d3b6c10c/1-0000.mp3", duration = 49.2408163, start = 0},
  },
}
P.transport["subzone:cragpool-lake"] = {
  hash = "ce4a52",
  fullHash = "ce4a52",
  text = "Cragpool Lake. In Windshear Crag, the Venture Company’s timberworks hang above Cragpool Lake and its dark water. At Cragpool Lake, Venture Company platforms cross above the water beneath a vast timber structure. Gerenzo Wrenchwhistle watches operations across the mountain valley. Company workers occupy the platforms overhead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cragpool-lake-610e9c890305d17fcf53/1-0000.mp3", duration = 19.3567347, start = 0},
  },
}
P.transport["subzone:crystal-lake"] = {
  hash = "e82dbe",
  fullHash = "e82dbe",
  text = "Crystal Lake. At Crystal Lake, murlocs claim the shore east of Goldshire. Their attacks endanger villagers and travelers passing by. East of Goldshire, Crystal Lake lies within walking distance of the Lion's Pride Inn. Freshwater murlocs claim its shore and shallow shoals, attacking anyone who comes too close. William Pestle, an alchemist at the inn, hires travelers to drive them back and gather the crystal kelp they carry for his experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crystal-lake-822817e7779f7949c6f9/1-0000.mp3", duration = 25.3126531, start = 0},
  },
}
P.transport["subzone:cut-throat-alley"] = {
  hash = "2379ea",
  fullHash = "2379ea",
  text = "Cut-Throat Alley. In Cut-Throat Alley, a hidden courtyard lies beyond a canal shop in Stormwind City. Its paved path ends at an empty residence, out of sight of ordinary city traffic. Step through the Shady Lady and a paved dead end opens before you. Stacked crates and forgotten barrels sit beside a two-story residence with no one at home. Though the alley is counted within the Dwarven District, it lies apart from the district's forge fires and soot.\n\nNo main avenue reaches Cut-Throat Alley. Its only footpath passes through the canal-side shop, just south of the bridge from Cathedral Square. Passing guards and ordinary citizens cannot see this quiet corner of the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cut-throat-alley-64d9765e58478dab1b67/1-0000.mp3", duration = 40.5159184, start = 0},
  },
}
P.transport["subzone:dagger-hills"] = {
  hash = "b320e6",
  fullHash = "81470b",
  text = "Dagger Hills. Bandits hold Dagger Hills, the rocky heights behind Moonbrook in southern Westfall. With royal patrols gone, the ridge threatens travelers and the plains below. The Defias Brotherhood uses this dry highland as a stronghold. Knuckledusters, pathstalkers and highwaymen hide among the crests and scrub. They ambush unwary travelers and watch the approaches to their strongholds below, keeping the surrounding plains under threat. Darkness brings danger to Dagger Hills. After sunset, Leprithus, a wandering ghoul, has been seen stalking the desolate heights. Outlaws and lingering undead roam the ridge. Nearby, Grimbooze Thunderbrew, a dwarven brewer, sets up his distilling equipment despite the dangers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dagger-hills-0d76d222b306123dea3a/1-0000.mp3", duration = 43.0759184, start = 0},
  },
}
P.transport["subzone:darkcloud-pinnacle"] = {
  hash = "373649",
  fullHash = "373649",
  text = "Darkcloud Pinnacle. Grimtotem tauren hold Darkcloud Pinnacle above the canyon east of the Great Lift. From their linked mesas, they disrupt the region and pursue secret dealings. Darkcloud Pinnacle rises above the canyon basin across three main mesas, joined by rope bridges. You can climb a steep natural slope from the canyon floor, then cross wooden bridges. A high crossing near Razorfen Downs offers another way up. From these windswept rocks, Grimtotem watchers survey the valley. The heights guard them from easy attack and leave them apart from the wider tauren tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_darkcloud-pinnacle-4049024f4a6772fa776d/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["subzone:darkened-bank"] = {
  hash = "ebfc4c",
  fullHash = "ebfc4c",
  text = "Darkened Bank. At Duskwood’s northern edge, Darkened Bank runs beside Elwynn Forest. Its shore reaches east toward the Redridge Mountains, between safer ground and the forest’s terrors. Darkened Bank follows the river that divides Duskwood from Elwynn Forest. Its shore stretches from the western bends to the stone span leading to the Redridge Mountains. Beneath Duskwood’s gloomy canopy, travelers coming south from Elwynn often reach this ground first. Near the western tip, a makeshift camp shelters the displaced Sven Yorgen and Lars, just beyond the deep woods.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_darkened-bank-86bc99d9b51f668cdaea/1-0000.mp3", duration = 33.3583673, start = 0},
  },
}
P.transport["subzone:darkshire"] = {
  hash = "0577e8",
  fullHash = "61195f",
  text = "Darkshire. Darkshire's Night Watch holds the line while Duskwood's unnatural gloom closes around the town. With little aid from Stormwind, the people must guard their homes. Darkshire began as Grand Hamlet, a peaceful woodland settlement. The Old Horde razed it during the First War, and the village rose again. After Medivh fell at Karazhan, the death throes left in the surrounding woods made them the shadowed wilderness of Duskwood.\n\nDarkshire belongs to the Kingdom of Stormwind, yet the crown sends virtually no aid to its town hall. Political paralysis in Stormwind City has left the garrison unstaffed and the borders unpatrolled. Mayor Ello Ebonlocke and the local council govern alone, enforcing harsh, insular justice in the shadows. Walking dead from the western graveyards and feral worgen in the woods press against Darkshire's palisades. The Night Watch, a voluntary civilian militia led by Althea Ebonlocke, is the town's chief defense. From the town square, weary sentries patrol the pitch-black roads, keep them open, and turn back terrors at the tree line.\n\nAt the Scarlet Raven Tavern, travelers meet locals who are suspicious, frightened, and desperate for anyone able to wield a blade.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_darkshire-73f0f904c25e019765ad/1-0000.mp3", duration = 75.4677551, start = 0},
  },
}
P.transport["subzone:darkshire-town-hall"] = {
  hash = "36f6c9",
  fullHash = "36f6c9",
  text = "Darkshire Town Hall. In Darkshire Town Hall, the mayor and council govern a town besieged by darkness and undead. Its dim halls are the seat of their rule. Just west of Darkshire's main square, the Town Hall is where the town's leaders govern an increasingly isolated territory. Mayor Lord Ello Ebonlocke struggles to keep order and protect the people while Stormwind sends little military aid.\n\nClerk Daltry and other officials track town records and the travelers who brave Duskwood's dangerous roads. With danger all around, keeping those ledgers current is grim work.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_darkshire-town-hall-32e83c88a70489c99a54/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["subzone:dawning-wood-catacombs"] = {
  hash = "278229",
  fullHash = "278229",
  text = "Dawning Wood Catacombs. Beneath Raven Hill Cemetery in western Duskwood, undead fill the Dawning Wood Catacombs. Skeletal guards and ravenous ghouls haunt their stone tunnels. Beneath the ruined Raven Hill Cemetery, the Dawning Wood Catacombs hold the dead of the surrounding woods. Before twilight cursed the forest, those dead rested in these stone corridors. Now the catacombs shelter some of the region’s deadliest undead, and lone travelers face danger in their depths.\n\nTwo underground wings divide the catacombs. Animated skeletons guard ancestral tombs in the western passages. To the east, tunnels descend into a foul warren overrun by ravenous, disease-bearing ghouls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dawning-wood-catacombs-dc043989f27989d95db5/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["subzone:dead-acre"] = {
  hash = "e7302e",
  fullHash = "e7302e",
  text = "Dead Acre. In southeastern Westfall, Dead Acre lies burned and abandoned near the bridge to Duskwood. The Defias Brotherhood torched the farm during its uprising, and rogue harvest golems still stalk the blackened fields. North of the road from Sentinel Hill to Duskwood, Dead Acre stands among Westfall’s old breadbasket farms. The homestead once gave good harvests, until the Defias Brotherhood rose in revolt and drove out the landowners. Then farm and crops went up in flames. Scorched timber and smoking earth remain, while mechanical Harvest Watchers still reap the barren soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dead-acre-8d8350525edcc2c2a78f/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["subzone:deeprun-tram"] = {
  hash = "a3b730",
  fullHash = "a3b730",
  text = "Deeprun Tram. Beneath the mountains, the Deeprun Tram carries travelers between Ironforge and Stormwind City. King Magni Bronzebeard commissioned it after the Second War, and its twin tracks carry citizens, soldiers, and goods between the Alliance capitals. After the Second War, King Magni Bronzebeard sought a faster way to send dwarven aid and supplies to Stormwind. Mountain passes made the journey slow, so he asked High Tinker Gelbin Mekkatorque to design an underground railway.\n\nGnomish engineers cut a route beneath a mountain and through a vast subterranean lake. Rats plagued the work, but the tram was finished. It carries thousands between Ironforge and Stormwind without charge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_deeprun-tram-268ed1714c2caa19f13d/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["subzone:deepwater-tavern"] = {
  hash = "d28b69",
  fullHash = "d28b69",
  text = "Deepwater Tavern. At Menethil Harbor, the Deepwater Tavern gives travelers a place to rest and seek work. Sailors and adventurers meet there, and harbor rumors may end in a brawl. In Menethil Harbor, the Deepwater Tavern offers shelter from the marsh rain and rough roads. Sailors, dockworkers, merchants, and weary adventurers gather beneath its timber beams. They trade news, meet, warm themselves, and tend their wounds.\n\nLocal merchants and a first aid trainer help those bound for the marsh or setting out across the Great Sea. The tavern stays lively, and spilled ale can turn a dispute into a brawl. Tapoke 'Slim' Jahn is known to spark them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_deepwater-tavern-cdc7756ffcd7cb6b21e2/1-0000.mp3", duration = 39.5755102, start = 0},
  },
}
P.transport["subzone:defias-hideout"] = {
  hash = "a3c321",
  fullHash = "a3c321",
  text = "Defias Hideout. Vagrants and Defias thugs linger in the ruined house on Moonbrook’s southern edge. Its upper floor conceals a route into chambers beneath the town.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_defias-hideout-153ee959d29bf5258504/1-0000.mp3", duration = 9.03836735, start = 0},
  },
}
P.transport["subzone:demon-fall-canyon"] = {
  hash = "7f8c0a",
  fullHash = "427645",
  text = "Demon Fall Canyon. In southern Ashenvale, the canyon bears the scars of the battle that freed the orcs from the blood curse. Thrall and Grommash Hellscream faced Mannoroth here. Near Felfire Hill and Demon Fall Ridge, the canyon still bears the scars of the Third War. Warchief Thrall and chieftain Grommash Hellscream tracked the pit lord Mannoroth here to break his hold over the Horde. Mannoroth struck Thrall down. Grom seized the chance to drive his axe, Gorehowl, into the demon’s chest.\n\nThe infernal blast shattered Mannoroth and killed Grom. With the pit lord’s death, the orcs were free of their lingering demonic servitude. The Horde named the canyon for Grom’s final stand and raised a monument nearby to honor his redemption. Mannoroth’s death unleashed demonic power that tainted the surrounding land. Fel magic still saturates the canyon, where lesser demons roam. Pilgrims who come to this hallowed ground face danger at every turn.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_demon-fall-canyon-ac9d6765df170f3f5693/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["subzone:demon-fall-ridge"] = {
  hash = "e9a7af",
  fullHash = "43b8d0",
  text = "Demon Fall Ridge. Demons hold Demon Fall Ridge in southeastern Ashenvale, above the place where Mannoroth fell. Fel magic still stains the heights, and the Burning Legion has claimed a night elf barrow den. West of Demon Fall Canyon, Demon Fall Ridge looks down on the place where Grommash Hellscream fought the pit lord Mannoroth. Its cliffs still bear the fel scars of the Third War. The demons who survived use the heights as a staging ground. Lesser demons patrol the rocky slopes, defile the woodland, and threaten travelers along Ashenvale’s southern border. A night elf barrow den lies abandoned in the ridge’s side. Dark sorcery now fills the passages where druids once slept. Fel fiends prowl its halls, and deep within, Diathorus the Seeker rules the conclave. The cunning dreadlord directs the demons who remain across the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_demon-fall-ridge-f563c91ee194efc33271/1-0000.mp3", duration = 50.7036735, start = 0},
  },
}
P.transport["subzone:demont-s-place"] = {
  hash = "2cfc57",
  fullHash = "eb62c1",
  text = "Demont's Place. Outlaws hold Demont's Place, west of Moonbrook in southwestern Westfall. Once its fields fed the Kingdom of Stormwind. Economic collapse and the Defias Brotherhood drove the caretakers away, leaving the fields empty and the fences weathered. Demont's Place lies within sight of Moonbrook, among the family holdings that once fed the Kingdom of Stormwind. Economic collapse and outlaw brigands stripped the farm of its livelihood and drove its caretakers away. Now outlaws use its grounds as an extension of the Defias stronghold in Moonbrook. The Defias Brotherhood holds Demont's Place on the outskirts of Moonbrook. Thugs, cutpurses, and displaced laborers linger among its fences and shattered buildings. They ambush travelers who stray from the southern roads. Until Moonbrook is reclaimed and the outlaws are broken, peaceful farming cannot return.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_demont-s-place-2e1b8297b4987259ef34/1-0000.mp3", duration = 51.1477551, start = 0},
  },
}
P.transport["subzone:dolanaar"] = {
  hash = "1bb1c3",
  fullHash = "1bb1c3",
  text = "Dolanaar. At Dolanaar, travelers and guides gather beneath Teldrassil’s boughs. Southwest of Shadowglen, the town is the first place young night elves reach after leaving their sheltered training grounds. Rangers, druids, and craftsmen help newcomers as strange afflictions spread through the World Tree. Beneath Teldrassil’s canopy, Dolanaar is a crossroads for travelers. Southwest of Shadowglen, its homes and platforms follow the traditional night elven way, woven into the woodland. Young night elves come here for their first broad training in trades, martial arts, and nature crafts. The road west leads toward Darnassus, the capital. Reports of corrupted wildlife, aggressive furbolgs, and foul mosses come from the surrounding boughs, and Dolanaar’s council hears them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dolanaar-1733ff2557ef5f3bfe0e/1-0000.mp3", duration = 48.5093878, start = 0},
  },
}
P.transport["subzone:dor-danil-barrow-den"] = {
  hash = "464d96",
  fullHash = "464d96",
  text = "Dor'Danil Barrow Den. South of Splintertree Post, Dor'Danil Barrow Den lies under Forsaken shadow. Druids once slept here while their spirits roamed the Emerald Dream. Now horror fills the sanctuary. For centuries, night elven druids have slept in barrow dens across Kalimdor. Their bodies rest underground while their spirits travel the Emerald Dream. When the Horde pushed into Ashenvale, Dor'Danil lay deep behind enemy lines. The orcs mostly left the sleeping elves alone, but the newly allied Forsaken saw an opportunity. Their agents entered the depths and began experiments to sever the druids from their spirits.\n\nThe ordeal fractured the dreamers' minds and drove them mad. Now sinister Forsaken assassins prowl the dark hollows. The tormented spirits of druids who cannot return to their bodies haunt them too.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dor-danil-barrow-den-f6255340f4a1353ec83a/1-0000.mp3", duration = 50.3379592, start = 0},
  },
}
P.transport["subzone:dormitory"] = {
  hash = "32660d",
  fullHash = "52f39f",
  text = "Dormitory. In Gnomeregan, troggs now overrun the Dormitory, and radiation chokes its halls. Gnomes once made their homes here, but the creatures that drove them out now hold the fallen city's residential quarters. Beyond the Clean Zone's decontamination chambers, the Dormitory once housed Gnomeregan's inventors, laborers, and families. When High Tinker Mekkatorque opened the emergency radiation vents to fight the invading troggs, this crowded part of the city became a trap. No gnomish life remains in its communal halls or living quarters. Mutated troggs thrive in the radioactive air. To reach the lower Hall of Gears, travelers must fight through this reminder of the catastrophe. Though the living quarters are abandoned, Gnomeregan's administrative machines still work. Matrix Punchograph 3005-B terminals process security punch cards. The cards open higher-security data terminals deeper in the city, where important records remain from the gnomes' flight.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dormitory-27282552d882df9fdd5d/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["subzone:dun-algaz"] = {
  hash = "396c30",
  fullHash = "96cb5c",
  text = "Dun Algaz. Dragonmaw orcs have seized Dun Algaz, closing the easy road between Ironforge's lands and Menethil Harbor. Its guarded pass and tunnels join Loch Modan to the Wetlands. Dun Algaz cuts through the jagged peaks between Loch Modan and the Wetlands. The pass was already there before the War of the Three Hammers. After the Wildhammer clan was driven from Ironforge, its people traveled this way north. Stone tunnels, bastions, and watchposts guard the road. Whoever holds Dun Algaz commands the only overland route from the dwarven heartlands to Menethil Harbor on the western sea. After their defeat at Dun Modr in the Second War, the Old Horde retreated to Dun Algaz. The pass became their last southern bulwark against Sir Anduin Lothar's forces. The Alliance took it back for a time, but Dragonmaw orcs have overrun the stronghold again. Dwarven Mountaineers have withdrawn to the upper tunnels, leaving a deadly gauntlet for travelers through the mountain corridor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dun-algaz-1833b4aba3d494160642/1-0000.mp3", duration = 59.4808163, start = 0},
  },
}
P.transport["subzone:dun-garok"] = {
  hash = "53341e",
  fullHash = "30f809",
  text = "Dun Garok. Dun Garok holds the southeastern heights of the Hillsbrad Foothills. Captain Ironhill leads its dwarven garrison, defending Alliance interests and nearby operations at the Azurelode Mine. The Forsaken of Tarren Mill see the stronghold as a threat on their border. Dun Garok holds the crags in southeastern Hillsbrad. Captain Ironhill leads the Ironforge mountaineers and riflemen who defend the outpost. They guard human settlements and protect Alliance operations at the Azurelode Mine. Stone walls and deep entrenchments help the garrison withstand nearby threats. Dun Garok lies close to Tarren Mill, and the Forsaken see it as an intrusion on their southern border. Sylvanas Windrunner's forces resent the armed dwarves near their stronghold. They plot to enter the fortress, break its defenses, and kill Captain Ironhill's garrison to secure Forsaken control of Hillsbrad.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dun-garok-761a7941e6dc4fded8ff/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["subzone:dun-modr"] = {
  hash = "5c6f6a",
  fullHash = "8aad3a",
  text = "Dun Modr. Dark Iron dwarves hold Dun Modr and the southern approach to the Thandol Span. The fortress changed hands in a fierce struggle during the Second War. At Wetlands' northern edge, Dun Modr guards the main road between Khaz Modan and the northern human kingdoms. Armies have fought for that route across the decades. During the Second War, the Orcish Horde seized the dwarven stronghold and used it to launch raids and resist Alliance armies.\n\nStromgarde warriors sailed from Tol Barad to reclaim it, but the Orcs struck back in a bloody struggle. At last, Alliance forces under Lord Anduin Lothar drove the invaders south across the Thandol Span and returned the fortress to dwarven hands. With Ironforge's attention divided and many of its finest mountaineers serving the Alliance abroad, Dun Modr lay exposed. Dark Iron invaders took their chance. They sabotaged the Thandol Span with explosives, then swarmed the fortress. Led by the warlock Balgaras the Foul, they overcame the defenders and drove out the Bronzebeard garrison. Now mountaineers hold a grim perimeter just down the road, seeking aid to drive out the occupiers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dun-modr-e47c35b843c62f54803b/1-0000.mp3", duration = 70.8440816, start = 0},
  },
}
P.transport["subzone:durnholde-keep"] = {
  hash = "e5a6ac",
  fullHash = "a18caa",
  text = "Durnholde Keep. Outlaws shelter in Durnholde Keep, east of Tarren Mill in the Hillsbrad Foothills. The shattered fortress once served as the Alliance headquarters for the southern orc internment camps. Now the Syndicate holds its ruins. After the Second War, the Alliance made Durnholde Keep its headquarters for the southern internment camps. Lieutenant General Aedelas Blackmoore commanded the fortress and its arena, where orcs fought for sport and profit. Blackmoore raised the orphaned infant Go'el as a slave, named him Thrall, and trained him to fight.\n\nWith Taretha Foxton's aid, Thrall escaped captivity and later united the scattered orc clans beneath the new Horde. He returned to Durnholde, besieged the keep, and slew Blackmoore. Then he called on the earth spirits to shatter its walls. Durnholde Keep has lain in ruins since its collapse before the Third War. After Lordaeron fell, the Syndicate took refuge among its broken ramparts. The bandits are dispossessed Alterac nobles and cutthroats.\n\nFrom the ruined bailey and towers, they prey on travelers across the Hillsbrad Foothills. The old fortress now serves them as a fortified outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_durnholde-keep-557caa8564523721bf63/1-0000.mp3", duration = 72.6465306, start = 0},
  },
}
P.transport["subzone:dust-plains"] = {
  hash = "ff9d60",
  fullHash = "ff9d60",
  text = "Dust Plains. Gnoll packs prowl the Dust Plains, Westfall’s dry southern frontier. The wastes stretch toward the coast and eastern hills, where Klaven’s Tower overlooks the plain. Across southern Westfall, the Dust Plains lead from troubled farmland toward desolate wilderness. Feral gnolls have long claimed this dry ground. They ambush travelers and challenge anyone bound for the coast or nearby hills.\n\nKlaven’s Tower marks the eastern boundary. Klaven Mortwake, a Defias rogue, holds the old mage tower. Gnolls prowl the surrounding wastes, leaving travelers no shelter there.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dust-plains-290308687078241e6726/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["subzone:dwarven-district"] = {
  hash = "aba864",
  fullHash = "aba864",
  text = "Dwarven District. In Stormwind's northern quarter, Dwarven craftsmen keep their furnaces and workshops at work. The Deeprun Tram links their home to Ironforge. Dwarven artisans, smiths, and engineers make their home in Stormwind's northern quarter. Its heavy stonework, smelting works, and craft shops recall Ironforge. At Potts' Plates, craftspeople from Khaz Modan find familiar company.\n\nOn the district's eastern side, an open, arched tunnel leads to the Stormwind station of the Deeprun Tram. The tram links the human capital directly to Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dwarven-district-88675ac2422e95d98818/1-0000.mp3", duration = 35.9706122, start = 0},
  },
}
P.transport["subzone:eastvale-logging-camp"] = {
  hash = "2af34c",
  fullHash = "8bb0ab",
  text = "Eastvale Logging Camp. Timber orders from Stormwind reach Eastvale Logging Camp, where danger keeps the work from going smoothly. Wolves and bears drive lumberjacks from the eastern woods, but the camp still sends timber to Stormwind and nearby settlements. Timber buyers across the Kingdom of Stormwind send Eastvale Logging Camp orders with strict deadlines. Wolves and bears prowl the woods around the work sites. They drive lumberjacks away and leave cut timber behind.\n\nSupervisor Raelen directs the camp’s work. Travelers help drive off the beasts and recover the abandoned wood before deliveries fall behind schedule. Eastvale Logging Camp has homes and horse stables where travelers can buy fine mounts. On a nearby hill above the work site, retired Marshal Haggard lives in a quiet manor.\n\nHe once led the Stormwind Guard. Then he left its service to retire far from the capital’s politics.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_eastvale-logging-camp-8906bf6b38277e318e27/1-0000.mp3", duration = 52.5061224, start = 0},
  },
}
P.transport["subzone:echo-ridge-mine"] = {
  hash = "3ecc87",
  fullHash = "03cf9d",
  text = "Echo Ridge Mine. Kobolds hold Echo Ridge Mine in the northwestern cliffs of Northshire Valley, where stone and ore once fed the valley. Echo Ridge Mine was cut into the hills above Northshire Abbey to supply the valley with stone and metal. Kobolds poured through its tunnels and drove out the workers. Marshal McBride fears they endanger Northshire's safety and its recruits. So he sends new recruits into the mine to thin their numbers and take it back. Kobolds have pushed beyond Echo Ridge Mine into Elwynn Forest. From the northwestern ridge, they threaten Northshire's training grounds and the flow of resources to the abbey.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_echo-ridge-mine-6a0693d184e0492acff7/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["subzone:engineering-labs"] = {
  hash = "4439e1",
  fullHash = "7d9758",
  text = "Engineering Labs. In Gnomeregan, the Engineering Labs lie in ruin across tiers linked to the Workshop Entrance and Launch Bay. Once a center of gnome invention, they fell in the city's radioactive catastrophe. Crazed leper gnomes and rogue machines now fill the chambers. The Engineering Labs once held Gnomeregan's work in invention. A central mechanical structure rises through two tiers, joined by a cargo lift. At the city's height, tinkerers made schematics and refined clockwork devices here. Radiation drove the remaining researchers mad. Now deranged leper gnomes guard the malfunctioning machinery beside rogue constructs. The Engineering Labs connect routes through Gnomeregan's lower reaches. Passages lead toward the Launch Bay, Tinkers' Court and the Workshop Entrance back door. On the lower floor, Matrix Punchograph 3005-D terminals process coded punch cards carried by gnome engineers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_engineering-labs-c0c16a377411ce7d8b72/1-0000.mp3", duration = 57.5738776, start = 0},
  },
}
P.transport["subzone:falfarren-river"] = {
  hash = "1b1656",
  fullHash = "071196",
  text = "Falfarren River. The Falfarren River runs through central Ashenvale, dividing night elven lands from Horde outposts. Travelers meet wild dangers and open conflict along its banks. From Mount Hyjal, the Falfarren River spills over waterfalls into Xavian. Then it winds between Splintertree Post and Night Run. In ordinary weather, the water is neither especially deep nor hard to cross.\n\nThe river marks a rough boundary through central Ashenvale. Astranaar and the heart of the Kaldorei lands lie west, while Horde camps and lumber operations lie east. Wooden bridges on the main road carry travelers into the contested forest, where patrols clash along the banks. The Falfarren River brings dangers beyond clashes between sentinels and grunts. Near Felfire Hill, corrupted bog beasts and aggressive water creatures prowl the muddy shallows. Rain can swell the currents.\n\nDense canopies line both shores, where ambushes and skirmishes often spill into the stream.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_falfarren-river-0292069f23a697535e01/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["subzone:fallen-sky-lake"] = {
  hash = "3a1a97",
  fullHash = "3a1a97",
  text = "Fallen Sky Lake. At Fallen Sky Lake, Shadethickets defend the shores and central isle between Silverwing Outpost and the Warsong Labor Camp. South of Silverwing Outpost and west of the Warsong Labor Camp, Fallen Sky Lake draws you into contested waters. Hulking Shadethickets roam the shore and the small isle at its center, treating intruders as threats.\n\nA powerful Shadethicket Oracle rules from the isle's heart. The Oracle hoards the fallen moonstones once gathered here and keeps the shadethickets bound to the lake, watchful for travelers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fallen-sky-lake-3f277c9ff6c31cc51252/1-0000.mp3", duration = 32.5485714, start = 0},
  },
}
P.transport["subzone:fargodeep-mine"] = {
  hash = "c12ebb",
  fullHash = "cc9f11",
  text = "Fargodeep Mine. Kobolds now swarm through Fargodeep Mine, south of Goldshire in central Elwynn Forest. Its gold once filled Stormwind's treasury, but now kobolds make their home in its tunnels. Gold once flowed from Fargodeep Mine into Stormwind's treasury. As the Kingdom's military presence in Elwynn dwindled, the outlying mine grew vulnerable. Kobolds filled its dark tunnels and made a warren beneath the hills. Now Marshal Dughan and Goldshire's authorities fear the lost ore and the danger to nearby farms, including the Stonefield and Maclure holdings. Fargodeep Mine runs through several levels, with lower shafts reaching deep beneath the forest floor. Kobold laborers and vermin hurry along wooden scaffolds, guarding the wax and gold dust they have scavenged. Goldtooth, a cunning kobold leader, lurks in a den above the main tunnels. He hoards trinkets stolen from travelers and nearby residents.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fargodeep-mine-cf3063101120bfbff624/1-0000.mp3", duration = 53.6032653, start = 0},
  },
}
P.transport["subzone:farstrider-lodge"] = {
  hash = "3b8cf6",
  fullHash = "0b39d1",
  text = "Farstrider Lodge. In southeastern Loch Modan, Farstrider Lodge welcomes hunters and travelers bound for the wilds. Its high elven style sets it apart, though dwarves and humans live there too. Farstrider Lodge looks unlike the stone buildings of Khaz Modan. Its design recalls high elven craft, though Vyrin Swiftwind is the only known high elf still living there. Dwarves and humans make their homes beside him. No one knows who founded the lodge or when it was built. In the southeastern hills of Loch Modan, Farstrider Lodge offers hunters and travelers a place to stop before entering the wilds. Hunter and pet trainers work there, alongside merchants. Others come seeking help with local wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_farstrider-lodge-eedb4b47089f2e800e64/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["subzone:fel-rock"] = {
  hash = "2d904e",
  fullHash = "8f81a8",
  text = "Fel Rock. North of Dolanaar, corruption spreads through Fel Rock and threatens Teldrassil’s woods. Lord Melenas and his grells have made the once-tranquil cavern a danger. North of Dolanaar, Fel Rock lies among Teldrassil’s wooded hills. Once peaceful, the cavern is now choked by twisted roots and strange shadows. Wild grells and grellkin roam within. The taint reaches into the boughs of the world tree. Lord Melenas, a satyr, has made Fel Rock his stronghold. From the cavern, he spreads corruption while night elf sentinels keep watch. Druids in Dolanaar, among them Tallonkai Swiftroot, seek defenders to cleanse the cave and slay Melenas. They must stop the blight before it reaches farther into the surrounding woods.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fel-rock-3d5d9dd7803d50db013b/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["subzone:felfire-hill"] = {
  hash = "5bf1c2",
  fullHash = "ec8612",
  text = "Felfire Hill. In eastern Ashenvale, demons still crawl across the blighted rise of Felfire Hill. Infernals struck there during the Third War, and fel power still burns in the soil. Horde guards hold the bridges to the hill near their settlements. During the Third War, the Burning Legion sent flaming meteors across Kalimdor, carrying fearsome infernals. Several struck this ridge in Ashenvale. Their fires burned away the ancient woodland and corrupted the earth. The Legion fell at Mount Hyjal, yet demons that survived its defeat still prowl the scorched slopes. Fel energy saturates the land they haunt. Felfire Hill lies southeast of Splintertree Post and southwest of the Warsong Lumber Camp, near vital Horde operations. Demonic remnants threaten to spill into the surrounding forest. So Horde forces raised fortified barricades and guard towers at both bridges leading to the hill. The guards keep the creatures within their blighted haven.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_felfire-hill-d0b7733e6d802a654529/1-0000.mp3", duration = 59.4546939, start = 0},
  },
}
P.transport["subzone:fire-scar-shrine"] = {
  hash = "e943ae",
  fullHash = "e1147a",
  text = "Fire Scar Shrine. At Fire Scar Shrine, fel corruption has seized the old night elf place of worship southwest of Astranaar. Demons now gather among its altar stones. Southwest of Astranaar and west of the Ruins of Stardust, Fire Scar Shrine lies beneath a spreading blight. Servants of the Cult of the Dark Strand and the Shadow Council feed its corruption. Fel magic has scorched the earth, and demons gather openly among the trees. The forest's defenders face them there. Ilkrud Magthrull, an orc warlock, brought corruption to Fire Scar Shrine under Athrikus Narassin's orders. He served the Cult of the Dark Strand, alongside agents of the Shadow Council. Summoned fiends now patrol the altar stones unchecked. A tear in the veil sometimes draws greater horrors, including the towering doomguard Akkrilus.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fire-scar-shrine-7dcbc29724c0515b7e64/1-0000.mp3", duration = 52.2971429, start = 0},
  },
}
P.transport["subzone:forest-s-edge"] = {
  hash = "1c78d7",
  fullHash = "ddc119",
  text = "Forest's Edge. At Forest's Edge, Riverpaw gnolls under Hogger threaten travelers on Elwynn's southwestern frontier. At Forest's Edge, the woods run southwest from Stormwind City, between Mirror Lake Orchard and the rivers that border Westfall. Westbrook Garrison is nearby, yet Stormwind has too few soldiers to keep the woods clear of wild beasts and raiding parties. Boars roam among the trees and along the banks. Riverpaw gnolls gather in force, using the woods as a staging ground. Hogger and his pack hunt through the woods of Forest's Edge. He is a massive, brutal gnoll chieftain who leads raids on nearby farms and harasses travelers. The Stormwind Army has placed a bounty on his head. His pack makes the timberland dangerous for anyone crossing it.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forest-s-edge-cf2bb5419f3fff406794/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["subzone:forest-song"] = {
  hash = "df6ccc",
  fullHash = "5e635b",
  text = "Forest Song. In northeastern Ashenvale, Forest Song keeps watch near Satyrnaar and Bough Shadow. The ancient kaldorei ruins lie mostly deserted, with Kayneth Stillwind guarding the eastern border. Forest Song’s white columns and broken arches rise among the trees of northeastern Ashenvale. Once an elegant kaldorei settlement, the ruin now lies overgrown with ivy and wild ferns. Satyrnaar lies southwest, while the Warsong Lumber Camp presses in from the south. Eastern trails lead from here toward Azshara and Bough Shadow. Demonic corruption and Horde incursions trouble the woods, though the ruins remain quiet. Kayneth Stillwind keeps watch over Forest Song alone. From the crumbling outpost, the druid watches for enemies entering the wilderness, including the Forsaken in the eastern forests. Astranaar lies far away, and Forest Song has no garrison fortifications. Still, Alliance travelers bound north for Felwood or seeking the corruption spreading through the canopy can gather here.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forest-song-1a1f68672ada53ad6130/1-0000.mp3", duration = 60.8130612, start = 0},
  },
}
P.transport["subzone:forlorn-cavern"] = {
  hash = "c2b5e4",
  fullHash = "c2b5e4",
  text = "Forlorn Cavern. In Ironforge's northern depths, the Forlorn Cavern shelters those who keep to the shadows. Thieves, cutpurses, and practitioners of the dark arts conduct business there, far from the Great Forge and the dwarven guards. Cold and damp, the Forlorn Cavern lies beneath Ironforge's clang of anvils and the Great Forge's heat. Its winding paths follow the northern edge of the underground lake, hidden between the Mystic Ward and the Hall of Explorers. Rogues and warlocks train there, and vendors serve them. Weapon merchants and fishermen work beside the lake as well.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forlorn-cavern-b617dcd89654f3f14cbe/1-0000.mp3", duration = 33.7502041, start = 0},
  },
}
P.transport["subzone:forlorn-rowe"] = {
  hash = "44c62f",
  fullHash = "44c62f",
  text = "Forlorn Rowe. At Raven Hill Cemetery's northern edge, Forlorn Rowe lies beneath a shadow of dread. Morbent Fel makes his home there, and his magic raises the restless dead across Duskwood. Forlorn Rowe climbs the northern edge of Raven Hill Cemetery in gloom. Morbent Fel makes his home on the hill. The necromancer raises many of the dead who roam the surrounding wilderness. From above, his foul enchantments command skeletal servants, making Duskwood's northwestern corner perilous for travelers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forlorn-rowe-c99f59375d858ee79b13/1-0000.mp3", duration = 28.7085714, start = 0},
  },
}
P.transport["subzone:freewind-post"] = {
  hash = "91bae6",
  fullHash = "91bae6",
  text = "Freewind Post. Freewind Post guards the Horde’s hold in Thousand Needles from a high canyon mesa. Tauren lifts and winding rope bridges lead to its refuge, where the Horde faces centaur warbands and prepares for the frontier. Freewind Post clings to the canyon mesas, where height helps guard its people. Galak centaur command the arid floor, but cannot climb the sheer cliffs or easily breach the heavy wooden lifts that carry Horde travelers upward. Rope and plank bridges link the post to neighboring spires, sheltering the outpost above.\n\nHarpies screech along the bluffs, while the tauren tend the nearby wyvern grounds at Highperch. There, they cull wild eggs and raise the hatchlings as loyal wind rider mounts for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_freewind-post-07f598fb02271a50a256/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["subzone:frostmane-hold"] = {
  hash = "50006c",
  fullHash = "678f6c",
  text = "Frostmane Hold. Frostmane trolls raid from the cliffs south of Gnomeregan in western Dun Morogh. The Ironforge Guard watches their camp and caverns as the raiders press into dwarven lands. In western Dun Morogh, Frostmane Hold cuts into cold cliffs. Rough structures stand outside its winding caves, where hideskinners and headhunters guard the tribe’s stronghold. From here, Frostmane raiders strike the valleys, threaten travelers on mountain passes, and test the defenses around Kharanos. Dwarven commanders in Kharanos fear the growing Frostmane force. Young mountaineers and adventurers scout the caverns and map their defenses. They thin the warbands before the tribe can gather for an organized assault on dwarven outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_frostmane-hold-eeb997e9d5e319765fc8/1-0000.mp3", duration = 45.4269388, start = 0},
  },
}
P.transport["subzone:frostmane-hovel"] = {
  hash = "e8b62a",
  fullHash = "e8b62a",
  text = "Frostmane Hovel. In southern Coldridge Valley, Frostmane trolls press toward the dwarven training grounds. Frostmane trolls shelter in caverns cut into the mountains south of Coldridge Valley. They refuse to yield the high snows to Ironforge and raid nearby dwarven camps. Their attacks disrupt the supply lines into the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_frostmane-hovel-bf25f2f888eb606414ee/1-0000.mp3", duration = 19.0955102, start = 0},
  },
}
P.transport["subzone:furlbrow-s-pumpkin-farm"] = {
  hash = "49ec78",
  fullHash = "7b13b0",
  text = "Furlbrow's Pumpkin Farm. Bandits and harvest golems hold Furlbrow's Pumpkin Farm in northern Westfall, off the road from Elwynn Forest. Farmer Furlbrow and Verna have lost their home to the Defias Brotherhood. Near Westfall's northern border, Furlbrow's Pumpkin Farm once fed the kingdom. The Defias Brotherhood drove Farmer Furlbrow and his wife Verna from their land. Now mechanical harvest golems roam the fields and attack anyone who approaches. Bandits occupy the farm buildings, while the rightful owners camp beside the road near the Jansen Stead, mourning their home and livelihood. The Defias Brotherhood has claimed homesteads like Furlbrow's while Stormwind's military garrison struggles to protect Westfall's rural farmers. Bandits camp at the farm and use it as a staging ground. Lethal harvest watchers guard the perimeter, leaving travelers on the nearby highway open to ambush.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_furlbrow-s-pumpkin-farm-46fe3be5e90aeef7ea29/1-0000.mp3", duration = 50.2073469, start = 0},
  },
}
P.transport["subzone:galardell-valley"] = {
  hash = "edc173",
  fullHash = "edc173",
  text = "Galardell Valley. Gnolls prowl Galardell Valley beneath the Tower of Ilgalar in northeastern Redridge. The valley threatens the nearby settlements. Redridge gnolls prowl Galardell Valley, beyond the reach of Lakeshire's defenders. They roam the lowlands and camp along the canyon floor, under brutal pack leaders such as Lieutenant Fangore. Above the ravines rises the Tower of Ilgalar, stronghold of the renegade mage Morganth. Together, gnolls and tower make the valley a source of dread for nearby settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_galardell-valley-c8e35640e949d283d74c/1-0000.mp3", duration = 30.6938776, start = 0},
  },
}
P.transport["subzone:gates-of-ironforge"] = {
  hash = "024d0f",
  fullHash = "024d0f",
  text = "Gates of Ironforge. From Dun Morogh, travelers climb to the Gates of Ironforge, where a stone king guards the way into the dwarven capital. The gates open in the mountain face, with High King Modimus Anvilmar's statue just inside. From central Dun Morogh, you climb a winding, fortified ramp through the snowy lowlands to the Gates of Ironforge. Beyond the great portal stands a stone likeness of High King Modimus Anvilmar. He united the dwarven clans before the War of the Three Hammers. The passage opens into the Commons, where Ironforge's trade and banking are centered.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gates-of-ironforge-b3b27357d4be732c2a1f/1-0000.mp3", duration = 33.28, start = 0},
  },
}
P.transport["subzone:goblin-foundry"] = {
  hash = "79e634",
  fullHash = "3cf1ab",
  text = "Goblin Foundry. In the Deadmines, goblins keep the Goblin Foundry working for the Defias Brotherhood. Gilnid oversees the craftsmen and engineers around its great smelting cauldron. Deep beneath Moonbrook, goblin craftsmen and engineers labor for the Defias Brotherhood. Smelters and iron ramps fill the chamber. There, they make anchors and cannonballs. Gilnid, the smelter, oversees the goblin workforce. Craftsmen keep production moving while engineers send remote-controlled golems to defend the workshop. Narrow ramps and molten metal make the chamber dangerous for intruders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_goblin-foundry-19c0b959e41b92cc98d7/1-0000.mp3", duration = 36.3885714, start = 0},
  },
}
P.transport["subzone:gol-bolar-quarry"] = {
  hash = "5e7732",
  fullHash = "5e7732",
  text = "Gol'Bolar Quarry. At Gol'Bolar Quarry, troggs have driven the miners from the snowy hills of southeastern Dun Morogh. The Ironforge dwarves came for stone and ore, but now the dig lies quiet. Ironforge dwarves opened Gol'Bolar Quarry southeast of Kharanos to draw stone and mineral wealth from the mountains. Their digging broke into underground warrens and brought a horde of hostile troggs into the open. The creatures soon drove out the miners.\n\nThe upper camp is now an embattled staging ground. Overseers, tradesfolk, and Prospector Gehn gather dwarven and gnomish recruits there to drive the troggs back and reclaim the pit.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gol-bolar-quarry-0bb759710a050731b348/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["subzone:gol-bolar-quarry-mine"] = {
  hash = "705c48",
  fullHash = "a22b3d",
  text = "Gol'Bolar Quarry Mine. Troggs hold Gol'Bolar Quarry Mine beneath the quarry in eastern Dun Morogh. Dwarves of Ironforge mined its tunnels for stone and rich ore until their picks broke into trogg caverns. Now Hammerspine leads the warband in the deepest shafts. The dwarves' pickaxes broke through a wall into caverns where troggs dwelled. Their mining ended there. Troggs poured from the darkness, overwhelmed the crews, and drove them from the mine. The abandoned shafts remain in trogg hands. Younger troggs roam the quarry's sunlit terraces, but the mine shelters the warband's fiercest fighters. Deep in its cramped tunnels lurks Hammerspine, their vicious chieftain. Local mountaineers still need to reclaim the valuable quarry. To do so, they must reach the mine's deepest shafts and cut off the troggs at their source.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gol-bolar-quarry-mine-7d2c3881cbc05ce47a98/1-0000.mp3", duration = 49.162449, start = 0},
  },
}
P.transport["subzone:gold-coast-quarry"] = {
  hash = "98b36d",
  fullHash = "98b36d",
  text = "Gold Coast Quarry. In southwestern Westfall, the Defias Brotherhood holds Gold Coast Quarry and draws on its remaining riches for rebellion. Once, its stone, minerals, and gold helped rebuild Stormwind. Stormwind once drew stone and gold from Gold Coast Quarry to rebuild the kingdom. After royal troops left Westfall, Defias highwaymen and renegade laborers seized the mine. Now Brotherhood patrols watch from its terraced ramps above the coast and take the minerals still left there to fund their rebellion.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gold-coast-quarry-b70b31a7c410c795be3e/1-0000.mp3", duration = 29.5706122, start = 0},
  },
}
P.transport["subzone:goldshire"] = {
  hash = "d86afe",
  fullHash = "8549d4",
  text = "Goldshire. Goldshire stands where Elwynn’s roads meet, between Stormwind City, Westfall, Redridge, and the southern frontier. Rebuilt after the First War, it offers travelers the Lion’s Pride Inn, while a hard-pressed Stormwind Guard defends the town. Goldshire holds the crossroads in rural Elwynn, where the king’s highways meet. Threats press closer as Stormwind’s forces thin and King Varian Wrynn remains mysteriously absent. Marshal Dughan must rely on passing adventurers instead of regular troops to guard the borders. Riverpaw gnolls push in from the west, while hostile murlocs claim the shores of Stone Cairn Lake and Crystal Lake. Their attacks have killed royal guards and brought danger close to town. Goldshire and Moonbrook were the last strongholds to fall in the First War. Warchief Blackhand cut King Llane Wrynn I off from his realm before sacking Stormwind Keep, and the Orcish Horde overwhelmed both towns. Goldshire was reduced to ash and lay barren until it was rebuilt after the Second War.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_goldshire-fb3cbb78b80a04fcd9a7/1-0000.mp3", duration = 62.4065306, start = 0},
  },
}
P.transport["subzone:grand-vestibule"] = {
  hash = "a1d5c8",
  fullHash = "f8b0d3",
  text = "Grand Vestibule. At the Grand Vestibule, Scarlet sentries guard the passage into the monastery’s inner halls. Crimson pillars and statues of fallen crusaders line the entrance. Past the Scarlet Monastery’s outer gates, you enter a marble hall lined with pillars and statues of armored champions. Scarlet sentries, disciples, and augurs patrol the flagstones. They strike down anyone who enters without the order’s crimson tabard. Here, the Crusade’s strict discipline meets its fervor. Every intruder must cross the Grand Vestibule to reach the monastery’s guarded inner wings. Alliance champions sent north and Horde forces advancing from the nearby Undercity both face the Crusade’s defenders beneath its high arches. Beyond them lie the inner cloisters.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grand-vestibule-0e5315defbc9e6ab54c8/1-0000.mp3", duration = 46.4718367, start = 0},
  },
}
P.transport["subzone:great-forge"] = {
  hash = "7d64f8",
  fullHash = "05a988",
  text = "Great Forge. At Ironforge’s center, the Great Forge keeps its fires burning and smiths at work. Its Great Anvil draws people from across the mountain city. The Great Forge was the first structure the early dwarves built beneath Ironforge Mountain. The capital grew outward in rings around it. Molten stone and slag run from giant foundries through glowing channels, lighting the cavern with an amber haze.\n\nAt the center, Master of the Forge Myolor Sunderfury oversees the massive Great Anvil. Masters of metalwork gather around its rim to hammer armor, tools, and weapons day and night. Smithing is only part of the Great Forge’s work. Guild offices, supply shops, and the city’s main gryphon roost ring the chamber. Gryth Thurden tends the roost, where travelers from across the Alliance mingle amid the hammer blows.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_great-forge-8e56bc374179046a484e/1-0000.mp3", duration = 51.0693878, start = 0},
  },
}
P.transport["subzone:great-lift"] = {
  hash = "0d098a",
  fullHash = "294f73",
  text = "Great Lift. At the Great Lift, travelers cross between the southern Barrens and Thousand Needles. Tauren platforms carry people and supplies between the rim and canyon floor, while quilboar threaten the southern road. At the rim between the southern Barrens and Thousand Needles, two wooden platforms hang over the canyon. Heavy timber, braided rope, and counterweighted pulleys carry caravans, couriers, and warriors across the sheer drop. Brave Moonhorn watches from the top platform, and Grish Longrunner keeps watch below. They guide travelers along the road and help cargo pass safely. The road to the Great Lift crosses hostile ground in the southern Barrens. Quilboar tribes have pushed south and now threaten the route between Thousand Needles and the northern trails. Travelers making the long journey must fend off razorfen raiders before they reach the wooden platforms.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_great-lift-f531460b49f237f21884/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["subzone:greatwood-vale"] = {
  hash = "3d4c9e",
  fullHash = "28ed50",
  text = "Greatwood Vale. In eastern Stonetalon, the Grimtotem hold Greatwood Vale and strike at nearby settlements. The dangerous Webwinder Path leads into the forested valley, now their base for bloody assaults. Greatwood Vale has become a violent frontier off the Webwinder Path. Grundig Darkcloud leads the Grimtotem who have moved into the vale in force. They bar safe passage and terrorize the surrounding foothills. From Greatwood Vale, Grimtotem raiders swept into nearby Camp Aparaje and slaughtered nearly every tauren there. Makaba Flathoof escaped. Now he directs vengeful Horde warriors into the heart of the vale to kill the renegade Grimtotem and end Grundig Darkcloud's rule.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_greatwood-vale-84c2903c3b1763db7282/1-0000.mp3", duration = 42.9453061, start = 0},
  },
}
P.transport["subzone:greenpaw-village"] = {
  hash = "dfe18e",
  fullHash = "aa4be0",
  text = "Greenpaw Village. Greenpaw Village lies between Raynewood Retreat and Silverwind Refuge, where the Foulweald furbolgs remain hostile. Chief Murgut and Shaman Oakpaw lead the corrupted tribe as Alliance and Horde forces clash with them in Ashenvale. South of Raynewood Retreat and northeast of Silverwind Refuge, Greenpaw Village holds the Foulweald furbolgs. Since the Third War, corruption in Ashenvale’s soil and spirits has tainted them. Chief Murgut leads the tribe, with Shaman Oakpaw as their corrupted spiritual guide. Travelers who enter their forest territory face attack. The Foulweald’s attacks bring fighting to every side of Greenpaw Village. Alliance sentinels and night elf druids seek to purge the furbolgs and protect nearby outposts and sacred moonwells. Horde forces advancing through Ashenvale clash with them too, as both factions press through the woodland.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_greenpaw-village-6e3ce1707fddd0e9a34c/1-0000.mp3", duration = 50.5991837, start = 0},
  },
}
P.transport["subzone:grim-batol"] = {
  hash = "11ec6a",
  fullHash = "97645d",
  text = "Grim Batol. Above the eastern Wetlands, Grim Batol's gates remain sealed. A curse drove the Wildhammer dwarves from the fortress, and the Dragonmaw orcs later made it a lair for breeding dragons. Thane Khardros Wildhammer carved Grim Batol from the jagged mountains east of the marsh after the ancient civil war among the three clans. During the War of the Three Hammers, the Dark Iron sorceress Modgud besieged the fortress. Khardros struck her down, but with her dying breath, Modgud cast a foul shadow across its stones.\n\nThe taint lingered in the halls and made them uninhabitable. The surviving Wildhammer dwarves abandoned their kingdom and migrated north into the Hinterlands. During the Second War, Orgrim Doomhammer sent the Dragonmaw clan to claim Grim Batol. The warlock Nekros Skullcrusher led them, and they used the ancient artifact called the Demon Soul to enslave the red Dragonqueen Alexstrasza deep beneath the mountain. Chained there, she was forced to hatch broods for the Horde's war effort until a small band of heroes shattered the artifact.\n\nFreed, the enraged Dragon Aspect incinerated the orcs within. Grim Batol became a desolate ruin, watched closely by surviving red dragons.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grim-batol-cbf9131edca5f289c517/1-0000.mp3", duration = 73.1689796, start = 0},
  },
}
P.transport["subzone:grizzled-den"] = {
  hash = "623b7b",
  fullHash = "4e71ff",
  text = "Grizzled Den. In Dun Morogh, wendigo packs make their lair in Grizzled Den, southwest of Kharanos. Southwest of Kharanos, Grizzled Den cuts into Dun Morogh’s crags. Wendigo packs make their home in its hollows. These aggressive, ape-like beasts breathe frost at intruders and band together to defend their lair. Hunters brave the cavern for thick wendigo manes, used by craftsmen to line cold chairs and carriage seats with insulating fur. Prospectors work copper veins in Grizzled Den’s frozen stone walls. Scouts search its darker corners for discarded footlockers. Deeper in the tunnels, the den’s largest and most vicious predators wait in the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grizzled-den-c54de70c6a0768776f53/1-0000.mp3", duration = 41.5608163, start = 0},
  },
}
P.transport["subzone:grizzlepaw-ridge"] = {
  hash = "67856d",
  fullHash = "67856d",
  text = "Grizzlepaw Ridge. Bears claim the rough hills of Grizzlepaw Ridge, south of Thelsamar in Loch Modan. Local hunters fear Ol' Sooty, a massive bear among them. Grizzlepaw Ridge rises above the road south of Thelsamar, with Stonesplinter Valley along its western edge. Territorial bears threaten travelers skirting the mountains, so those passing between the dwarven settlements watch the tree line and rocky terraces. Deep within the ridge lives Ol' Sooty, an unusually fierce bear feared by local hunters.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grizzlepaw-ridge-628f5d12fc2959e1b2e5/1-0000.mp3", duration = 31.1902041, start = 0},
  },
}
P.transport["subzone:grove-of-the-ancients"] = {
  hash = "14330f",
  fullHash = "e89200",
  text = "Grove of the Ancients. Nature spirits and kaldorei gather in the Grove of the Ancients, where Onu, an Ancient of Lore, keeps watch. Old temple ruins stand beside the Wildbend River in southeastern Darkshore. Old temple stones ring the Grove of the Ancients in southeastern Darkshore. The Wildbend River runs through its heart, offering refuge from a troubled coastline. Nature spirits and kaldorei gather here as the Circle of Ancients. Together, they tend to the forest’s balance. Onu, an Ancient of Lore, watches the land’s changing fortunes and offers wisdom to travelers. Wandering merchants and slumbering druids rest beneath the boughs. To the southeast, territorial furbolg camps hold their ground. Alliance sentinels and druids watch the southern reaches of Darkshore from this frontier outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grove-of-the-ancients-81faa65ae62477508e71/1-0000.mp3", duration = 48.3004082, start = 0},
  },
}
P.transport["subzone:gryphon-roost"] = {
  hash = "30bda3",
  fullHash = "6444dc",
  text = "Gryphon Roost. Gryphons carry travelers from Stormwind’s eastern ramparts across the Eastern Kingdoms. Human gryphon master Dungar Longdrink tends the roost beside the Trade District. Dungar Longdrink arranges flights to Ironforge, Lakeshire, Sentinel Hill, and other Alliance garrisons and settlements. The roost joins Stormwind to these outlying holds. Its trained gryphons wait ready for the journeys ahead. Gryphons and their handlers bring a trace of Hinterlands tradition into Stormwind. The Wildhammer clan has long honored gryphons as partners. During the Second War, they brought aerial warfare and transport to the wider Alliance. Leather, feed, and fresh winds lend the roost a frontier air amid the city’s stonework.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gryphon-roost-31e18a9c8af09b5ef394/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["subzone:hall-of-arms"] = {
  hash = "cfef2e",
  fullHash = "cfef2e",
  text = "Hall of Arms. In Ironforge’s Military Ward, the Hall of Arms readies the city’s forces for battle. Command staff oversee the troops while warriors and hunters train, and machines are prepared for war. The Hall of Arms commands Ironforge’s armed forces from the Military Ward’s southeastern corner. Veteran instructors train warriors and hunters there, while the facility stores and stages machines of war. Steam tanks are assembled and maintained for Alliance battlefields. Gyrocopters and flying machines ride industrial conveyor belts through shafts in the cavern ceiling, then launch toward the Ironforge Airfield above.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-arms-f077970cad91dd645349/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["subzone:hall-of-arms-northshire"] = {
  hash = "1de868",
  fullHash = "1de868",
  text = "Hall of Arms (Northshire). Recruits train with the Stormwind Army in Northshire Abbey’s Hall of Arms, south of the Main Hall. Blunted steel rings through the Hall of Arms, and instruction keeps a measured cadence. South of Northshire Abbey’s Main Hall, human fighters and devout aspirants train for the Stormwind Army. Veteran battle instructors and paladin mentors teach the postures and disciplines needed to defend Elwynn Forest from kobolds, Defias bandits, and gnoll raiders. Across the courtyard, clerics and scholars study ancient tomes in the Library Wing.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-arms-northshire-90639d184d0a201b4bd1/1-0000.mp3", duration = 31.6604082, start = 0},
  },
}
P.transport["subzone:hall-of-explorers"] = {
  hash = "0df4b6",
  fullHash = "0df4b6",
  text = "Hall of Explorers. In Ironforge, the Hall of Explorers draws the dwarves who seek their people's origins. The Explorers' League studies Azeroth's past here. In northeastern Ironforge, the Hall of Explorers fills a cavern with scholars and field agents. High Explorer Muninn Magellas directs their work as they arrange digs in distant lands. Those expeditions bring back relics, ancient titan machinery, and prehistoric bones. At the hall's center, the Library keeps historical lore. Visitors may see its displays, while other records remain restricted.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-explorers-3d6f4f3463f666f9c03b/1-0000.mp3", duration = 33.6718367, start = 0},
  },
}
P.transport["subzone:hall-of-gears"] = {
  hash = "6b6d4f",
  fullHash = "8bd0b8",
  text = "Hall of Gears. In Gnomeregan, the Hall of Gears lies in ruin beyond the Clockwerk Run. Toxic sludge fills its lower floor, where oozes and irradiated troggs roam. Beyond the Clockwerk Run, the Hall of Gears lies deep within Gnomeregan’s ruined machinery halls. Its two levels show how completely the gnome capital has fallen. Irradiated troggs claw through collapsed access shafts and prowl the upper catwalks. Below, radioactive pools cover the floor. Corrosive slimes and living poison elementals thrive in the toxic runoff. The Hall of Gears links parts of Gnomeregan’s operational quarters. From the upper walkways, paths lead to contaminated dead ends, the Clean Zone, and the Dormitory. Below, winding maintenance passages lead toward the Launch Bay. Horrors left by Mekgineer Thermaplugg’s venting scheme still make both levels dangerous.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-gears-9d084a598292f1c50879/1-0000.mp3", duration = 55.3795918, start = 0},
  },
}
P.transport["subzone:hall-of-mysteries"] = {
  hash = "3152f0",
  fullHash = "3152f0",
  text = "Hall of Mysteries. In Ironforge’s Mystic Ward, the Hall of Mysteries gathers dwarven and gnomish practitioners for faith and arcane study. They read ancient texts, learn the Holy Light, and weave enchantments within its blue-lit halls. Blue and purple light marks the Hall of Mysteries among Ironforge’s stone, iron, and heavy plate. Five soaring pillars shelter scholars in flowing robes. Here, the dwarven priesthood and the Order of the Silver Hand hold their headquarters within Khaz Modan. They join arcane study with devotion to the Holy Light.\n\nYoung clerics and knights study texts such as the Tome of Divinity here. They receive guidance before traveling onward to Stormwind’s Cathedral of Light.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-mysteries-6ec11539fa09788b0fe3/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["subzone:helm-s-bed-lake"] = {
  hash = "a0a729",
  fullHash = "a0a729",
  text = "Helm's Bed Lake. In southeastern Dun Morogh, dwarves keep a hole open in Helm's Bed Lake for fresh water. But beasts, troggs, and hostile Dark Iron dwarves make the shore dangerous. The ice is firm enough to cross, but the banks are dangerous. Displaced troggs scavenge along the ridges, and wild beasts prowl the edges. South of the water, hostile Dark Iron dwarves have taken an abandoned lodge. They ambush travelers who pass nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_helm-s-bed-lake-5ef42ff93961b5a0609e/1-0000.mp3", duration = 27.115102, start = 0},
  },
}
P.transport["subzone:heroes-vigil"] = {
  hash = "e43720",
  fullHash = "72724c",
  text = "Heroes' Vigil. On Stone Cairn Lake's island, Heroes' Vigil lies neglected and overrun by renegade wizards. The Stone of Remembrance honors those who fell in the First War. Heroes' Vigil gathers around the Stone of Remembrance on an island in Stone Cairn Lake. Erected after the First War, its inscribed circle honors the soldiers and citizens slain when the Old Horde sacked Goldshire and the surrounding valleys. Once a sacred place of faith and sacrifice, the memorial has slipped from Stormwind's attention. Its grounds are overgrown, and no soldiers tend them. Without a kingdom garrison, outcasts have claimed the island. Rogue wizards control Stone Cairn Lake and the memorial grounds. They practice wild, undisciplined magic beyond the oversight of the Kirin Tor and the Academy of Arcane Sciences. Near the stones lies Henze Faulk's body among other tragic casualties. Travelers can only wonder whether the shrine will know peace again.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_heroes-vigil-8ade6627152e6b24d218/1-0000.mp3", duration = 56.4244898, start = 0},
  },
}
P.transport["subzone:high-seat"] = {
  hash = "736ded",
  fullHash = "40a2c8",
  text = "High Seat. King Magni Bronzebeard holds court in High Seat, between the Commons and the Great Forge. His advisors and historians gather there, and a sealed passage leads down to Old Ironforge. King Magni Bronzebeard hears petitioners and meets with his advisors in High Seat. Royal Historian Archesonus and Senator Barin Redstone stand at his side. From here, Magni directs the defense of the Alliance's northern bastions. High Seat is the seat of power for Khaz Modan, and he leads the kingdom through troubling times across Azeroth. A heavy doorway at the back of the throne room leads down into Old Ironforge. The lower ruins are ancestral halls the dwarves carved before the city was reconfigured around the Great Forge. The passage is sealed and guarded, keeping general traffic from the ancient halls beneath the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_high-seat-92e9b61675d156591e40/1-0000.mp3", duration = 49.2669388, start = 0},
  },
}
P.transport["subzone:highperch"] = {
  hash = "f2d6ef",
  fullHash = "441656",
  text = "Highperch. Wild wyverns nest among the crags of Highperch, above the western Thousand Needles canyon. Their prides guard the heights and their young. Highperch rises from the canyon floor, giving Kalimdor’s native wyverns a rugged refuge. Its height shields them from predators and offers a clear launch for hunts across Thousand Needles.\n\nWyvern prides guard their nests under watchful patriarchs and matriarchs. They fiercely defend their territory from any intruder who reaches their high domain. The cliffs draw a few travelers and hunters willing to brave the climb. Pao'ka Swiftmountain, a tauren scout, is stranded on the heights and needs help reaching Whitereach Post.\n\nThose who climb the cliffs face dozens of razor-sharp talons and venomous tails.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_highperch-5ef4d2fd0c362c9d9af1/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["subzone:hillsbrad-fields"] = {
  hash = "a57ac6",
  fullHash = "89ed05",
  text = "Hillsbrad Fields. In western Hillsbrad Foothills, Hillsbrad Fields face constant attacks from nearby Tarren Mill. Farmers and militia defend one of the few human communities in former Lordaeron to resist the Scourge and the Scarlet Crusade. Hillsbrad Fields stretch from Darrow Hill to the Azurelode Mine. Orchards, pumpkin patches, and pastures there supply Southshore and the surviving Alliance resistance. While much of Lordaeron fell to undeath, the people endured and kept the royal tabard and heraldry of their fallen kingdom.\n\nMagistrate Burnside and the Council of Hillsbrad lead the township as an independent civic body under constant siege. Verringtan, the local blacksmith, and his apprentices arm farmers and laborers to defend their land. High Executor Darthalia and the Forsaken forces at Tarren Mill target Hillsbrad's fertile fields. The Undercity sees the thriving human settlement as a threat on its southern flank, so it directs constant raids against crops, livestock, councilors, and farmers. Hillsbrad's defenders have formed a hardened militia in response. Farmer Ray and Farmer Getz organize ambushes and fight the undead to protect their homes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hillsbrad-fields-19b755242cf402785ee4/1-0000.mp3", duration = 69.4857143, start = 0},
  },
}
P.transport["subzone:howling-vale"] = {
  hash = "b26ec2",
  fullHash = "b26ec2",
  text = "Howling Vale. In north-central Ashenvale, Terrowulf worgen howl through Howling Vale near the Felwood border. Their caves conceal an ancient shrine to Elune, bound to the worgen’s origins on Kalimdor. North of the road to Felwood, the Terrowulf’s howls break Ashenvale’s calm. Ancient trees fill the vale, but corrupted packlords and aggressive wildlife roam beneath them. At its heart, a cave holds the ruined shrine of Mel'Thandris, an ancient night elf priestess. Once devoted to quiet worship, the shrine is now defiled by feral wolf-men. The nearby Sentinels cannot explain where they came from.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_howling-vale-6c115eb0dddf8e1e5755/1-0000.mp3", duration = 40.1240816, start = 0},
  },
}
P.transport["subzone:hushed-bank"] = {
  hash = "854b74",
  fullHash = "854b74",
  text = "Hushed Bank. At Hushed Bank, Duskwood’s western river marks the way from Three Corners toward Stranglethorn Vale. Beasts stalk its quiet shore, where dark mysteries linger. Hushed Bank follows Duskwood’s western edge beside the river that divides the forest from Westfall. A covered wooden bridge carries travelers west, out of the grim wood. Near the bridge, open plains and sunlit farms give way to unnatural twilight. Thick underbrush and creeping fog crowd the riverbanks, where large spiders and hungry forest wolves stalk anyone who strays from the path.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hushed-bank-171bf134d5cb42ab6dcd/1-0000.mp3", duration = 32.9404082, start = 0},
  },
}
P.transport["subzone:iceflow-lake"] = {
  hash = "e0cebc",
  fullHash = "e0cebc",
  text = "Iceflow Lake. In western Dun Morogh, dwarves keep fishing holes open at Iceflow Lake, just north of Brewnall Village. Snow-covered islands rise from its center, where winter wolves prowl under their alpha, Timber. Paxton Ganter and other local dwarves clear thick ice from the lake for drinking water and fish. Bitter cold sweeps the shore, yet it still sustains them.\n\nThe islands are dangerous ground. A fierce pack of wild wolves prowls the icy mounds, led by Timber, a savage gray worg.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_iceflow-lake-450fedae05c958335e66/1-0000.mp3", duration = 32.0522449, start = 0},
  },
}
P.transport["subzone:iris-lake"] = {
  hash = "841e73",
  fullHash = "795ea9",
  text = "Iris Lake. In north-central Ashenvale, Fel corruption has turned Iris Lake yellow-green. Bog beasts prowl its shores. Between Astranaar and Shael'dryn's moonwell, Iris Lake has been fouled since the Third War. Fel energies drift south from the tainted heights of Felwood and poison the basin. Clear water becomes a yellow-green mire, and the native plants and water spirits are twisted. Aggressive bog beasts lash out at travelers who come near. Pollution chokes Iris Lake, yet sacred traces of the past remain along its edges. Rare crystalline stones called Elune's Tears sometimes lie on the muddy banks. Keepers of elven traditions, including Shael'dryn, seek these holy stones to help purify tainted moonwells and resist the demonic blight spreading across Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_iris-lake-0215268a39b4accdfb6c/1-0000.mp3", duration = 47.1510204, start = 0},
  },
}
P.transport["subzone:ironband-s-compound"] = {
  hash = "122035",
  fullHash = "7c38de",
  text = "Ironband's Compound. Dark Iron dwarves now hold Ironband's Compound south of Helm's Bed Lake in eastern Dun Morogh. Sturgy Ironband once used the camp, but its fall has brought danger to travelers and nearby settlements. Sturgy Ironband raised the camp as a staging post in Dun Morogh's snowy wilderness. Dark Iron infiltrators then pushed deep into Bronzebeard territory and seized it. Their forces now stand close to Ironforge, and the outpost threatens the city's edge. Within Dun Morogh, the Dark Iron camp is a grave provocation to Ironforge. The city keeps watch and sends seasoned warriors to recover fallen scouts. They also seek vital intelligence on the Dark Iron threat in the mountain kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ironband-s-compound-6259553cc848c2e0e885/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["subzone:ironband-s-excavation-site"] = {
  hash = "f20f66",
  fullHash = "c551b9",
  text = "Ironband's Excavation Site. In southeastern Loch Modan, troggs have driven the miners from Ironband's Excavation Site. The dig lies south of the Loch and southwest of Farstrider Lodge. Prospector Ironband began the dig to seek the dwarves’ ancient Titan origins. Then the miners disturbed an unusually fierce and large breed of subterranean troggs. The creatures surged from the earth and drove the miners back. Now they camp among scattered tools, broken carts, and half-excavated relics. Troggs hold the site while surviving prospectors wait at its perimeter. Like archaeological efforts in the Badlands, Wetlands, and Uldaman, this dig is caught in danger. The prospectors hope to reclaim their stolen gear and guard exposed artifacts from the ravenous troggs. Strange ancient statues remain among those artifacts, left by long-forgotten builders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ironband-s-excavation-site-815397944d8cbc09753c/1-0000.mp3", duration = 51.2783673, start = 0},
  },
}
P.transport["subzone:ironbeard-s-tomb"] = {
  hash = "06a5f0",
  fullHash = "06a5f0",
  text = "Ironbeard's Tomb. Black and crimson oozes foul Ironbeard's Tomb beside the road north to Dun Modr. Travelers search the slime for possessions swallowed in the graveyard. Beside the road north to Dun Modr, Ironbeard's Tomb overlooks the marshes. A great stone statue, believed to show Ironbeard, watches over the burial plot. Black and crimson oozes now overrun the crypt below and foul the resting place. Dwarves no longer bring their dead here. Those who enter the vaults search among remains swallowed by the slimes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ironbeard-s-tomb-bb03689281493e48bc9e/1-0000.mp3", duration = 30.955102, start = 0},
  },
}
P.transport["subzone:ironclad-cove"] = {
  hash = "3fb148",
  fullHash = "3fb148",
  text = "Ironclad Cove. Deep beneath Westfall, the Defias Brotherhood hides a shipyard in Ironclad Cove. There, they build a war juggernaught with a passage to the sea. At the deepest point of the Deadmines, Ironclad Cove opens into a vast sea cavern, now a fortified dockyard. Edwin VanCleef and the Defias Brotherhood are building an enormous warship here, the juggernaught. Wooden scaffolding, islets, and loading catwalks fill the cavern. Defias pirates, deckhands, and overseers watch over the work.\n\nVanCleef means to do more than raid Westfall's farmsteads. He plans to assemble a private naval force that can bombard Stormwind's shores.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ironclad-cove-61b5625c188d2b16dc86/1-0000.mp3", duration = 40.6987755, start = 0},
  },
}
P.transport["subzone:ironforge-airfield"] = {
  hash = "ba9b56",
  fullHash = "a3fbcb",
  text = "Ironforge Airfield. Gnome flying machines and dwarven mountaineers keep watch at Ironforge Airfield, high above Dun Morogh. Its plateau overlooks jagged crags and the steep descent toward the Wetlands. Above Dun Morogh's trails, gnome flying machines line open strips among the peaks. Dwarven stonework holds the ridgelines, where mountaineers watch the perimeter. Nearby, engineers tend the machines and inspect their engines in the cold. Frostmane trolls dwell in caves near the airfield and harass the dwarven sentries. Across the frozen waters beneath the peaks, dwarven defenders and Stormpike patrols clash with troll raiders. So the outpost remains on guard.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ironforge-airfield-4a4739d8c71c71c38a68/1-0000.mp3", duration = 43.2326531, start = 0},
  },
}
P.transport["subzone:jangolode-mine"] = {
  hash = "3d95aa",
  fullHash = "3d95aa",
  text = "Jangolode Mine. In Westfall, the Defias Brotherhood works Jangolode Mine for itself. The mine once supplied Stormwind City with ore and raw materials. Before Westfall declined, Jangolode Mine sent metal to Stormwind City for rebuilding and supplies. As civil order weakened, the kingdom withdrew its garrisons. The Defias Brotherhood seized the mine to support its own operations. Now the bandits work its rich veins and fiercely defend the shafts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jangolode-mine-66cb79ac74e49c4ed6e2/1-0000.mp3", duration = 26.6710204, start = 0},
  },
}
P.transport["subzone:jansen-stead"] = {
  hash = "14baf8",
  fullHash = "14baf8",
  text = "Jansen Stead. Defias bandits and mechanical Harvest Watchers roam the fields of Jansen Stead, just west of Elwynn. Jansen Stead stands beside the road from Elwynn into Westfall. Once its farm fed the kingdom, but unrest has driven the family from the land. Now mechanical Harvest Watchers patrol the fields alongside brigands. The Watchers are tied to the Defias Brotherhood. Couriers and travelers between Goldshire and Sentinel Hill pass close by.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jansen-stead-7b05b6f56dbea9bb75a7/1-0000.mp3", duration = 26.0440816, start = 0},
  },
}
P.transport["subzone:jasperlode-mine"] = {
  hash = "1f1858",
  fullHash = "a79e15",
  text = "Jasperlode Mine. In north-central Elwynn, kobolds and giant spiders hold Jasperlode Mine. Its shafts once sent iron and minerals to Stormwind City, but the kingdom lacks the strength to reclaim them. Jasperlode Mine once sent a steady supply of minerals to Stormwind, as did nearby Fargodeep. Now the kingdom's forces are stretched thin by threats beyond its borders and unrest at home. Local garrisons cannot guard the shafts. Kobolds drove out the human miners and seized the mine, hoarding stolen gold and tallow candles. Mine spiders have made their home beneath Jasperlode Mine's timber supports. A massive matriarch called Mother Fang leads them. They prey on kobolds who trespass and on unwary prospectors. Salvaging the mine means facing those dangers in its depths.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jasperlode-mine-061b099d48c8d4f3ba0b/1-0000.mp3", duration = 47.3338776, start = 0},
  },
}
P.transport["subzone:jerod-s-landing"] = {
  hash = "1e0827",
  fullHash = "1e0827",
  text = "Jerod's Landing. Defias smugglers hold Jerod's Landing beside the Nazferiti River in Elwynn Forest. Its dock gives them a hidden route for stolen goods across the kingdom's waterways. Defias outlaws control the dock at Jerod's Landing, where Elwynn Forest meets the Nazferiti River. Once an ordinary boat dock, it now receives goods plundered from the Redridge Mountains. A Defias dockmaster watches over the cargo as the outlaws move it downstream toward holdings such as Klaven's Tower in Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jerod-s-landing-71c37796cbf1a1725e5c/1-0000.mp3", duration = 28.7869388, start = 0},
  },
}
P.transport["subzone:kargathia-keep"] = {
  hash = "b17efe",
  fullHash = "add9cc",
  text = "Kargathia Keep. Warsong overseers hold the eastern edge of their lumber camp at Kargathia Keep. The stronghold guards the Southfury River border in Ashenvale and links the outpost to Orgrimmar. At the eastern edge of the Warsong Lumber Camp, Kargathia Keep stands just west of the Southfury River. Spiked barricades guard the outpost, where Overseer Gorthak and his officers direct the Horde’s logging. From the river border, the Warsong clan watches for incursions. When night elf skirmishers strike, reinforcements can come swiftly from Durotar and Orgrimmar. Kargathia Keep takes its name from Kargath Bladefist, famed chieftain of the Shattered Hand clan. Kargath in the Badlands and Bladefist Bay on Durotar’s coast bear his name as well. For Warsong orcs facing Ashenvale’s hostile woodlands, the keep’s imposing walls speak of martial resilience and Horde defiance in lands claimed by the night elves.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_kargathia-keep-c8db4204af2e617ed02d/1-0000.mp3", duration = 55.2228571, start = 0},
  },
}
P.transport["subzone:kharanos"] = {
  hash = "ea401e",
  fullHash = "5eb7c8",
  text = "Kharanos. Travelers leaving Coldridge Valley make Kharanos their primary stop, just down the road from Ironforge. The town has a forge, gnomish workshops, and the famous Thunderbrew Distillery. Along Dun Morogh's central road, Kharanos is the first true town for recruits arriving from Anvilmar. The cold and wind bite hard, but dwarven grit and gnomish ingenuity keep the settlement thriving. Its heart is a roaring public forge and the Thunderbrew Distillery, whose ale is counted among the finest in Khaz Modan and renowned across the eastern mountains.\n\nCrafters work among weary travelers seeking warmth. Together, they make Kharanos an essential place for business in the lower peaks. Behind Kharanos's cozy hearths, a military outpost guards the mountain passes. Fierce indigenous wendigo prowl the frozen caverns directly to the west, while aggressive Frostmane trolls hold Shimmer Ridge to the northwest.\n\nIronforge's regular forces are stretched thin across the realm. So Kharanos relies heavily on visiting adventurers and local watchmen to drive back raiding parties, cull dangerous predators, and keep the trade routes open.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_kharanos-c7a0d611422514c9858b/1-0000.mp3", duration = 68.9110204, start = 0},
  },
}
P.transport["subzone:lake-al-ameth"] = {
  hash = "222b41",
  fullHash = "3fb6dc",
  text = "Lake Al'Ameth. South of Dolanaar, Lake Al'Ameth's shores have grown dangerous as the plants turn violent. Once a quiet haven with little more than a wooden jetty, it is one of Teldrassil's largest freshwater lakes. Timberlings and timberling sprouts prowl the water's edge at Lake Al'Ameth. The lake lies just south of Dolanaar, where calm water and a sparse settlement give little hint of the danger ashore. An unnatural sickness spreading through Teldrassil has driven the plants into a frenzy. So druids and researchers from Dolanaar send travelers to gather seeds and kill the creatures before corruption spreads deeper into the forest. Oakenscowl, once a noble timberling, now spreads corruption from a cave on Lake Al'Ameth's southern bank. A gargantuan tumor has swollen his body, and other timberlings lash out at anyone who comes near. The woodland spirits have lost their balance. Now the Cenarion Circle faces an urgent test: can the rot around the lake be diagnosed and treated, and can Teldrassil's unblessed creation endure?",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lake-al-ameth-2f03987a0682a7c1a456/1-0000.mp3", duration = 58.5926531, start = 0},
  },
}
P.transport["subzone:lake-everstill"] = {
  hash = "1ee5dc",
  fullHash = "e4744a",
  text = "Lake Everstill. Murlocs and lake beasts threaten Lake Everstill beside Lakeshire. Its clear mountain waters once drew anglers, but now the shores and depths are perilous. Lake Everstill fills Redridge's central basin beside Lakeshire. Clear water runs east toward Stonewatch, and a bridge crosses the lake at the heart of town. For years, the lake supported local trade and gave anglers a quiet place to fish. Now danger has broken the calm along its shores. Murlocs have made camps in the northern and eastern shallows. They disrupt trade and harry fishermen. Farther down, dangerous threshers patrol the deep water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lake-everstill-ecfb97d3ef29a50b8e63/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["subzone:lake-falathim"] = {
  hash = "bb0a73",
  fullHash = "a0242d",
  text = "Lake Falathim. Murlocs now overrun Lake Falathim, on Ashenvale’s western shore southwest of Maestra’s Post. Night elves once swam and fished here, drawn by moonlight said to touch the water by day and night. Southeast of the Zoram Strand, Lake Falathim once welcomed Kaldorei who came to swim and fish. Local lore says Elune’s gentle light touches the water at every hour, by day and by night. Now ferocious murlocs have surged inland and seized the shores. Their numbers drive travelers and scholars away. Lake Falathim’s murlocs make it dangerous to wander alone. The night elf scholar Teronis recently went missing near the water while pursuing his inquiry. Sentinels fear for anyone who approaches the moonlit pool alone, with hostile murlocs lurking along the banks and in the shallows.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lake-falathim-e4858c300c2e89b11f56/1-0000.mp3", duration = 46.3934694, start = 0},
  },
}
P.transport["subzone:lakeridge-highway"] = {
  hash = "0354b7",
  fullHash = "4475fb",
  text = "Lakeridge Highway. Gnolls and Blackrock orcs make Lakeridge Highway perilous along Lake Everstill's southern shore. Before the First War, the road carried trade through Redridge; now ruin and danger bar the way. Before the First War, Lakeridge Highway carried goods and travelers through Redridge along Lake Everstill's southern shore. Travelers crossed between the valley settlements and the eastern heights under Stormwind's protection. Then the Horde marched through, and that safety was shattered. Eastern Redridge remains contested and desolate. After Blackrock orcs seized Stonewatch Keep, road repairs and patrols ceased. Lakeridge Highway crumbled into an overgrown track, where savage gnoll packs roam. Stormwind's forces are spread thin and cannot reinforce Lakeshire, so the highway remains officially unsafe. Travelers bound for the eastern ridges face gnoll ambushes along the way.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lakeridge-highway-ac82f1badffe19f00a0c/1-0000.mp3", duration = 51.6440816, start = 0},
  },
}
P.transport["subzone:lakeshire"] = {
  hash = "3de693",
  fullHash = "3de693",
  text = "Lakeshire. Lakeshire's defenders hold the town against orcs, gnolls, and murlocs along Lake Everstill. Magistrate Solomon leads them, while Marshal Marris commands the guard. In the foothills east of Stormwind, Lakeshire once knew peace. Now it is the kingdom's hardest-pressed frontier. Blackrock clan orcs came down from the north and overran the garrison at Stonewatch Keep. Dark wizardry drove Shadowhide gnolls into organized raiding parties.\n\nBlackrock saboteurs broke parts of the Everstill Bridge. Foreman Oslow and his crew struggle to mend the span under threat of attack. Murlocs crowd the lake's shores, and gnolls stalk the high passes. Lakeshire's defenders are close to breaking.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lakeshire-09c63032060e161157be/1-0000.mp3", duration = 42.4489796, start = 0},
  },
}
P.transport["subzone:lakeshire-inn"] = {
  hash = "920702",
  fullHash = "1900c9",
  text = "Lakeshire Inn. At Lakeshire Inn, travelers and townsfolk seek shelter as danger closes around Lakeshire. The inn on Lake Everstill offers food, drink, and a place to hear news amid the town’s troubles. Lakeshire Inn stands on the shore of Lake Everstill, offering a brief rest from the gnoll bands and Blackrock orcs pressing against the town. Lakeshire’s military position grows more desperate, yet the tavern remains warm and welcoming. Barkeep Daniels and Innkeeper Brianna serve ale, wine, and hot meals to locals and travelers. Townspeople gather to trade news, ease their sorrows, and find hired blades to defend the kingdom’s eastern border. Wiley the Black watches the room from a table, keeping his thoughts to himself while watching for dangers in the region. Traveling brewers such as Yorus Barleybrew stop at the inn, as do Darcy Parker and other townsfolk. For those bound for the jagged peaks or south toward Duskwood, Lakeshire Inn is the last safe haven before the contested wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lakeshire-inn-b4a4dae40b530a7e8400/1-0000.mp3", duration = 61.2832653, start = 0},
  },
}
P.transport["subzone:lakeshire-town-hall"] = {
  hash = "6de6ce",
  fullHash = "ec2980",
  text = "Lakeshire Town Hall. At Lakeshire Town Hall, Magistrate Solomon directs Redridge's affairs from the heart of Lakeshire. Blackrock orcs and gnolls threaten the lakeside settlement. Lakeshire Town Hall has been refurbished many times over the years. The aging stone building stands prominently in Lakeshire, where it once served as a quiet administrative office. It houses Magistrate Solomon, a kind and dedicated civil leader who keeps order in the eastern reaches of the Kingdom of Stormwind.\n\nNow Stormwind's military is stretched thin and royal aid is scarce. The hall has become an active command center, where desperate appeals for volunteer defenders and mercenaries are handled each day. Gnoll incursions and advancing Blackrock orcs have driven Magistrate Solomon to desperation. With aid scarce, he readily accepts help from independent adventurers who come through the town hall doors.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lakeshire-town-hall-02d581a7bb025ec60a2e/1-0000.mp3", duration = 53.1069388, start = 0},
  },
}
P.transport["subzone:library-ironforge"] = {
  hash = "10e7ed",
  fullHash = "aa3758",
  text = "Library (Ironforge). In Ironforge, the Explorers' League keeps its histories and recovered relics in the Library. The eastern wing of the Hall of Explorers holds books and artifacts gathered across Azeroth. In the Hall of Explorers, dwarven scholars study relics and field reports in a great chamber. The Explorers' League keeps the Library, where shelves hold chronicles of the War of the Three Hammers, the ancient Troll Wars, and the origins of the dwarven race. Librarian Mae Paledust helps visitors find rare books and records. Curator Thorius oversees displays of finds from deep excavations, abandoned ruins, and distant shorelines. League members study, preserve, and display these objects. The collection ranges from crude murloc idols and carved knives to relics recovered frozen in northern ice. Curators record each find as they piece together the history of the Titans and early Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_library-ironforge-86e20f5600abc882ab5a/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["subzone:library-wing-northshire"] = {
  hash = "bc8c18",
  fullHash = "bc8c18",
  text = "Library Wing (Northshire). In Northshire Abbey, the Library Wing gathers scholars and new priests and mages. They prepare to join Stormwind’s defense. The Library Wing opens south from Northshire Abbey’s Main Hall. Dusty shelves, lecterns, and quiet alcoves fill its rooms. Here aspiring mages and priests study the Arcane and the Holy Light. Across the abbey, recruits drill in the Hall of Arms.\n\nPriestess Anetta guides novice priests in faith and healing. Khelden Bremen teaches budding mages to shape primal elemental energy.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_library-wing-northshire-064a02c855003f635933/1-0000.mp3", duration = 32.3918367, start = 0},
  },
}
P.transport["subzone:lion-s-pride-inn"] = {
  hash = "b7aa6c",
  fullHash = "b7aa6c",
  text = "Lion's Pride Inn. At the Lion's Pride Inn, travelers rest and find work just south of Stormwind. Innkeeper Farley welcomes them to Goldshire's gathering place in Elwynn Forest. Goldshire's crossroads bring travelers to the Lion's Pride Inn. Innkeeper Farley keeps the old motto: “Rest and relaxation for the tired and cold.” Hearths, strong drinks, and rooms welcome weary travelers from Northshire. The roads link Stormwind with Westfall, Redridge, and Duskwood, so town marshals, local crafters, and seasoned trainers gather here to share news and hire passing mercenaries.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lion-s-pride-inn-c6128faa32e15df595c7/1-0000.mp3", duration = 36.1795918, start = 0},
  },
}
P.transport["subzone:long-wash"] = {
  hash = "99b5c3",
  fullHash = "99b5c3",
  text = "Long Wash. Murlocs now threaten the shore of Long Wash, south of Auberdine and toward Ameth'Aran beneath Darkshore's gray sky. Long Wash is Darkshore's shortest stretch of distinct coast, despite its name. Beneath the region's perpetual overcast skies, damp sand lies strewn with flotsam, driftwood, and sea creatures washed up by the Veiled Sea. Crabs comb the surf, but travelers heading south from Auberdine must watch for murloc tribes camped at the water's edge. The murlocs attack anyone who enters the ground where they scavenge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_long-wash-bb60ca912e02a2073b14/1-0000.mp3", duration = 32.522449, start = 0},
  },
}
P.transport["subzone:longshore"] = {
  hash = "a5d030",
  fullHash = "a5d030",
  text = "Longshore. Murlocs command the surf at Longshore, where broken ships lie beneath the waves. Along Westfall’s western coast, Longshore stretches wide with unbroken sand. Travelers find little peace here. Murlocs rule the surf, and Old Murk-Eye is among their feared leaders. Sunken ships, including ruined elven destroyers, lie in the shallows.\n\nNear the south, Daphne Stilwell’s isolated farm faces Defias bandits. Across the water, you can see the Westfall Lighthouse.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_longshore-b308952ca513b58dcd71/1-0000.mp3", duration = 31.6604082, start = 0},
  },
}
P.transport["subzone:lordamere-lake"] = {
  hash = "8f21ab",
  fullHash = "8f21ab",
  text = "Lordamere Lake. Between Tirisfal Glades, Silverpine Forest, and the Alterac Mountains, Lordamere Lake lies under the shadow of the undead. Once the northern heart of human life, its cold waters and islands are now haunted by Scourge necromancers and feral murlocs. Lordamere Lake once joined the northern centers of human power. The Capital City of Lordaeron guarded its northern shores, Dalaran rose near its southern reach, and Alterac lined its eastern edge beneath the mountains. Merchant vessels and fishing boats crossed the broad lake without fear. After the devastation of the Third War, the lake became a natural barrier between Forsaken-held Tirisfal and Silverpine and the treacherous heights of Alterac.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lordamere-lake-e6f6e6dc86cb31887d87/1-0000.mp3", duration = 42.1355102, start = 0},
  },
}
P.transport["subzone:maclure-vineyards"] = {
  hash = "2a778d",
  fullHash = "2a778d",
  text = "Maclure Vineyards. In southern Elwynn, grapes and wine from Maclure Vineyards go to Stormwind. The Maclure estate is known for its harvest and its bitter feud with the neighboring Stonefields. In southern Elwynn Forest, the Maclures tend their fields and make wine. Yet the Stonefields, who live down the road, cast a shadow over that daily labor. Accusations of theft and old resentment keep tempers high between the households. Hungry boars prowl the land, while kobolds press toward both homesteads.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_maclure-vineyards-65bafe26beccf9656612/1-0000.mp3", duration = 28.6302041, start = 0},
  },
}
P.transport["subzone:maestra-s-post"] = {
  hash = "fd4768",
  fullHash = "167eb4",
  text = "Maestra's Post. Along western Ashenvale's road, Maestra's Post guards the way between Astranaar and the Ruins of Ordil'Aran. Night elven Sentinels hold the settlement, where a few humans serve the Alliance. Maestra's Post keeps watch beneath the trees of western Ashenvale. A slender night elven tower and an open lodge mark the settlement beside the road from the coast of Darkshore to Astranaar. Sentinels scan the wilds as corrupted furbolg stir nearby. Horde movements also threaten Alliance supply lines. At Maestra's Post, a handful of human allies live among the night elven Sentinels. Feero Ironhand and Delgren the Purifier bring martial strength and devotion to the holy Light in service of the Alliance. This remote campsite is an early meeting place between the eastern kingdoms and Kalimdor's ancient defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_maestra-s-post-75c32e6e7e760d367ff6/1-0000.mp3", duration = 49.6326531, start = 0},
  },
}
P.transport["subzone:mage-quarter"] = {
  hash = "134977",
  fullHash = "134977",
  text = "Mage Quarter. Across the canals in southwestern Stormwind, Mage Quarter draws the kingdom's spellcasters. The Wizard's Sanctum rises above its streets, while shops supply their craft. The quarter also holds sorcery the kingdom's high conjurers forbid. Bridges from Cathedral Square and the Trade District lead into Mage Quarter, where the Alliance's mystic needs are met. Human and allied spellcasters gather around the Wizard's Sanctum to study arcane magic and train apprentices. Nearby shops sell tailoring cloth, reagents, alchemical supplies, and enchanted staves. This close-knit district serves research and the kingdom's defense.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mage-quarter-b1a3c2f36fa26a0628ba/1-0000.mp3", duration = 37.9820408, start = 0},
  },
}
P.transport["subzone:main-hall-northshire"] = {
  hash = "3f6123",
  fullHash = "3f6123",
  text = "Main Hall (Northshire). Newcomers report to the Main Hall at Northshire Abbey in western Elwynn. From there, they reach the Hall of Arms, the Library Wing, and the abbey tower before receiving their first assignments defending Stormwind. Trainees and clerics pass through the Main Hall when they enter Northshire Abbey. The chamber joins the Hall of Arms, where recruits prepare for battle, to the Library Wing and the stairs to the abbey tower.\n\nStrife in the valley reaches even this quiet place. Officers gather able newcomers here to defend the kingdom's borders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_main-hall-northshire-be43579efaa6db3a8fd2/1-0000.mp3", duration = 32.0522449, start = 0},
  },
}
P.transport["subzone:malaka-jin"] = {
  hash = "726d21",
  fullHash = "d079ba",
  text = "Malaka'jin. In Malaka'jin, Darkspear hunters shelter Horde travelers climbing from the Barrens into the lower Stonetalon hills, south of Grimtotem Post. Beside the main trail into the Stonetalon Mountains, troll hunters keep a small camp among the crags and scrublands. They trade supplies and fresh game with travelers passing through. They also watch for mountain predators and Grimtotem tauren farther up the trails. Near the Barrens boundary, Malaka'jin gives the Horde an early foothold in Stonetalon. Sun Rock Retreat lies farther north as a larger stronghold. Here, Horde trackers watch for tribal unrest and guard the winding roads against threats.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_malaka-jin-c97a3a75f54cbe6c6b5e/1-0000.mp3", duration = 40.7771429, start = 0},
  },
}
P.transport["subzone:manor-mistmantle"] = {
  hash = "ec5d62",
  fullHash = "ec5d62",
  text = "Manor Mistmantle. In northeastern Duskwood, Manor Mistmantle lies north of Darkshire. The old family homestead has fallen to ruin, and ghouls prowl its grounds. West of Beggar's Haunt, decay chokes the ruined grounds of Manor Mistmantle. Vicious ghouls guard the broken house. In the untended garden, the Tear of Tilloa blooms alone, the last sign of living beauty on the estate.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_manor-mistmantle-6297b0d78b4eed53847e/1-0000.mp3", duration = 23.9281633, start = 0},
  },
}
P.transport["subzone:mast-room"] = {
  hash = "10ae5d",
  fullHash = "10ae5d",
  text = "Mast Room. In the Deadmines, timber from Westfall reaches the Mast Room, where goblin woodcarvers shape it for the Defias.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mast-room-b349834a4dbac7661f1a/1-0000.mp3", duration = 7.18367347, start = 0},
  },
}
P.transport["subzone:master-s-glaive"] = {
  hash = "6349d9",
  fullHash = "a738ce",
  text = "Master's Glaive. In southwestern Darkshore, Twilight's Hammer cultists now swarm around the Master's Glaive. Night elves once revered this ancient site, where a colossal weapon and a petrified skull recall a forgotten clash. At the Master's Glaive, an adamantine blade pierces a colossal petrified skull. No record names the creature or the hand that drove the blade home. Onu, the Ancient of Lore, says only that an old, old lord of the earth fell here. For generations, night elves believed only the titans could wield a weapon so vast. The blade and skull remain as a monument to that forgotten clash. For generations, night elves held the Master's Glaive in solemn reverence. Now Twilight's Hammer fanatics camp around the sunken carcass, digging trenches and uncovering petrified ribs. Whispers beneath the stone draw them to study the remains and commune with the malevolent power that clings to them. They seek to revive or harness whatever fell essence sleeps within the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_master-s-glaive-d7c174cc72a4904050b4/1-0000.mp3", duration = 59.2979592, start = 0},
  },
}
P.transport["subzone:menethil-harbor"] = {
  hash = "274589",
  fullHash = "7f6400",
  text = "Menethil Harbor. From its island off the Wetlands' western shore, Menethil Harbor links the Eastern Kingdoms to Kalimdor. Stone battlements and Menethil Keep's towers guard the port, where merchants, off-duty soldiers, and salty adventurers gather. Named for King Terenas Menethil II of Lordaeron, Menethil Harbor gives the Alliance a haven on the Wetlands coast. Its remote marshland setting leaves the town exposed, so massive walls, a single bridged causeway, and the four stone watchtowers of Menethil Keep guard it. Ships from Menethil Harbor cross the ocean to theramore isle in dustwallow marsh and, by way of southshore, auberdine in Darkshore. They carry trade and diplomats across the sea, while off-duty Kul Tiran marines spend their wages at the Deepwater Tavern.\n\nPeace remains fragile. The Dragonmaw clan contests inland supply paths through Dun Algaz, and Dark Iron raiders press the northern marshes. Captain Stoutfist and the harbor garrison stay on constant alert.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_menethil-harbor-3507d4d52ae75d601f41/1-0000.mp3", duration = 61.8318367, start = 0},
  },
}
P.transport["subzone:military-ward"] = {
  hash = "55c863",
  fullHash = "2e9946",
  text = "Military Ward. In Ironforge, red banners gather the city's defenders in the Military Ward. Its halls, barracks, weapons masters, siege engines, and flying machines ready the mountain city's military. Along the northern edge of Ironforge, the Military Ward gathers the city's defenses. At its heart, the Hall of Arms holds warrior and hunter trainers and battlemasters. Nearby hangars house dwarven flying machines and steam tanks.\n\nDrill squares and training dummies fill the ward, with supply shops close at hand. Craghelm's Plate and Chain, Goldfury's Hunting Supplies, and Timberline Arms serve those who train and defend the city. Mountaineers and city defenders gather here before setting out. Red banners cover the Military Ward, unlike the Commons' pale blue and the Great Forge's fiery orange. Soldiers drill and inspect their weapons, then gather with off-duty guards for ale at Bruuk's Corner.\n\nWeapon Master Buliwyf Stonehand teaches recruits the ancient martial traditions of the dwarves.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_military-ward-027c4b8f6ea3830b803e/1-0000.mp3", duration = 61.8057143, start = 0},
  },
}
P.transport["subzone:mirage-raceway"] = {
  hash = "105565",
  fullHash = "204643",
  text = "Mirage Raceway. Rocket cars race across the salt flats at Mirage Raceway. Goblin tinkerer Pozzik and gnome engineer Fizzle Brassbolts test their machines as Horde and Alliance supporters gather to wager and cheer. Across the white salt flats, Pozzik and Fizzle Brassbolts keep up their fierce rivalry. The goblin tinkerer and gnome engineer each built a rocket-powered drag car, then gathered a crew to race it in daily showdowns. Their contest draws invention, sabotage, and testing to the flats. Each crew hunts for a mechanical advantage. Horde and Alliance supporters gather at the raceway. Spectators cheer for gnome precision or goblin firepower, while gamblers and shady opportunists thrive on wagers over the results. The camps also serve as a busy trading depot for travelers journeying between Thousand Needles and the blazing sands of Tanaris.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mirage-raceway-c93153a56c6c309342f0/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["subzone:mirkfallon-lake"] = {
  hash = "6f02da",
  fullHash = "226163",
  text = "Mirkfallon Lake. Mirkfallon Lake gathers wildlife beneath Windshear Crag in the Stonetalon Mountains. Thunder lizards and wyverns crowd its banks, while aggressive slimes make its waters dangerous. The slopes of the Stonetalon range send their runoff down to Mirkfallon Lake, at the range's heart. It lies between Webwinder Path to the south and Stonetalon Peak to the north. Thunder lizards come down from the highlands to drink, and wyverns leave their roosts overhead. Strange slimes bubble in the water, making the crossing hazardous for travelers. Paths meet across the lake basin. To the east, rocky tracks climb into Windshear Crag and the logging operations in its forested valleys. Northward, travelers climb toward night elven sanctums and tauren heights. Southward, the route skirts venomous spider hollows. Scouts and explorers crossing these contested mountains must reckon with dangers that shift around the lake.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mirkfallon-lake-140dfc083589aa7369db/1-0000.mp3", duration = 55.1183673, start = 0},
  },
}
P.transport["subzone:mirror-lake"] = {
  hash = "8209e1",
  fullHash = "8209e1",
  text = "Mirror Lake. Water falls into Mirror Lake beneath Stormwind’s cliffs in northwestern Elwynn Forest. An orchard stands nearby, where Defias bandits prowl and mages watch the forest’s arcane currents. Mirror Lake rests beneath Stormwind City's walls, where fishermen and tired travelers can seek a quiet rest. Yet Defias Brotherhood brigands stalk the surrounding orchards, making a long stay perilous for locals.\n\nMystical disturbances across Azeroth have begun to warp the forest's natural channels of arcane energy. Mages from the Wizard's Sanctum watch the lake closely. They send practitioners to sample its currents and guard against chaotic arcane runoff poisoning communities downstream.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mirror-lake-0c892fe85447f7156367/1-0000.mp3", duration = 42.5273469, start = 0},
  },
}
P.transport["subzone:mirror-lake-orchard"] = {
  hash = "cba9ce",
  fullHash = "cba9ce",
  text = "Mirror Lake Orchard. Defias bandits now hold Mirror Lake Orchard on Mirror Lake’s southern shore in western Elwynn Forest. With Stormwind’s guards stretched thin, the grove near Thunder Falls lies exposed. Mirror Lake’s clean waters once sustained the farmstead. Now outlaws across Elwynn seek shelter in rural homes. The orchard’s cottage and grounds give the Defias Brotherhood a place to hide near Thunder Falls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mirror-lake-orchard-6b14f38c7a25a6d0e29b/1-0000.mp3", duration = 25.2081633, start = 0},
  },
}
P.transport["subzone:mist-s-edge"] = {
  hash = "baff8e",
  fullHash = "347262",
  text = "Mist's Edge. North of Auberdine, Mist's Edge follows Darkshore's western shore under ocean fog. Gray beaches hold wrecks, the remains of great sea creatures, crabs, and murlocs. Along Darkshore's western edge, Mist's Edge is a shore of damp sand and rocky tidepools beneath coastal fog. Shattered vessels and drift timber lie among the remains of huge sea creatures. Crabs forage along the beach, while murloc tribes make their homes in the surf. Lost vessels leave wreckage and discarded cargo along these sands. Night elf sentinels and scavengers watch the coast. Yet murloc encampments menace travelers making their way along the shore from Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mist-s-edge-bf3384890de0d4b0df79/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["subzone:misty-pine-refuge"] = {
  hash = "fdb87c",
  fullHash = "fdb87c",
  text = "Misty Pine Refuge. In central Dun Morogh, the Argent Dawn keeps a small outpost at Misty Pine Refuge. Misty Pine Refuge is an unassuming Argent Dawn outpost among Dun Morogh's windswept hills. Ironforge mountaineers patrol the crags nearby. Father Gavin, the order's lone agent here, keeps a quiet hearth amid bitter cold and danger on the mountain roads.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_misty-pine-refuge-1597b6f58cff1b30617f/1-0000.mp3", duration = 21.9428571, start = 0},
  },
}
P.transport["subzone:mo-grosh-stronghold"] = {
  hash = "b821fa",
  fullHash = "b821fa",
  text = "Mo'grosh Stronghold. In northeastern Loch Modan, Mo'grosh Stronghold threatens the dwarven settlements below. Ogres raid supply caravans from caves and outer camps among ancient ruins. Mo'grosh ogres raid supply caravans in northeastern Loch Modan. Their caves and outer camps threaten travelers and the peace of Thelsamar. Rugged stonework scattered through the camp points to an older settlement. The ogres claimed the site and raised their distinctive mounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mo-grosh-stronghold-e5391455a9e991933e05/1-0000.mp3", duration = 27.1934694, start = 0},
  },
}
P.transport["subzone:molsen-farm"] = {
  hash = "65e49d",
  fullHash = "65e49d",
  text = "Molsen Farm. In Westfall, Molsen Farm lies empty, its fields gone untended. Once fertile land that fed Stormwind, it fell into ruin after the Defias Brotherhood rose and mechanical harvest golems were left prowling there. Molsen Farm is one of Westfall's ruined homesteads, exposed by the kingdom's neglect and the criminal uprising. When the Defias Brotherhood took control of the countryside, farmers here were driven out or worse. They left their crops and buildings behind. Now hostile mechanical Harvest Watchers and wandering outlaws scour the fields, where laborers once gathered grain. The farm is dangerous for anyone traveling through the province.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_molsen-farm-7be1b8e734986be90a5d/1-0000.mp3", duration = 39.7583673, start = 0},
  },
}
P.transport["subzone:moonbrook"] = {
  hash = "5ec6be",
  fullHash = "5ec6be",
  text = "Moonbrook. In southwestern Westfall, Moonbrook lies under Defias control, and its peaceful residents have fled. The Brotherhood guards the town above its hidden headquarters in the Deadmines. Before the First War, Moonbrook stood at the heart of Westfall’s breadbasket. Farming families and the Deadmines gold shafts depended on the town. The Old Horde razed it, but Moonbrook rose again after the Second War.\n\nPeace did not last. The House of Nobles in Stormwind neglected the settlement and stripped away its military protection. Unable to resist the red-masked bandits, the people fled their homes for Sentinel Hill and Elwynn Forest. Citizens and teachers left alike.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_moonbrook-8c9c14a079f2b612e286/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["subzone:moonbrook-schoolhouse"] = {
  hash = "2dda66",
  fullHash = "2dda66",
  text = "Moonbrook Schoolhouse. In Moonbrook's northwestern corner, Defias outlaws occupy the schoolhouse, with a small graveyard behind it. Stalvan Mistmantle once taught local children there. The mayor commissioned Stalvan Mistmantle to run a school after he began tutoring local children. In Moonbrook's brighter days, the town prospered and students filled the hall. Now outlaws occupy the building, while weathered headstones in the rear cemetery look out over Westfall's decline.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_moonbrook-schoolhouse-6460ab71207c2c11d26a/1-0000.mp3", duration = 27.3763265, start = 0},
  },
}
P.transport["subzone:moonshrine-ruins"] = {
  hash = "f101a1",
  fullHash = "f101a1",
  text = "Moonshrine Ruins. Deep in Blackfathom Deeps, the Moonshrine Ruins lie flooded and held by the Twilight's Hammer. Their halls once honored Elune, but now the cult performs dark rituals among the ancient stones. Beyond the cavernous Pool of Ask'ar, the Moonshrine Ruins lie along the Ashenvale coast. Their halls once rang with chants to Elune, the Moon Goddess. The Great Sundering shattered the temple and drowned its lower levels in seawater.\n\nMurky waters churn with aggressive crabs and serpentine threshadons. The Twilight's Hammer holds the stones and performs dark rituals that mock the shrine's sacred beginnings.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_moonshrine-ruins-059da195d3a50e92d167/1-0000.mp3", duration = 38.1387755, start = 0},
  },
}
P.transport["subzone:moonspray"] = {
  hash = "8dd2d3",
  fullHash = "8dd2d3",
  text = "Moonspray. Moonspray carries travelers across the sea between Darkshore and Teldrassil. The Alliance ship sails between mainland Kalimdor and the great World Tree. Moonspray carries travelers between Auberdine and Rut'theran Village. Across the Veiled Sea, it bears adventurers, couriers, and provisions from Darkshore's coast to the night elf sanctuary at Teldrassil's crown.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_moonspray-7921fec5b61ce2555b25/1-0000.mp3", duration = 23.562449, start = 0},
  },
}
P.transport["subzone:moonwell-ashenvale"] = {
  hash = "216bba",
  fullHash = "216bba",
  text = "Moonwell (Ashenvale). In central Ashenvale, the Moonwell of Purity rests east of Iris Lake and west of Raynewood Retreat. Its waters carry Elune's grace to nourish the forest and cleanse foulness from the land. Alliance travelers following Raene Wolfrunner's research seek Shael'dryn beside its basin. Beneath central Ashenvale's canopy, this moonwell is a sacred place for the kaldorei. Its shining waters draw on nature's magic and the light of Elune. Satyr corruption, fel taint, and logging harm the surrounding forest. Shrines of pure water are vital to those working to heal the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_moonwell-ashenvale-b2d06d67d171469d1d8f/1-0000.mp3", duration = 36.9371429, start = 0},
  },
}
P.transport["subzone:mor-shan-rampart"] = {
  hash = "9b9d12",
  fullHash = "7171f2",
  text = "Mor'shan Rampart. At Mor'shan Rampart, Horde guards hold the northern end of the Gold Road and the way into Ashenvale. The Warsong clan raised the barricade to shield Horde territory from night elf counterattacks and to stage raids into the forest. At the northern end of the Gold Road, Mor'shan Rampart guards the meeting of the Barrens and Ashenvale. Its timber walls and watchtowers were raised against night elf strikes over the Horde's logging. From here, raiding parties head north toward Astranaar. Warsong fighters and sentries keep Mor'shan Rampart ready for battle. They watch the tree line for night elf scouts and archers. The post also keeps supply lines open between Ashenvale's frontline outposts and Horde settlements to the south.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mor-shan-rampart-0f4bdab1cc7ce02083a7/1-0000.mp3", duration = 42.0310204, start = 0},
  },
}
P.transport["subzone:mortwake-s-tower"] = {
  hash = "c7771a",
  fullHash = "c7771a",
  text = "Klaven's Tower. In southeastern Westfall, Klaven's Tower guards a river crossing near the kingdom's borders. Klaven Mortwake commands the tower, where stolen goods pass along Defias routes. North of the Dagger Hills, Klaven's Tower anchors the Defias Brotherhood's work in southern Westfall. Across the river in Elwynn Forest, Jerod's Landing receives and stages goods plundered from the Redridge Mountains. Together, the two sites move contraband toward Westfall.\n\nFrom the tower, the Brotherhood watches the waterways and slips supplies past Kingdom patrols. This helps shield its supply routes from the crown's eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mortwake-s-tower-5e29fe649cd4fdd7fbb1/1-0000.mp3", duration = 36.9893878, start = 0},
  },
}
P.transport["subzone:mystic-ward"] = {
  hash = "8a7820",
  fullHash = "8a7820",
  text = "Mystic Ward. Faith and arcane study share Ironforge's Mystic Ward, a quieter quarter of the city. Pale blue banners mark its halls, and priests, paladins, and mages gather beneath stone arches in the Hall of Mysteries. The Mystic Ward is where Ironforge turns to faith and learning. Pale blue banners mark the quarter between the Commons, the Forlorn Cavern, and the Great Forge. Shops such as The Fighting Wizard and Maeva's Mystical Apparel supply scholars and spellweavers with regalia, scrolls, and alchemical reagents. At the Hall of Mysteries, followers of the Holy Light and arcane practitioners find guidance in wielding unseen powers to defend the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mystic-ward-279752d9398f6d21c42d/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["subzone:mystral-lake"] = {
  hash = "00b79a",
  fullHash = "9d95e3",
  text = "Mystral Lake. Travelers from the Horde and Alliance come to Mystral Lake in south-central Ashenvale. Its deep waters draw them beneath the night elves’ watch. Mystral Lake draws travelers to its shores in southern Ashenvale. It lies south of Silverwind Refuge and east of Talondeep Vale, and no lake in the forest is larger. Night elves keep watch from their outpost on the northern shore. Travelers of both the Horde and the Alliance often find their journeys bringing them here. Horde shaman come to Mystral Lake during trials of elemental communion. In its deep waters, they seek to understand the element of water. The lake’s primal resonance makes it an essential pilgrimage for those learning to bind and respect the tidal spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_mystral-lake-ec7266c73be756424a44/1-0000.mp3", duration = 41.5085714, start = 0},
  },
}
P.transport["subzone:night-run"] = {
  hash = "21998f",
  fullHash = "21998f",
  text = "Night Run. In east-central Ashenvale, the Felmusk satyr hold Night Run among ancient elven ruins. Dark soul magic gathers within their outpost. Night Run is Ashenvale’s smallest and most isolated of its three great satyr strongholds, with Xavian and Satyrnaar. Crumbling elven stonework and broken pillars shelter the settlement on a high ridge, ringed by steep cliffs no traveler can cross.\n\nYou can follow the Falfarren River near Xavian’s waters, then turn west up the ridge. Or take the precarious northern ledge above Raynewood Retreat. The Felmusk satyr have joined the shadowy Cult of the Dark Strand. Together they anchor twisted soulgems here to gather demonic essence in the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_night-run-160bdd2e0972d1ee8105/1-0000.mp3", duration = 43.7289796, start = 0},
  },
}
P.transport["subzone:nightsong-woods"] = {
  hash = "10a81c",
  fullHash = "10a81c",
  text = "Nightsong Woods. In eastern Ashenvale, Nightsong Woods is a forest where night elves and the Warsong clan fight over lumber and old corruption lingers. Nightsong Woods is Ashenvale’s eastern battleground. The Falfarren River cuts through the western forest, dividing Alliance settlements from Horde incursions. Farther east, Splintertree Post directs Horde campaigns against the Silverwing Sentinels.\n\nWarsong orcs fell the southern groves for lumber to fuel the Horde’s expansion, and the Kaldorei fight back. Satyr strongholds at Satyrnaar and Xavian taint the eastern forest, along with demonic remnants at Demon Fall Canyon and Felfire Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_nightsong-woods-e9c109dcdfe8ca9e1b56/1-0000.mp3", duration = 39.0791837, start = 0},
  },
}
P.transport["subzone:north-gate-outpost"] = {
  hash = "eb7f50",
  fullHash = "eb7f50",
  text = "North Gate Outpost. At North Gate Outpost, mountaineers guard the road where Dun Morogh meets Loch Modan. Their patrols shield travelers from beasts in the crags. Dwarven mountaineers watch North Gate Pass from the outpost. They guard travelers heading through the mountain tunnels into Loch Modan. The pass marks Dun Morogh’s northeastern edge, where harsh weather and steep ravines make patrols perilous. When patrols go missing or predators threaten the road, the garrison calls on travelers to scout the ridges.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-gate-outpost-b2c7a8e5aafbc9c30326/1-0000.mp3", duration = 28.4212245, start = 0},
  },
}
P.transport["subzone:north-gate-pass"] = {
  hash = "3ce90c",
  fullHash = "3ce90c",
  text = "North Gate Pass. Travelers cross North Gate Pass through the Khaz Modan peaks between Dun Morogh and Loch Modan. A fortified dwarven outpost watches the northern corridor, where travelers bound for the Wetlands pass. North Gate Pass is the most direct road through Khaz Modan for those heading north. From the west, you leave steep mountain tunnels for the broad loch valley. Roads lead down toward the Wetlands, carrying dwarven messengers, merchants, and wandering adventurers. North Gate Outpost gives the route its strategic value. Mountaineers there watch for troggs and mountain predators.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-gate-pass-35db95cefb27d79b6966/1-0000.mp3", duration = 34.7428571, start = 0},
  },
}
P.transport["subzone:northshire-valley"] = {
  hash = "9c92fc",
  fullHash = "1f0519",
  text = "Northshire Valley. Northshire Valley, in the hills of northern Elwynn, is where Stormwind's newest defenders begin. Mountain ridges guard it on every side but one. At its heart stands the ancient abbey, with fertile vineyards and a rich mine close by. But bandits and kobolds trouble the valley now, and wolves prowl its quiet pastures. The only way out is the road south. It runs through a fortified gatehouse, on toward Goldshire and the rest of the forest. A clear river crosses the pastures and flows into Crystal Lake. In the abbey, recruits train under seasoned veterans and the Knights of the Silver Hand. With its vineyards and its mine, the valley has all it needs, far from the wars beyond its ridges. But even here, Stormwind's defenses are stretched thin. In the valley, Marshal McBride and his detachment of the Guard struggle to keep order. So the commanders here take on every able-bodied soul who reaches the gates. They need every one of them.\n\nWolves have come north out of darkened Duskwood. Kobolds have overrun the tunnels of Echo Ridge Mine. And masked thugs of the Defias Brotherhood harass the vineyards. They threaten even the abbey grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_northshire-valley-35f2aae5599751be4aaf/1-0000.mp3", duration = 71.5232653, start = 0},
  },
}
P.transport["subzone:northshire-vineyards"] = {
  hash = "d33602",
  fullHash = "d33602",
  text = "Northshire Vineyards. East of Northshire Abbey, Northshire Vineyards are in Defias hands. Their grapes once supplied wine to the clerics, but thieves now plunder the harvest and threaten local farmers. Across the stream from Northshire Abbey, local workers once tended the grape fields. Milly Osworth was among them. Now Garrick Padfoot leads the Defias Brotherhood brigands who hold the acreage.\n\nThe vineyards give newly arrived Brotherhood recruits an easy foothold close to the abbey. The Defias presence has reached its fields.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_northshire-vineyards-c3da757991fad3782dbc/1-0000.mp3", duration = 32.9142857, start = 0},
  },
}
P.transport["subzone:old-ironforge"] = {
  hash = "bd7633",
  fullHash = "1b9879",
  text = "Old Ironforge. Beneath the High Seat, Old Ironforge remains sealed behind guarded gates. Known as the Assembly of Thanes, this ancient chamber lies deep below the royal throne room. Old Ironforge lies beneath King Magni Bronzebeard's throne in the High Seat. Its cavernous halls sit deep in the mountain, where winding stone bridges cross pools of lava. Long before the Great Forge and the Commons filled with dwarven commerce, early thanes gathered here to govern the mountain kingdom. The entrance from the throne room remains barred. Ironforge's royal guard watches the thresholds leading down into the old vaults.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_old-ironforge-9e946396ec692cd00be1/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["subzone:old-town"] = {
  hash = "3557ac",
  fullHash = "6bd939",
  text = "Old Town. Soldiers train in Old Town beside crowded tenements and narrow alleys. The quarter largely survived the First War and still holds Stormwind’s military Command Center and SI:7’s covert headquarters. Old Town keeps much of Stormwind’s shape from before the First War. While the Stonemasons rebuilt the rest of the city from the ground up, this quarter escaped total ruin. It never gained the polished marble facades or grand canals of the Trade District and Cathedral Square.\n\nWorking folk, laborers, and the city’s poorest residents live among its crowded tenements. Old Town’s cobbled streets are narrower, dirtier, and more chaotic than those elsewhere in the capital. They preserve the feel of the old kingdom. Stormwind’s military officers, barracks, and combat trainers gather in Old Town’s Command Center. Nearby, the Champions’ Hall brings together the Alliance’s finest warriors. At the district’s edge, Master Mathias Shaw leads SI:7 from its covert compound.\n\nOff-duty footmen and shadowy operatives meet at the Pig and Whistle Tavern. It is one of the city’s liveliest watering holes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_old-town-5627cd34e02f88899962/1-0000.mp3", duration = 69.1983673, start = 0},
  },
}
P.transport["subzone:oracle-glade"] = {
  hash = "7a2521",
  fullHash = "36d0d6",
  text = "Oracle Glade. In Oracle Glade, Bloodfeather harpies trouble a sacred woodland between Darnassus and Wellspring Lake. The ancient Oracle Tree and Teldrassil’s first and most potent moonwell watch over the island boughs. Between Darnassus and Wellspring Lake, Oracle Glade offers a place of communion with nature. At its heart, the ancient Oracle Tree has been magically nurtured. Its great boughs form the shape of an eagle perched atop a bear. Nearby shines Teldrassil’s first and most potent sacred moonwell, bright with Elune’s grace.\n\nThe Circle of the Ancients and the Oracle Tree watch over the island boughs. The tree sheds bark marked with messages for Archdruid Fandral Staghelm about the World Tree’s health. Bloodfeather harpies have made roosts in the glade’s high branches. These aggressive avian scavengers threaten the sacred tree and harass traveling druids, disturbing the moonwell’s quiet. Sentinels from Darnassus struggle to drive them out.\n\nAs you pass through the northern part of the glade, tread carefully. Harpies strike swiftly near their roosts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_oracle-glade-533ea8c1a62f43fdbc32/1-0000.mp3", duration = 68.4408163, start = 0},
  },
}
P.transport["subzone:park"] = {
  hash = "718cba",
  fullHash = "fc452b",
  text = "Park. Night elf visitors find a quiet haven in Stormwind's Park, on the city's western edge. Between Cathedral Square and the Mage Quarter, its greenery offers rest, and its druid trainers are the only ones in the Eastern Kingdoms. Stormwind's Park brings a quiet stretch of wilderness into the stone capital. Once a place where the city's people sought recreation, it became an enclave for night elf emissaries and travelers from across the Great Sea. Shaded canopies shelter the district, and a Moonwell stands at its heart. Here, the sacred glades of Kalimdor find an echo in the human kingdom. Night elves have a foothold in foreign lands within Park. Kaldorei priests such as Nara Meideros tend visiting pilgrims, while druidic mentors guide those devoted to the wild. Weary travelers can rest here, away from the clatter of the Trade District and the solemn duties of the Cathedral.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_park-75cdea20ee490dd2a612/1-0000.mp3", duration = 52.9502041, start = 0},
  },
}
P.transport["subzone:petitioner-s-chamber"] = {
  hash = "3e6666",
  fullHash = "3e6666",
  text = "Petitioner's Chamber. Petitioners wait for the crown in a chamber just inside Stormwind Keep. Nobles, church dignitaries, and visiting subjects mingle, drink, or await an audience. Just inside Stormwind Keep, the Petitioner's Chamber lies to your right. Count Remington Ridgewell and Bishop DeLavey wait there for audiences with boy-king Anduin Wrynn and Highlord Bolvar Fordragon. Between formal visits, nobles and clergy mingle, trade gossip, and quietly press their concerns. Who speaks with whom can show where influence lies in the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_petitioner-s-chamber-c15660d82d1c0070fcde/1-0000.mp3", duration = 33.8285714, start = 0},
  },
}
P.transport["subzone:pig-and-whistle-tavern"] = {
  hash = "b0931d",
  fullHash = "b0931d",
  text = "Pig and Whistle Tavern. In Stormwind City's Old Town, the Pig and Whistle Tavern draws travelers and local laborers. Veterans gather there to recall the kingdom's past conflicts. In Old Town's winding alleys, the Pig and Whistle Tavern gives citizens, workers, and road-weary travelers a place to find warmth, ale, and lodging. Recipe vendor Kendor Kabonka shares the room with grizzled veterans. Over their tankards, they remember the First and Second Wars.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_pig-and-whistle-tavern-42738b8e406e079feb9f/1-0000.mp3", duration = 27.115102, start = 0},
  },
}
P.transport["subzone:pool-of-ask-ar"] = {
  hash = "f02918",
  fullHash = "76ea67",
  text = "Pool of Ask'ar. Naga invaders and aquatic beasts crowd Pool of Ask'ar, deep within Blackfathom Deeps. Beneath its waters lie night elven stonework and passages into the corrupted sanctuary. Past the Drowned Sacellum, cold water fills Pool of Ask'ar beneath a vast cavern roof. Oversized snapping turtles and deep-sea crabs nest among natural caverns and ancient stonework. Ghamoo-ra, an enormous ancient chelonian, watches over them.\n\nNaga have seized the temple and guard this flooded threshold. Their patrols watch the approaches leading deeper into the complex, toward Lady Sarevess and the Moonshrine Ruins. Dangerous creatures and naga patrols guard relics from the shrine's past, before the Sundering. Submerged ledges and hidden alcoves along the cavern's edges hold lost artifacts, including the Lorgalis Manuscript sought by Gerrig Bonegrip, a dwarven scholar from Ironforge.\n\nSwim through the flooded southern passages to reach dry tunnels guarded by vile murlocs and Old God cultists. The pool remains a vital waterway through Blackfathom Deeps.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_pool-of-ask-ar-be9812911b49cf89b157/1-0000.mp3", duration = 67.2391837, start = 0},
  },
}
P.transport["subzone:pools-of-arlithrien"] = {
  hash = "8b9ec4",
  fullHash = "8b9ec4",
  text = "Pools of Arlithrien. South of Darnassus, danger and neglect have overtaken the Pools of Arlithrien. Their moonwell no longer draws night elves to a quiet sanctuary, as beasts and nearby Gnarlpine furbolgs threaten the springs. Beneath Teldrassil’s shaded boughs, the Pools of Arlithrien lie south of Darnassus. A stone moonwell rests at their heart, its waters touched by Elune’s grace. Danger has driven the night elves to leave the sanctuary untended, though it lies near their capital. Agitated beasts roam the shallows, and hostile Gnarlpine furbolgs remain nearby. A quiet retreat has become a place troubled by dangers across the island.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_pools-of-arlithrien-0f8106c09817d8286f28/1-0000.mp3", duration = 39.4187755, start = 0},
  },
}
P.transport["subzone:raven-hill"] = {
  hash = "74bb7f",
  fullHash = "b2886f",
  text = "Raven Hill. The ruins of Raven Hill lie beneath the shadow of its vast cemetery in western Duskwood. Frightened squatters and invisible spirits are all that remain of the once lively human settlement. Raven Hill lies along Duskwood’s western road, just north of Addle’s Stead. Dark magic and undead horrors swept through the Grand Hamlet region, driving the living east toward Darkshire or out of the territory. Now ruined timber homes decay beneath the gloom. Travelers keep away, fearing the restless dead from the neighboring cemetery and the invisible Unseen among the crumbling walls. Only a handful remain among Raven Hill’s ruins. Jitters, a nervous adventurer, hides in the abandoned structures, afraid of the horrors stalking the woods. In a dilapidated attic, the goblin Bliztik ekes out a solitary living by selling supplies to wary passersby. They share the ruins with the invisible spirits called the Unseen, beside the sprawling burial grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_raven-hill-6e4f3ffec6cc78c24b22/1-0000.mp3", duration = 56.2416327, start = 0},
  },
}
P.transport["subzone:raven-hill-cemetery"] = {
  hash = "d1ee23",
  fullHash = "d1ee23",
  text = "Raven Hill Cemetery. In western Duskwood, the dead rise from their graves at Raven Hill Cemetery. The burial ground once served nearby hamlets, but undead, spiders, and grave robbers now roam among the tombs. Settlements around the Dawning Wood once buried their dead at Raven Hill Cemetery. Then dark sorceries fell upon the region, and the dead began clawing out of their plots. Skeletons, ghouls, and shambling horrors crowd the graveyard now. Rotting abominations and giant spiders prowl among the tombs, while desperate grave robbers plunder ancestral crypts beyond the reach of local authorities. Raven Hill remains one of Duskwood's most dangerous places.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_raven-hill-cemetery-49066869fbdca9f382b4/1-0000.mp3", duration = 38.635102, start = 0},
  },
}
P.transport["subzone:ravenholdt-manor"] = {
  hash = "f5c7d7",
  fullHash = "75f4a5",
  text = "Ravenholdt Manor. High in the Hillsbrad mountains, Ravenholdt Manor shelters a guild of thieves and assassins. Lord Jorach Ravenholdt leads them as they hone stealth beyond the authorities’ reach. Northwest of Durnholde Keep, a narrow pass winds through a cave to Ravenholdt Manor. The estate stands alone on the border of the Alterac Mountains, under Lord Jorach Ravenholdt’s care. He keeps a disciplined company of rogues, assassins, and intelligence operatives.\n\nA quiet garden and an outdoor arena give them room to practice lockpicking, poison-crafting, and close combat under martial experts such as Master Kang. Those skilled in skullduggery are welcome, but watchful sentries greet clumsy strangers and unwanted visitors with cold suspicion. Before the First War, the lands around Ravenholdt Manor belonged to the kingdom of Alterac. The manor’s weathered orange roof tiles still recall that time. After Alterac fell, displaced nobles formed the Syndicate and sought control of the region. Their ambition brought them into conflict with Ravenholdt. Jorach’s followers now fight across Hillsbrad and Alterac to preserve their sovereign haven.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ravenholdt-manor-b1ad5e5a5871524e5e52/1-0000.mp3", duration = 70.2432653, start = 0},
  },
}
P.transport["subzone:raynewood-retreat"] = {
  hash = "b912e1",
  fullHash = "b912e1",
  text = "Raynewood Retreat. At Raynewood Retreat, Cenarion guards watch Ashenvale’s northern approaches to Felwood. Keeper Ordanus makes his home in the great tree at the heart of the outpost. Raynewood Retreat stands between Shael'dryn's moonwell and the satyr-infested ruins of Night Run. Cenarion Protectors, faerie dragons, and Laughing Sisters guard the outpost. Their watch turns north, toward the taint spreading from Felwood.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_raynewood-retreat-53f96e529f87eb064213/1-0000.mp3", duration = 24.842449, start = 0},
  },
}
P.transport["subzone:razorfen-downs"] = {
  hash = "bcb9ba",
  fullHash = "bcb9ba",
  text = "Razorfen Downs. Scourge power now stains Razorfen Downs, the quilboar’s sacred burial maze in southern Kalimdor. Their dead still rest among Agamaggan’s thorns, though necromancy has taken hold. Razorfen Downs holds the quilboar’s ancestral dead among the petrified briars of Agamaggan. The thorn maze rises from the fallen demigod, and legend says its arched entrance was carved from the Great Boar’s own maw. For centuries, high priests of the Death's Head tribe tended its deep, winding burrows and honored the dead. Now a catastrophe darker than any quarrel over water in the Barrens has struck this sacred ground.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razorfen-downs-1099032e469727c039c1/1-0000.mp3", duration = 37.2767347, start = 0},
  },
}
P.transport["subzone:remtravel-s-excavation"] = {
  hash = "6e4c18",
  fullHash = "6e4c18",
  text = "Remtravel's Excavation. Prospector Remtravel's dig in southern Darkshore has broken into ancient ruins. Prospector Remtravel came to southern Darkshore in search of relics from the distant past. He set up a large dig, far from Auberdine's safety. As his team cut through old layers of earth, they uncovered Gravelflint troggs and hulking stone golems. The creatures overran the quarry and scattered the miners. Now Remtravel scrambles to recover his most promising finds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_remtravel-s-excavation-982b07490283936bb36b/1-0000.mp3", duration = 27.2195918, start = 0},
  },
}
P.transport["subzone:render-s-rock"] = {
  hash = "10633c",
  fullHash = "10633c",
  text = "Render's Rock. Blackrock orcs hold Render's Rock above Redridge, near the pass into the Burning Steppes. They use the cave to prepare attacks on the valleys below. North of Lakeshire, Blackrock orcs guard a cave in the Redridge heights. Render's Rock lies near the mountain pass into the Burning Steppes, where veteran orcs direct attacks against Redridge's defenders. Their guards make it perilous to enter, whether you mean to disrupt the orcs' supplies or recover captives lost in the fighting.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_render-s-rock-25185937835bbf4e0b2e/1-0000.mp3", duration = 28.2644898, start = 0},
  },
}
P.transport["subzone:render-s-valley"] = {
  hash = "78d16e",
  fullHash = "5dcf77",
  text = "Render's Valley. Blackrock orcs hold a camp in southeastern Redridge at Render's Valley. Their raids threaten travelers, and captives from nearby lands remain under guard. Among rocky ridges southeast of Lake Everstill, Blackrock orcs keep an auxiliary camp for their work in Redridge. War tents, banners, and sentry posts mark the valley, unlike the keeps and stone towers on the northern cliffs.\n\nFewer warriors serve here, and they carry less armor than the clan's main forces. Still, they raid local roads and harass travelers. Captured prisoners wait in crude cages under guard. Scouts who reach Render's Valley find more than war parties on its dirt paths. Human prisoners are held in the camp, including a servant from the Tower of Azora in Elwynn Forest. He traded specialist goods beneath his captors' noses.\n\nUnmarked paths cross the high southern bluffs behind the valley. Daring travelers can follow them into the murky bogs of the Swamp of Sorrows.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_render-s-valley-a6def9caec0a0808dbb0/1-0000.mp3", duration = 58.8016327, start = 0},
  },
}
P.transport["subzone:rethban-caverns"] = {
  hash = "fd1811",
  fullHash = "bdf7b1",
  text = "Rethban Caverns. In northwestern Redridge, gnolls hold the winding Rethban Caverns. The caves are the only source of uncommon Rethban ore. Above Lake Everstill, the caverns shelter the local gnolls in a fortified redoubt. Their leader, Ardo Dirtpaw, commands a pack that guards the twisting passages and chambers below. Wander too near the hillside entrance, and they attack. Blacksmiths and researchers in Lakeshire seek Rethban ore from these winding, dangerous tunnels. The Dirtpaw pack carries the distinct mineral, so travelers sent for samples must face the gnolls to find this rare mountain ore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rethban-caverns-cf65365d90fd22f181a4/1-0000.mp3", duration = 36.7542857, start = 0},
  },
}
P.transport["subzone:ridgepoint-tower"] = {
  hash = "1922ec",
  fullHash = "e1f046",
  text = "Ridgepoint Tower. Stormwind guards watch eastern Elwynn from Ridgepoint Tower, where forest roads lead into neighboring wilderness. The garrison scans the valleys for threats to the kingdom’s farms and settlements. Ridgepoint Tower looks out from high ground at the eastern edge of Stormwind’s authority, with wild country beyond. Its guards watch the routes toward farms and settlements nearer Northshire and Goldshire. They remain alert for danger crossing the border. Threats press in from several directions. East lie the Redridge Mountains, where aggressive gnoll packs and blackrock orc raiders test human defenses. Across the southern river, undead horrors prowl Duskwood’s timberline. Nearby wilderness camps shelter rogue Defias Brotherhood bandits seeking gaps in the guard’s defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ridgepoint-tower-d2fda041be515e1e23cf/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["subzone:roland-s-doom"] = {
  hash = "b9e70d",
  fullHash = "b9e70d",
  text = "Roland's Doom. Nightbane worgen prowl the abandoned mine at Roland's Doom, east of the Rotting Orchard in southeastern Duskwood. East of the Rotting Orchard, Roland's Doom lies among the ridges of southeastern Duskwood. The mine has stood idle for a long while. Now Nightbane worgen use its tunnels as a staging ground, led by such chieftains as Gutspill and Nefaru. Their snarls carry through the dark shafts. Blood stains the damp earth, and those who enter face one of Duskwood's most perilous places.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_roland-s-doom-6e61be28c8fed0520200/1-0000.mp3", duration = 30.7983673, start = 0},
  },
}
P.transport["subzone:rotting-orchard"] = {
  hash = "fc9bf1",
  fullHash = "fc9bf1",
  text = "Rotting Orchard. In southern Duskwood, the Rotting Orchard has fallen to the Nightbane worgen. Its fruit once fed nearby Darkshire, but now the trees and buildings lie in ruin. Nightbane worgen have made camps among the Rotting Orchard’s ruined barns and outbuildings. The grove lies east of the ruined Yorgen Farmstead and west of Tranquil Gardens Cemetery. Withered fruit hangs from the trees as Nightbane Stalkers prowl the twisted brush. Nightbane Shadow Weavers practice dark magic among the decaying timber. The fierce worgen Gutspill and Nefaru lead the pack from their lair in the nearby mine of Roland's Doom.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rotting-orchard-d1157656ea6d0c3c535e/1-0000.mp3", duration = 35.3436735, start = 0},
  },
}
P.transport["subzone:royal-gallery"] = {
  hash = "588413",
  fullHash = "588413",
  text = "Royal Gallery. In Stormwind Keep, the Royal Gallery honors the kingdom’s history and the Grand Alliance. Beyond the courtyard garden, a quiet hall holds statues and works of art. Beyond the interior garden and beside the Royal Library, the Royal Gallery holds statues of King Llane Wrynn, Stormwind’s fallen ruler, and Grand Admiral Daelin Proudmoore of Kul Tiras. Lady Mara Fordragon is honored here too, for her patronage of the refugees who fled to Lordaeron after the First War. Courtly visitors such as Lady Dena Kennedy come to see these figures and the works of art around them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_royal-gallery-d54d24d8b366ddf25ae0/1-0000.mp3", duration = 35.6310204, start = 0},
  },
}
P.transport["subzone:royal-library"] = {
  hash = "1bbcaf",
  fullHash = "1bbcaf",
  text = "Royal Library. Within Stormwind Keep, scholars turn to the Royal Library for the kingdom’s records and histories. Head Librarian Milton Sheaf watches over its scrolls and treatises, from ancient wars to accounts of realms beyond the sea. Within Stormwind Keep’s guarded halls, the Royal Library offers a quiet place amid courtly intrigue. Milton Sheaf oversees its shelves of southern human history. They hold surviving texts written before the First War, recent military chronicles, and recovered tomes. Alliance scholars, priests, and travelers may browse its treatises on the founding of the Alliance of Lordaeron and the recent arrival of Thrall’s Horde in Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_royal-library-8791db9018b40448eb65/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["subzone:ruins-of-mathystra"] = {
  hash = "676f6d",
  fullHash = "e0ab9a",
  text = "Ruins of Mathystra. Stormscale naga hold Mathystra's broken halls on Darkshore's northern coast. Ghost Sabers haunt the ruins of this ancient night elven city, shattered in the Great Sundering ten thousand years ago. Mathystra once sheltered Highborne nobles on Darkshore's northern coast. When the Well of Eternity collapsed in the Great Sundering, great waves broke the city. They toppled its marble arches and swept much of its stonework into the sea. The surviving night elves left for smaller woodland villages farther south. Sunken courtyards and cracked foundations still face the battered coast. Stormscale naga guard Mathystra's broken halls and drive away travelers who venture north past the Tower of Althalaxx. Ancient Highborne relics lie half-buried among flagstones, sand, and seafoam. Young night elves sometimes brave the naga to recover remnants of their heritage. Meanwhile, spectral Ghost Sabers stalk the broken streets.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ruins-of-mathystra-1c4435e6e672f75a79e7/1-0000.mp3", duration = 55.5102041, start = 0},
  },
}
P.transport["subzone:ruins-of-ordil-aran"] = {
  hash = "33e7de",
  fullHash = "33e7de",
  text = "Ruins of Ordil'Aran. Between Maestra's Post and Bathran's Haunt, the Ruins of Ordil'Aran have fallen to Thistlefur furbolgs. The ancient night elf settlement once sheltered shadow cultists. Weathered pillars and cracked arches mark the old Kaldorei buildings. The Cult of the Dark Strand once hid among these stones and ambushed travelers on Ashenvale's northwestern paths. Recently, Thistlefur furbolgs drove the cultists out in a bloody takeover. Their fallen practitioners still lie across the ground. Now the furbolgs patrol the perimeter and guard the ancient Heartswood tree within the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ruins-of-ordil-aran-b15f4563a809bf0d18ab/1-0000.mp3", duration = 33.7502041, start = 0},
  },
}
P.transport["subzone:ruins-of-stardust"] = {
  hash = "c2d7dd",
  fullHash = "2005c8",
  text = "Ruins of Stardust. South of Astranaar, corruption from Felwood reaches the island sanctuary at the Ruins of Stardust. Bog beasts prowl its fallen stones, while healing shrubs still grow among them. South of Astranaar, you find the Ruins of Stardust on a lone island. The night elves once revered this holy place. Now demonic rot spreads south from Felwood, turning the water sickly yellow-green, as it does at nearby Iris Lake. The corruption has twisted local plant life into hostile bog beasts. They prowl the fallen stones, warped by the tainted water. Stardust shrubs still bloom among the ruins, untouched by corruption in the soil and along the shore. Their leaves and blossoms can cleanse and heal. Shamans, herbalists, and local night elf defenders seek them for remedies against Ashenvale's encroaching decay.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ruins-of-stardust-938877e7576a216d767a/1-0000.mp3", duration = 49.5542857, start = 0},
  },
}
P.transport["subzone:rut-theran-village"] = {
  hash = "6f401d",
  fullHash = "6f401d",
  text = "Rut'theran Village. At Teldrassil’s southern shore, Rut'theran Village joins Darnassus to Kalimdor by sea and sky. Ferries and hippogryphs carry travelers between the World Tree and the mainland. Rut'theran Village meets the water below Teldrassil’s towering heights. Darnassus rests in the boughs above, and the village tends to its needs beyond the tree. A mystical portal beneath the trees carries travelers between the shore and Darnassus in an instant. Ferries leave the docks for Auberdine on Darkshore’s mainland coast, and flight masters tend roosts of trained hippogryphs.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rut-theran-village-a5f481abb3dfc58cf4f7/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["subzone:saldean-s-farm"] = {
  hash = "7976ca",
  fullHash = "63d969",
  text = "Saldean's Farm. In Westfall, Saldean's Farm remains the one homestead not wholly overrun and abandoned to the Defias Brotherhood. Farmer Saldean and his wife Salma keep the farmhouse as a rare safe haven amid the region's troubles. The Saldean family held to their land as neighboring farms fell to banditry and mechanical sabotage. Farmer Saldean and his wife Salma still offer travelers hot food and a kind word. Harvest golems deployed across the plains now plague their fields, so the family stays close to the farmhouse walls. Stormwind's crown has largely neglected Westfall, and few guards are left to keep order. A handful of Sentinel Hill and Stormwind guards patrol the edges, but the Saldeans rely chiefly on their own grit and help from passing travelers. Salma's famous Westfall stew and goretusk liver pie bring small comforts, as does the farmhouse shelter, against the Defias threat.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_saldean-s-farm-143a58219a1c462cf778/1-0000.mp3", duration = 53.6555102, start = 0},
  },
}
P.transport["subzone:satyrnaar"] = {
  hash = "39ef1c",
  fullHash = "39ef1c",
  text = "Satyrnaar. In Satyrnaar, Bleakheart satyrs hold an ancient night elf settlement in northeastern Ashenvale. The ruins sit beside the road from Splintertree Post toward Azshara, and their stonework is more intact than that of other satyr camps deep in the forest. You find Satyrnaar northeast of Splintertree Post and southwest of Forest Song. Along with Xavian and Night Run, it is one of Ashenvale’s three chief satyr settlements. Its elven buildings are more intact than those deep in the wilderness, though tents now stand among the broken stone. The Bleakheart satyrs make the trade road east toward Azshara dangerous. They are allied with the Cult of the Dark Strand, whose soulgem lies among the corrupted stones.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_satyrnaar-abb39b2b5d0e5cf34a7d/1-0000.mp3", duration = 41.7959184, start = 0},
  },
}
P.transport["subzone:scarlet-raven-tavern"] = {
  hash = "87ea2d",
  fullHash = "87ea2d",
  text = "Scarlet Raven Tavern. In Darkshire, Scarlet Raven Tavern is the town’s primary inn and gathering place. Tavernkeep Smitts welcomes weary locals, passing adventurers and frightened travelers seeking shelter from the horrors beyond town. The Scarlet Raven Tavern offers a dim refuge in Darkshire, where the hearth burns beneath the forest’s eternal dusk. Years ago, Marshal Haggard and the Stormwind Guard stopped here for pints after patrols. Since then, business has dwindled as the town’s security has weakened.\n\nTavernkeep Smitts tends the bar for a somber, anxious crowd seeking warmth against the cold and fear. The inn remains a place to trade rumors and a starting point for travelers seeking answers about the dark forces consuming the region.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_scarlet-raven-tavern-3049289d80d07ad9a9a5/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["subzone:sentinel-hill"] = {
  hash = "9a851f",
  fullHash = "94e3e1",
  text = "Sentinel Hill. At Sentinel Hill, the Alliance holds its main stronghold in Westfall, and the People's Militia keeps its command post there. Overgrown fields, scavenging gnolls, and hostile outlaws surround the rise, leaving it as the lawful citizens' only secure foothold in the region. Sentinel Hill rises above central Westfall. Around Sentinel Tower stand a barracks-style inn, a gryphon roost with flights to Stormwind and beyond, a forge, and a lumber mill. Overgrown fields, scavenging gnolls, and outlaws crowd the surrounding land. Within the fragile perimeter, travelers, beleaguered farmers, and recruits can regroup under the eyes of veteran defenders. The royal army is detained in Stormwind and cannot spare soldiers for the outlying territories. So Gryan Stoutmantle established the People's Militia on Sentinel Hill. Volunteer fighters organize scouts, strike at the Riverpaw gnolls, and investigate the organized banditry tearing through Westfall's abandoned farmsteads. This is no opulent fort or comfortable refuge. It is a working frontline camp, determined to reclaim the kingdom's former breadbasket.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sentinel-hill-610fa2fc528f87fe0a1f/1-0000.mp3", duration = 67.2391837, start = 0},
  },
}
P.transport["subzone:sentinel-tower"] = {
  hash = "6d8a5a",
  fullHash = "45a3d7",
  text = "Sentinel Tower. At Sentinel Tower, defenders watch Westfall and organize resistance against bandits, gnolls, and the Defias Brotherhood. Gryan Stoutmantle and the People's Militia hold the line. Sentinel Tower watches over Westfall's unsettled plains. With Stormwind's army largely absent and aid withheld, local volunteers and veterans have gathered around this stronghold. From its stone heights, lookouts see across dusty plains, past abandoned pumpkin patches to the misty shores. They watch for highwaymen and gnoll raiding parties moving through the region. Gryan Stoutmantle and local leaders direct the militia from Sentinel Tower. Makeshift defenses ring the stronghold, where wounded refugees and weary soldiers gather. Homesteaders driven from their lands find emergency shelter there. Militia members piece together reports about the Defias Brotherhood and organize volunteers for strikes against the syndicate that has brought Westfall to ruin.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sentinel-tower-73aff4f097da0e863c09/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["subzone:shadowthread-cave"] = {
  hash = "a05686",
  fullHash = "64f37b",
  text = "Shadowthread Cave. In Shadowthread Cave, spiders now threaten the young kaldorei near Aldrassil. The cave lies beneath Shadowglen’s northwest cliffs. In Shadowglen’s shaded northwest, Shadowthread Cave shelters Teldrassil’s giant spiders. Once they lived quietly among the World Tree’s young boughs. Now the brood guards its territory fiercely. Webwood silk chokes the stone corridors, and the spiders threaten young kaldorei who venture beyond Aldrassil. Githyiss the Vile rules Shadowthread Cave’s deepest recesses. The monstrous broodmother is far more ferocious than the common webwood crawlers. Young night elf sentinels and druids enter the cave to curb the infestation and slay her. Corruption touches Teldrassil’s wildlife, and the sanctuary of Shadowglen is at risk.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shadowthread-cave-a2b04e608f8aed9c4e1b/1-0000.mp3", duration = 49.6587755, start = 0},
  },
}
P.transport["subzone:shimmer-ridge"] = {
  hash = "a2e61a",
  fullHash = "a6c34c",
  text = "Shimmer Ridge. In northern Dun Morogh, Shimmer Ridge lies west of the Gates of Ironforge, where Frostmane trolls hold two camps across a chasm. Shimmerweed grows nowhere else. Frostmane trolls hold camps on both sides of a chasm, joined by a rickety wooden bridge. Troll scavengers and tamed mountain boars guard the rocky heights. The ridge lies near the main road and the dwarven capital, giving the trolls a place to raid travelers and mountain patrols. Frostmane trolls grow shimmerweed on the ridge. Dwarven brewmasters prize the plant for the potent, flavorful highland ales it makes. Since it is hard to gather elsewhere, mountaineers and young recruits brave troll ambushes and tusked beasts to harvest it from the trolls' plots.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shimmer-ridge-a3bad644f09e0ebfb2c8/1-0000.mp3", duration = 44.9306122, start = 0},
  },
}
P.transport["subzone:shimmering-flats"] = {
  hash = "b55612",
  fullHash = "4f27fd",
  text = "Shimmering Flats. At Thousand Needles' southeastern edge, the Shimmering Flats stretch between the salt pan and Tanaris. The old lakebed now draws racers to the Mirage Raceway, where gnome and goblin tinkerers test their machines among desert beasts. Beneath the southern sun, the Shimmering Flats lie bare, with bleached turtle bones and the wooden wreck of an ancient sailing vessel. Their level salt crust makes them Kalimdor's chief ground for testing experimental vehicles. At the heart of the flats, the Mirage Raceway gathers gnome and goblin tinkerers for fierce contests. Rocket cars, gyrocopters and engines roar across the salt. Their makers chase speed, and fiery crashes leave smoking craters behind. Beyond the raceway, hardened basilisks, aggressive scorpids and circling vultures hunt across the open flats. Farther south, the ground turns treacherous around the Rustmaul Dig Site. Dwarven prospectors first excavated the quarry, then the Horde contested it. The site was abandoned when picks broke into underground tunnels and unleashed vicious silithid across the southern edge of the flats.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shimmering-flats-5f55203d9bb0dd8480c0/1-0000.mp3", duration = 63.7126531, start = 0},
  },
}
P.transport["subzone:shrine-of-aessina"] = {
  hash = "44932d",
  fullHash = "44932d",
  text = "Shrine of Aessina. At the Shrine of Aessina, night elves honor an ancient spirit of nature and wild creatures. The shrine lies in southwestern Ashenvale, between Maestra's Post and Astranaar, where border friction is growing. West of Astranaar, night elves honor Aessina, a Wild God who bears the heart and spirit of the deep forests. For generations, they and their woodland kin have come here to commune with nature, far from the main roads. The Horde presses into Ashenvale for timber and footholds, and peace grows uncertain at sacred grounds across the territory.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shrine-of-aessina-9513530ae54c624cfd16/1-0000.mp3", duration = 33.6718367, start = 0},
  },
}
P.transport["subzone:si-7-stormwind-city"] = {
  hash = "0df6d1",
  fullHash = "0df6d1",
  text = "SI:7 (Stormwind City). In Old Town, SI:7 watches for threats to Stormwind from a fortified stone manor. Master Mathias Shaw directs the kingdom’s intelligence service from behind its heavy doors. In Old Town, SI:7 works from a fortified stone manor. From the street, it could pass for an ordinary home or military barracks. Master Mathias Shaw directs Stormwind Intelligence, Section 7. Its agents gather intelligence, watch suspected threats and carry out secret operations to guard the kingdom from subversion.\n\nThe city guard patrols Stormwind’s streets, while the Royal Guard protects Stormwind Keep. SI:7 trains handlers and sends covert agents against foreign enemies, saboteurs and unrest within the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_si-7-stormwind-city-26faeb4c3d51a03caaa1/1-0000.mp3", duration = 44.8783673, start = 0},
  },
}
P.transport["subzone:silver-stream-mine"] = {
  hash = "fb62a2",
  fullHash = "4b5e7f",
  text = "Silver Stream Mine. In northern Loch Modan, Silver Stream Mine lies between Algaz Station and the Stonewrought Dam. Its silver veins are spent, and Tunnel Rat kobolds now hoard stolen equipment and rare minerals in the Miners' League depot. Silver Stream Mine once sent rich silver to Ironforge. Dwarf miners worked its veins until they ran dry, leaving broad chambers beneath the earth. The Miners' League put those hard-won shafts to use as a guarded storehouse for tools, mining crates, and regional equipment. The mine also yields Charged Rift Gems, which draw arcanists seeking delicate tailoring reagents. Tunnel Rat kobolds came in great numbers and drove the Miners' League caretakers out into the cold of Loch Modan. Now they guard the stolen dwarf crates with manic fervor. Beyond the rear entrances, shattered orcish catapults and wagons lie forgotten, remnants of older frontier skirmishes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_silver-stream-mine-ae6bcf288567bf02285f/1-0000.mp3", duration = 54.2563265, start = 0},
  },
}
P.transport["subzone:silverwind-refuge"] = {
  hash = "78c6cc",
  fullHash = "78c6cc",
  text = "Silverwind Refuge. Sentinels guard Silverwind Refuge in south-central Ashenvale, just north of Mystral Lake. Travelers find shelter along the forest trails. Silverwind Refuge lies between Mystral Lake and Iris Lake, with Iris Lake to the north. Alongside Astranaar, it is one of central Ashenvale’s chief night elven waystations. Craftsmen and wilderness trainers teach herbalism, alchemy, skinning, and hunting. Sentinels guard the refuge, where allies crossing the ancient woods can rest.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_silverwind-refuge-1c8583ff453cf7b8100b/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["subzone:silverwing-grove"] = {
  hash = "513c0b",
  fullHash = "513c0b",
  text = "Silverwing Grove. Silverwing Sentinels muster at Silverwing Grove in south-central Ashenvale, near Fallen Sky Lake. From this fortified hollow, night elf warriors gather Alliance forces against the Warsong Clan loggers cutting through the forest. Beneath the canopy southwest of Silverwing Outpost, Silverwing Sentinels gather at Silverwing Grove. They use the post to oppose the Horde's lumbering in Warsong Gulch. Alliance officers, provisions, and scouts assemble here to organize skirmishes and muster champions. Together, they defend Ashenvale against orcish expansion.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_silverwing-grove-c60948c8f4113668c1b3/1-0000.mp3", duration = 32.8097959, start = 0},
  },
}
P.transport["subzone:silverwing-outpost"] = {
  hash = "271fef",
  fullHash = "271fef",
  text = "Silverwing Outpost. At Silverwing Outpost, Duriel Moonfire commands the Alliance’s easternmost hold against the Horde in contested Ashenvale. The garrison guards the eastern bank of the Falfarren River in the forest’s south-central reaches. Southwest of Splintertree Post and just north of the Barrens border, Silverwing Outpost holds the eastern bank of the Falfarren River. The Horde contests and patrols this ground. From here, the garrison shields night elf holdings deeper in the forest. Duriel Moonfire and her Silverwing Sentinels face constant attacks from nearby orcs seeking to drive night elf forces away.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_silverwing-outpost-e50418ca253028bce63b/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["subzone:sishir-canyon"] = {
  hash = "0ad612",
  fullHash = "99a5a5",
  text = "Sishir Canyon. Webs and Deepmoss spiders choke Sishir Canyon, the eastern pass through the Stonetalon Mountains. Travelers face the brood on the dangerous way to the Ruins of Eldre'thar. Sishir Canyon cuts through the Stonetalon Mountains toward the ancient Ruins of Eldre'thar. Deepmoss spiders have overrun the gorge. Sheets of web cover its stone floor and walls, and egg sacs cluster among them. Travelers and sentinels heading for the night elven ruins must fight through swarms of aggressive webspinners. Deep in Sishir Canyon, Besseleth rules as matriarch of the Deepmoss brood. Her great size and venom threaten anyone trying to secure the pass. Local forces in Stonetalon keep watch and warn travelers that scattered spiders are not all that lurks in the webbed depths. Besseleth fiercely guards her brood.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sishir-canyon-9f8f5436c7b987324122/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["subzone:slaughtered-lamb"] = {
  hash = "ba532e",
  fullHash = "ba532e",
  text = "Slaughtered Lamb. In Stormwind's Mage Quarter, the Slaughtered Lamb keeps a quiet, seedy tavern above a hidden warlock sanctuary. Dark corners and few patrons greet you at the Slaughtered Lamb, where barkeep Jarel Moor warns visitors to avoid the shadows. The warning is literal. Back passages descend to crypts and summoning circles below. There, human warlocks and transfer practitioners from Khaz Modan study fel arcana, beyond the disapproving eyes of the Church of the Holy Light and the Kirin Tor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_slaughtered-lamb-61af8b4b22c2f5b51158/1-0000.mp3", duration = 29.4922449, start = 0},
  },
}
P.transport["subzone:south-gate-outpost"] = {
  hash = "bf9847",
  fullHash = "bf9847",
  text = "South Gate Outpost. At South Gate Outpost, mountaineers guard the pass between Dun Morogh and Loch Modan. Their fortified post watches the southern road from Ironforge's frigid heights to the Loch's temperate valley. South Gate Outpost marks the spot where the snowy slopes end and the basin begins. Ironforge mountaineers patrol the rocky switchbacks and keep dangerous wildlife off the main highway. Their kin at North Gate Outpost face a harder fight, but the southern road is largely secure. Travelers, pilgrims, and trade wagons can reach Thelsamar in relative safety.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_south-gate-outpost-b9820c1b11bf81ff3af3/1-0000.mp3", duration = 32.8620408, start = 0},
  },
}
P.transport["subzone:south-gate-pass"] = {
  hash = "b37c0d",
  fullHash = "f9e40b",
  text = "South Gate Pass. Travelers cross South Gate Pass between Dun Morogh and Loch Modan. Its guarded road links Ironforge with Thelsamar. South Gate Pass cuts through the Khaz Modan range, joining Dun Morogh's high mountains to Loch Modan's valley in the east. Stone archways mark the way from cold slopes into warmer dwarven heartlands. The road leads toward Thelsamar, carrying mountaineers, couriers, and newly trained adventurers setting out from the capital. Dwarven mountaineers keep watch at South Gate Outpost, guarding the pass against wild beasts and prowling troggs. The road is safer than the untamed parts of the valley, though hostile wildlife and roving threats still test its approaches. Stay on the road as you travel.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_south-gate-pass-16df51d6032d5780ba80/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["subzone:southshore"] = {
  hash = "a59a4b",
  fullHash = "e3bd9c",
  text = "Southshore. In Hillsbrad, Southshore shelters the Alliance amid the ruins of Lordaeron. Once a quiet fishing village, the coastal port now faces the Forsaken at Tarren Mill, Syndicate bandits, and monsters along the shore. Refugee boats from the fallen kingdom of Stormwind first brought Southshore to prominence during the First War. The town was contested and overrun during the Second War, then rebuilt. It endured the horrors of the Third War as well.\n\nNow much of Lordaeron lies in ruins or under Forsaken rule, but Southshore remains loyal to the Grand Alliance. It shelters displaced human survivors, veteran paladins of the Silver Hand, and scholars of the Kirin Tor. Southshore's docks see the ship between Menethil Harbor and Auberdine, and the town is known for its turtle bisque. Yet life here is perilous. Magistrate Henry Maleb and Marshal Redpath lead the town as it faces pressure from every side.\n\nTo the north, the Forsaken of Tarren Mill fight a bitter border conflict for control of Hillsbrad. Inland, Syndicate outlaws raid supply lines and assassinate local leaders. Ogres, murlocs, and naga also harass the town's borders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_southshore-044c58baffcee32c2792/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["subzone:splintertree-post"] = {
  hash = "ac625c",
  fullHash = "2590eb",
  text = "Splintertree Post. In eastern Ashenvale, Splintertree Post holds the Horde’s frontier northwest of Felfire Hill. Grommash Hellscream and the Warsong clan raised it during the Third War as a fortified base against the night elves and a staging ground for expansion. Splintertree Post anchors the Horde’s military and supply lines across eastern Ashenvale. Grommash Hellscream and the Warsong clan founded it when the orcs first entered the forest during the Third War. Orcish and tauren scouts and warriors still guard the armed outpost. An inn, a flight master, and steady supplies from Orgrimmar support the Horde’s contested hold beneath the trees. Splintertree Post stays ready for attack. The night elves have neither forgotten nor forgiven Grommash’s actions during the war. They also oppose the Horde’s continued logging and its raids on Astranaar. Sentinels hide in the surrounding woods and strike in constant retaliation, testing the post’s watchmen at all hours.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_splintertree-post-ac7a979886508587cb8c/1-0000.mp3", duration = 56.9730612, start = 0},
  },
}
P.transport["subzone:splithoof-crag"] = {
  hash = "3b7798",
  fullHash = "090a85",
  text = "Splithoof Crag. Galak centaur patrol the northern cliffs of Splithoof Crag and guard their canyon stronghold. Their settlement surrounds Splithoof Hold, while they contest the ravine below the Grimtotem heights. On the northern rock face of Thousand Needles, east of Darkcloud Pinnacle, Galak centaur keep their stronghold. Crude tents and dirt paths fill the enclave. Against the cliff stands Splithoof Hold, a cavern beneath the settlement. There, the Galak guard the Cloven Hoof, an ancient centaur relic kept beside a sacred brazier. Galak centaur attack travelers, Horde expeditions, and tauren scouts passing beneath their bluffs. The Grimtotem occupy nearby high pinnacles. Yet the Galak hold the canyon ravine and the caverns beneath its stone.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_splithoof-crag-12bcc6c5a0746f4d462e/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["subzone:splithoof-hold"] = {
  hash = "e99c84",
  fullHash = "9947e2",
  text = "Splithoof Hold. Galak centaur guard Splithoof Hold in the caves of Splithoof Crag. Within, the Ancient Brazier keeps their sacred flame burning without end. Within Splithoof Crag, Galak centaur defend their cavern against rival tribes and travelers crossing Thousand Needles. Its deep shelter protects them from the windswept canyon floor. Chokepoints guard the way in, with a secure refuge inside the rock. Deep within Splithoof Hold, the Ancient Brazier cradles the Sacred Flame. The mystic fire burns without end. The centaur honor it in ritual, while spiritual wanderers from across the canyon come to wonder at its power.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_splithoof-hold-455ad2d0a7824872ff54/1-0000.mp3", duration = 38.3738776, start = 0},
  },
}
P.transport["subzone:starbreeze-village"] = {
  hash = "c00bc8",
  fullHash = "c00bc8",
  text = "Starbreeze Village. Gnarlpine furbolgs have overrun Starbreeze Village, east of Dolanaar in Teldrassil. The once quiet night elf hamlet lies in ruins beneath the corruption spreading through the World Tree. Southeast of Shadowglen, just down the road from Dolanaar, Starbreeze Village lies in shambles. Night elf families once lived peacefully beneath Teldrassil’s boughs. Now aggressive Gnarlpine furbolgs occupy the wooden homes. Corruption afflicting the World Tree’s boughs has driven them wild. They drove out the elven residents and fiercely defend the ruined grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_starbreeze-village-b93c8f8bb51fb7df689a/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["subzone:steelgrill-s-depot"] = {
  hash = "b9a745",
  fullHash = "b9a745",
  text = "Steelgrill's Depot. East of Kharanos, Steelgrill's Depot keeps Alliance vehicles and machinery working. Beldin Steelgrill and his crew repair them, supply tinkerers, and salvage what they can. Just off the snowy road, dwarven miners and eccentric gnome engineers gather among heavy machinery, mechanized walking frames, and raw ore from nearby quarries. Metal clanks, steam vents hiss, and experimental engines churn. Trogg disruptions and shortages of mechanical supplies trouble Dun Morogh. In the bitter cold, travelers come for spare parts or technical guidance.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_steelgrill-s-depot-68fa264568322f5b5217/1-0000.mp3", duration = 35.6571429, start = 0},
  },
}
P.transport["subzone:stendel-s-pond"] = {
  hash = "da892f",
  fullHash = "da892f",
  text = "Stendel's Pond. At Stendel's Pond, anglers still come for fresh fish despite the gnolls along its banks. Southwest of Sentinel Hill, Stendel's Pond still draws anglers. Gnolls roam the muddy banks, where scattered skeletons and two lone graves mark a perilous shore. No one knows whether foul water or the beasts caused the deaths. Yet schools of sagefish still bring anglers to the pond.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stendel-s-pond-9e1f38a95ecac62d1cae/1-0000.mp3", duration = 23.4840816, start = 0},
  },
}
P.transport["subzone:stone-cairn-lake"] = {
  hash = "c731f3",
  fullHash = "bec26f",
  text = "Stone Cairn Lake. At Stone Cairn Lake in northeastern Elwynn, murlocs hold the southern shore. Renegade wizards camp beside Heroes' Vigil, a memorial to those lost in the First War. Families and pilgrims once crossed the calm lake waters to honor the dead at Heroes' Vigil. The stone memorial rises on the central island, marking the heavy loss of human life in the First War against the Orcish Horde. Now the island is hostile, and those who come to pay their respects must face the wizards' camp beside the monument. Aggressive murlocs hold Stone Cairn Lake's southern banks. Crude huts line the water, and the murlocs harass anyone who comes near. Rich mineral veins run through the hills and rocky outcrops around the lake, drawing prospectors and miners despite the dangers along the shore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stone-cairn-lake-808fc2551ff7ff4828b6/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["subzone:stonefield-farm"] = {
  hash = "416b04",
  fullHash = "416b04",
  text = "Stonefield Farm. In southern Elwynn Forest, the Stonefield family works its fields while a long feud divides them from the Maclures. South of Goldshire, the Stonefields grow crops for the realm. For decades, they have quarreled with the nearby Maclure Vineyards. Each household accuses the other of theft and trespassing, and even small disputes keep tensions high. Gramma Stonefield, Ma Stonefield, and young Tommy Joe Stonefield make their home here.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonefield-farm-35f31735cfc175dbfcaf/1-0000.mp3", duration = 26.5926531, start = 0},
  },
}
P.transport["subzone:stonefire-tavern"] = {
  hash = "5a0bb0",
  fullHash = "5a0bb0",
  text = "Stonefire Tavern. In Ironforge’s Commons, travelers find the Stonefire Tavern just north of the city gates. Its hearth, dwarven ale, and rooms offer rest to those arriving from across Khaz Modan. In Ironforge’s Commons, just north of the fortress gates, Innkeeper Firebrew runs Stonefire Tavern with his daughter Gwenna. Weary wayfarers can find meals, local brews, and lodging beneath the mountain.\n\nTravelers come from across the Alliance to rest from Dun Morogh’s mountain snows, trade tales, or gather supplies before exploring the city. The hearth draws them together at the heart of the Commons.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonefire-tavern-d39b81a7eddaa611473f/1-0000.mp3", duration = 36.7542857, start = 0},
  },
}
P.transport["subzone:stonesplinter-valley"] = {
  hash = "428b0d",
  fullHash = "428b0d",
  text = "Stonesplinter Valley. In southwestern Loch Modan, Stonesplinter troggs hold a mountain vale behind crude defenses. Their chieftain, Grawmug, leads the tribe from within. Among the crags of southwestern Loch Modan, Stonesplinter troggs have made their stronghold. Troggs clawed up from underground across Khaz Modan and ended the quiet that once filled this hollow. The Stonesplinter tribe claimed the valley and carved crude defenses into its rocky passes.\n\nThey dug dens and raised barricades, and now hunt anything that comes too close. Their numbers threaten the roads through southern Loch Modan. So Mountaineers from Thelsamar hire mercenaries to thin the tribe and bring down Grawmug, its towering warlord.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonesplinter-valley-ac851a62ba1e00b3a61b/1-0000.mp3", duration = 43.2587755, start = 0},
  },
}
P.transport["subzone:stonetalon-peak"] = {
  hash = "465f86",
  fullHash = "1e42fe",
  text = "Stonetalon Peak. At Stonetalon Peak, kaldorei Sentinels and druids guard an ancient sanctuary. Its sheltered valley is sacred to the night elves and remains the Alliance’s main foothold in the high mountains. High above the dry lower ranges, Stonetalon Peak opens into a green valley. Its ruins reach back millennia to temples that honored Queen Azshara before the Great Sundering. Night elven Sentinels and druids care for the sanctuary now. They keep a barrow den and an Alliance flight roost here. During the Third War, Jaina Proudmoore’s human expedition and Thrall’s Horde climbed Stonetalon Peak, each seeking the Oracle in the deep caverns. Medivh’s visions had led them there. When they met, these mortal enemies laid down their blades. Their uneasy pact helped them stand against the Burning Legion at Mount Hyjal. Sentinel patrols still guard the peak, and Horde incursions in the lowlands keep its defenders alert.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonetalon-peak-89c5ed66dbf1b870e60e/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["subzone:stonewatch"] = {
  hash = "c97a7a",
  fullHash = "fc4388",
  text = "Stonewatch. Blackrock orcs hold Stonewatch above the approaches from the Burning Steppes, and Lakeshire faces their threat. The fortress once guarded Redridge against invasions from the north. Stonewatch overlooks the cliffs near Stonewatch Falls. Its tower and keep command the approaches from the Burning Steppes. Lakeshire's defenders held the fortress first, until Morganth, a rogue warlock, allied with the Blackrock clan. With dark magic, the orcs overwhelmed the 12th Sabre Regiment and seized the keep.\n\nMorganth then turned against his allies and withdrew to the nearby Tower of Ilgalar with an army of Shadowhide gnolls. The Blackrock orcs held Stonewatch under Warlord Gath'Ilzogg and Lieutenant Tharil'zun. Blackrock orcs hold Stonewatch, leaving Lakeshire open to conquest. Stormwind's House of Nobles has sent no substantial military reinforcements, whether from indifference or paralysis. Magistrate Solomon and Marshal Marris have had to hire mercenaries and call for volunteers.\n\nTheir best hope of lifting the threat over the region is to strike at the fortress's leaders, Tharil'zun and Gath'Ilzogg.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonewatch-715af541bdfd066aad22/1-0000.mp3", duration = 68.5191837, start = 0},
  },
}
P.transport["subzone:stonewatch-falls"] = {
  hash = "bfa246",
  fullHash = "bfa246",
  text = "Stonewatch Falls. Water spills into a murloc-claimed pool at Stonewatch Falls, beneath Stonewatch in the eastern Redridge Mountains. Stonewatch Falls pours down the slope beneath Stonewatch, the Blackrock orc stronghold. Its water runs from Lake Everstill’s eastern river and gathers in a deep pool against the mountainside. Murlocs have claimed the shore with crude reed hovels, and prey on travelers who come too close to the water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonewatch-falls-781e8760054db1689563/1-0000.mp3", duration = 23.9542857, start = 0},
  },
}
P.transport["subzone:stonewatch-keep"] = {
  hash = "3f0834",
  fullHash = "29a65a",
  text = "Stonewatch Keep. Blackrock orcs now hold Stonewatch Keep in eastern Redridge Mountains and turn its walls against Lakeshire. The Kingdom of Stormwind built and manned the fortress before the invaders seized it as a base for their warlords. Stonewatch Keep once guarded the eastern ridges and Lakeshire's settlers from hostile incursions. Then the renegade warlock Morganth joined forces with the Blackrock clan. His dark magic strengthened the orcs, who stormed the fortress and overcame its human defenders. After the victory, Morganth abandoned the clan to raise the nearby Tower of Ilgalar and subjugate local gnolls. The Blackrock orcs kept the keep as a staging ground for attacks on the valley. A strong Blackrock garrison holds Stonewatch Keep under the orc warlord Gath'Ilzogg and his lieutenant, Tharil'zun. From the ramparts, they direct raids across Redridge and take prisoners, among them Stormwind's Corporal Keeshan.\n\nStormwind's forces are spread thin, so the kingdom cannot send a full regiment to reclaim the fortress. Magistrate Solomon and Marshal Marris have hired mercenary champions to enter the stronghold and kill the Blackrock leaders before Lakeshire is overrun.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonewatch-keep-d5c030813d85caf94b14/1-0000.mp3", duration = 69.3289796, start = 0},
  },
}
P.transport["subzone:stonewatch-tower"] = {
  hash = "fdce42",
  fullHash = "fdce42",
  text = "Stonewatch Tower. Blackrock sentinels hold Stonewatch Tower in northeastern Redridge. Once Lakeshire's outpost, it now helps the clan watch the ridges and guard its mountain stronghold. Above Lake Everstill, Stonewatch Tower guards the high mountain passes. The Kingdom of Stormwind built it as a forward scout for Stonewatch Keep. From its heights, sentries watched the eastern ridges and warned Lakeshire of threats from the Burning Steppes.\n\nThen Warlord Gath'Ilzogg's Blackrock orcs swept down from the heights. They overcame the human defenders and seized the stronghold for their war effort. Blackrock sentinels now watch the tower, keeping Alliance scouts from reaching the fortress unseen.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonewatch-tower-679d848378dc35190708/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["subzone:stonewrought-dam"] = {
  hash = "9c3d6c",
  fullHash = "c6144b",
  text = "Stonewrought Dam. Along Loch Modan’s northern rim, waters gather behind Stonewrought Dam. The dwarven barrier holds back the Loch and drains the Wetlands below into habitable marshes. East of Dun Algaz, Stonewrought Dam spans a canyon in one of the great works of dwarven craft. Dark Iron architect Franclorn Forgewright designed it and pioneered the stonewrought technique used to raise it. By holding water in the mountain basin, the dam doubled the Loch’s surface area and steadily lowered the waters to the north. The Wetlands formed from a valley once wholly flooded. Stonewrought Dam now serves Ironforge, but Dark Iron saboteurs from the southern mountains target it. After recent assaults and attempts to slip inside, Ironforge placed a garrison here under Chief Engineer Hinderweir the Seventh. Guards and engineers patrol the masonry day and night. Should the dam be breached, the Loch could drain and send a devastating flood across the Wetlands below.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonewrought-dam-e669fd48c7feabe46949/1-0000.mp3", duration = 58.9844898, start = 0},
  },
}
P.transport["subzone:stormwind-gate"] = {
  hash = "b3cbcd",
  fullHash = "b3cbcd",
  text = "Stormwind Gate. Stormwind Gate stands open between Elwynn Forest and Stormwind City, watched by sentries. Beyond its arch, stone monuments line the Valley of Heroes. The Stormwind City Guard holds this passage, and patrols march from the outer arch toward the Valley of Heroes. Unrest lingers in Elwynn, yet the iron and stone gates remain open. Travelers, merchants, and defenders returning from the road pass through toward the heart of the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stormwind-gate-e358b5a1d3b3320f8635/1-0000.mp3", duration = 27.1673469, start = 0},
  },
}
P.transport["subzone:stormwind-keep"] = {
  hash = "d67dd4",
  fullHash = "d67dd4",
  text = "Stormwind Keep. Stormwind Keep holds the royal court above the capital. Rebuilt after its ruin in the First War, it is now home to the young boy-king Anduin Wrynn and his regent, Highlord Bolvar Fordragon. Stormwind Keep crowns a plateau above the city, with halls for the crown and the kingdom’s defense. The Old Horde burned the first stronghold after King Llane was assassinated near the end of the First War. After the Alliance reclaimed the kingdom, builders raised the keep again on its old foundations. Its halls include the grand throne room and the War Room, while garden courtyards and the Royal Library offer quieter spaces.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stormwind-keep-11ccba1eddc9d7569389/1-0000.mp3", duration = 37.2767347, start = 0},
  },
}
P.transport["subzone:stormwind-stockade"] = {
  hash = "e133a7",
  fullHash = "e133a7",
  text = "Stormwind Stockade. Stormwind Stockade has fallen into chaos beneath the canals near the Mage Quarter. A coordinated revolt has driven the guards from the lower cells, and the prison's most dangerous prisoners roam free. Warden Thelwater oversees the Stockade, where Stormwind holds cutthroats, Defias operatives, captured Blackrock orcs, and Dark Iron dwarves. The Defias conspirator Bazil Thredd led the uprising, and now prisoners roam the corridors. Thelwater has secured the entrance, but the revolt still threatens to spill into the canals. He needs adventurers to enter the prison and put it down.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stormwind-stockade-4bbe5d9337bc542029a4/1-0000.mp3", duration = 35.9444898, start = 0},
  },
}
P.transport["subzone:stormwind-stockade-classic"] = {
  hash = "36c722",
  fullHash = "36c722",
  text = "Stormwind Stockade (Classic). A revolt has put the prisoners in control beneath Stormwind City's canal district. The Stockade lies beside the canals between Old Town and the Mage Quarter. Warden Thelwater oversees the Stockade, where Stormwind holds its most dangerous prisoners. Among them are Defias Brotherhood cutthroats, a Blackrock orc, an ogre and a Dark Iron dwarf. Then Bazil Thredd led a coordinated riot that overwhelmed the garrison. The surviving guards fled, and prisoners now rule the halls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stormwind-stockade-classic-1e34b8c664940c66e8ca/1-0000.mp3", duration = 30.7722449, start = 0},
  },
}
P.transport["subzone:stoutlager-inn"] = {
  hash = "6b5bc5",
  fullHash = "6b5bc5",
  text = "Stoutlager Inn. In Thelsamar, Stoutlager Inn welcomes travelers crossing western Loch Modan with a warm hearth and a place to gather. Stoutlager Inn draws miners, mountaineers, and travelers passing between Dun Morogh and the Wetlands. They trade rumors, find beds, and share dwarven ale beneath its roof. Beyond Thelsamar, troggs and kobolds make the wilderness dangerous, so the inn’s stone walls and fires offer welcome shelter.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stoutlager-inn-357c4cf71528da564b09/1-0000.mp3", duration = 27.2195918, start = 0},
  },
}
P.transport["subzone:strahnbrad"] = {
  hash = "12a91c",
  fullHash = "37b0d7",
  text = "Strahnbrad. Syndicate brigands hold Strahnbrad, a ruined town in the northeastern heights of the Alterac Mountains. Near the Western Plaguelands border, it has fallen into decay since Prince Arthas Menethil defended it from Blackrock orc raiders. Strahnbrad belonged to the Kingdom of Alterac until Lordaeron absorbed it after the Second War. On the eve of the Third War, Blackrock clan orcs raided the town to take human sacrifices for the Burning Legion. Prince Arthas Menethil rode to its defense with the Knights of the Silver Hand. He drove off the raiders and slew their slave master, but Strahnbrad was left bloodied. Soon after, the Scourge brought down Lordaeron, and the town was abandoned to the elements. The Syndicate uses Strahnbrad as an operations hub. Displaced Alteraci nobles and outlaws patrol the abandoned town hall and blacksmith, now their hideouts and staging grounds as they plan to reclaim their fallen realm. The Syndicate keeps supplies and captive labor in the ruins, including the orc Gol'dir. Horde scouts from Tarren Mill seek to free him.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_strahnbrad-fa2ef09a5957fa620186/1-0000.mp3", duration = 61.5183673, start = 0},
  },
}
P.transport["subzone:sun-rock-retreat"] = {
  hash = "d91992",
  fullHash = "cefd50",
  text = "Sun Rock Retreat. In the high basin south of Mirkfallon Lake, Sun Rock Retreat shelters the Horde among Stonetalon's peaks. The tauren hold this ground sacred, and orcs and tauren use the settlement as a base and supply post. South of Mirkfallon Lake, Sun Rock Retreat rests in a mountain basin the tauren have long held sacred. Their ancient tradition says An'she, the Sun, kissed the peak above the village. Before the Horde came, tauren shamans and pilgrims traveled here for rites that crossed the mortal veil. They drew strength from the land's close bond with the spirit world. Orcs and tauren now hold Sun Rock Retreat as the Horde's chief base across the Stonetalon Mountains. Together they seek a secure foothold against hostile harpy broods, local night elf sentinels, and the Venture Company's industrial pillaging. Trade and flight routes link the retreat with Thunder Bluff, the Crossroads, and the borders of Ashenvale. Here, those who brave the crags find shelter, provisions, and spiritual guidance.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sun-rock-retreat-8963d4700a7fe2b2b0ab/1-0000.mp3", duration = 61.8318367, start = 0},
  },
}
P.transport["subzone:talondeep-path"] = {
  hash = "21eba1",
  fullHash = "21eba1",
  text = "Talondeep Path. Beneath the ridge, Talondeep Path links Ashenvale with the Stonetalon Mountains. Its quiet tunnel runs from the woods west of Mystral Lake to Windshear Crag. Travelers between Ashenvale and the Stonetalon Mountains can climb the ridge or go under it by Talondeep Path. It joins the woods west of Mystral Lake to the northwestern reaches of Windshear Crag. Surface trails cross dangerous country, where predators and warring factions roam. The tunnel stays calm, with no hostile beasts or encampments.\n\nSide pockets twist away from the passage, and crevices and natural alcoves break up the rock. Above ground, faint traces of an old road remain along the peaks. Travelers once crossed there before taking the route through the stone.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_talondeep-path-ea0d7ba6185591b3c22b/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["subzone:talondeep-vale"] = {
  hash = "a4c4cb",
  fullHash = "a4c4cb",
  text = "Talondeep Vale. In south-central Ashenvale, the wooded vale carries travelers toward the Stonetalon Mountains. Talondeep Vale lies beneath Ashenvale’s trees. Silverwind Refuge stands to the east, with the Ruins of Stardust nearby. To the south, the land rises toward the Stonetalon Mountains. Travelers cross the valley between Ashenvale’s heart and the high crags beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_talondeep-vale-a72d400a4ab7d846c5ed/1-0000.mp3", duration = 22.4391837, start = 0},
  },
}
P.transport["subzone:tarren-mill"] = {
  hash = "2bb57b",
  fullHash = "c7bbf1",
  text = "Tarren Mill. In northern Hillsbrad Foothills, Tarren Mill holds the Horde's line beneath the Alterac Mountains. Once a peaceful human farming village, it is now a Forsaken outpost locked in conflict with Southshore to the south. Since the Third War, Tarren Mill's fields and mill have fallen silent. Before then, the town thrived on farming and served Lordaeron. During the Second War, Alliance forces near Tarren Mill freed high elven archers from orc encampments. Their rescue secured Quel'Thalas's full commitment to the Alliance of Lordaeron.\n\nThe town's living inhabitants are gone, replaced by the Forsaken. Its buildings are weathered, its fields barren, and its mill quiet. The Forsaken fortify Tarren Mill against mountain beasts, Syndicate outlaws, and Alliance skirmishers. Tarren Mill is the Horde's forward base in Hillsbrad. Southshore, the Alliance port, lies directly across from it, and the road between the towns has become a warzone. From Tarren Mill, Horde travelers push back against the human farmers and soldiers occupying Hillsbrad. They also coordinate strikes against dwarven excavators at Dun Garok and secure the dangerous roads that climb into the snowy crags of the Alterac Mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tarren-mill-60028a6c40b34df7dee4/1-0000.mp3", duration = 72.3330612, start = 0},
  },
}
P.transport["subzone:temple-gardens"] = {
  hash = "80bdf2",
  fullHash = "c85ef7",
  text = "Temple Gardens. In Temple Gardens, water and bridges gather at the heart of Darnassus. The city bank stands on the main island, beside the Temple of the Moon to the south and a glowing tree portal to Teldrassil's base. Water runs beneath wooden bridges through Darnassus's center. They link the Temple Gardens' islets with the Cenarion Enclave to the north, the terraces to the east, and the Temple of the Moon to the south. Night elves tend the waters and foliage. Travelers and priestesses find a quiet place to rest. Darnassus's central vault and bank occupy the main island. On its western bank, a great glowing pink tree portal carries travelers through the boughs to Rut'theran Village at Teldrassil's base. From there, coastal docks and flight paths connect the World Tree to other destinations.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_temple-gardens-5fff16230fceea7de265/1-0000.mp3", duration = 48.1959184, start = 0},
  },
}
P.transport["subzone:temple-of-the-moon"] = {
  hash = "ff2b33",
  fullHash = "1ade3e",
  text = "Temple of the Moon. High Priestess Tyrande Whisperwind guides her people from the Temple of the Moon in Darnassus. The sanctuary is the seat of government on Teldrassil and home to the Sisterhood of Elune, whose priestesses tend a sacred moonwell. Built soon after the Third War, the Temple of the Moon rose as the night elves made their home on Teldrassil. It is among the largest stone works made by modern kaldorei hands. Its marble came from quarries on the Kalimdor mainland and crossed the sea by magical means.\n\nAt the temple's heart, a broad moonwell rests beneath the statue of Haidene. Pilgrims come to worship and reflect beside its consecrated waters. The temple also holds Darnassus's highest seat of government, where High Priestess Tyrande Whisperwind guides her people through a new age. The priestesses of the Sisterhood of Elune serve their goddess from the temple terraces, in worship and in the field. Emissaries and dispatched sisters travel across northern Kalimdor to investigate threats or aid local sentinels. Priestess Gwennyth Bly'Leggonde, for example, makes inquiries along the Darkshore coastline.\n\nNovices and veteran priestesses gather beneath the starry vaulted ceiling to learn divine spellwork, tend the wounded, and guard the sanctum from outside corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_temple-of-the-moon-7fb13e0893359019bad1/1-0000.mp3", duration = 77.4530612, start = 0},
  },
}
P.transport["subzone:the-loch"] = {
  hash = "913e57",
  fullHash = "dcabc3",
  text = "The Loch. The Loch's waters fill the heart of Loch Modan, held back by the Stonewrought Dam. The lake is Khaz Modan's largest body of water and sustains the dwarven settlements around it. At the center of Loch Modan, The Loch spreads among the largest inland lakes in the known world. Only Lordamere Lake and Darrowmere Lake to the north rival its size. Local fishermen draw from its waters, while Thelsamar and nearby hunting lodges enjoy a peaceful setting along its shores. Beneath the calm surface, aggressive threshadons and freshwater beasts make swimming across perilous. To the north, the Stonewrought Dam keeps The Loch in its tranquil state. The massive dwarven structure crosses a cleft in the mountains and prevents the lake from flooding into the Wetlands below. Its upkeep preserves the valley's ecosystem and helps keep Khaz Modan secure.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_the-loch-5d846b6133a5d256186f/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["subzone:thelsamar"] = {
  hash = "7bbe46",
  fullHash = "28bc11",
  text = "Thelsamar. In Thelsamar, travelers find shelter on the road between Dun Morogh and the Wetlands. The town keeps watch over the western bluffs above Loch Modan's great lake as troggs and ogres press nearby. Thelsamar gathers dwarven life beneath stout roofs of stone and timber. At the Stoutlager Inn, travelers can rest, and nearby they find a gryphon roost, crafting stations, and supply merchants. The town lies along the road from the South Gate Pass into Dun Morogh to the Algaz Pass toward the Wetlands. Travelers crossing the region pass through its doors. Trouble presses in on Thelsamar from several sides. Troggs pour from Stonesplinter Valley to the south, while bears and other predators haunt Grizzlepaw Ridge. Ironforge's regular forces are stretched thin across the realm. So the local magistrate and Mountaineers rely on travelers and mercenaries to patrol the trade roads and drive back hostile forces.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thelsamar-f0852142d11a6695a9ac/1-0000.mp3", duration = 54.5436735, start = 0},
  },
}
P.transport["subzone:thistlefur-hold"] = {
  hash = "409dc7",
  fullHash = "409dc7",
  text = "Thistlefur Hold. At Thistlefur Hold, corruption has turned the furbolgs against every outsider who draws near. Their cavern den lies at the northern end of Thistlefur Village in west-central Ashenvale. At the northern end of Thistlefur Village, Thistlefur Hold lies at the heart of the Thistlefur tribe's territory. Corruption has driven the furbolgs mad, and they attack travelers and neighbors who draw near. In the winding caverns, the tribe hoards scavenged relics, including troll charms sought by the Darkspear. Deep within, wooden cages hold captives, among them Ruul Snowhoof, a tauren brave.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thistlefur-hold-115903cb030c044459f1/1-0000.mp3", duration = 35.9706122, start = 0},
  },
}
P.transport["subzone:thistlefur-village"] = {
  hash = "f019d4",
  fullHash = "f019d4",
  text = "Thistlefur Village. In Ashenvale, Thistlefur furbolgs attack outsiders who approach their village north of Astranaar. Corruption has taken hold of the tribe, making the village dangerous to travelers. Among Ashenvale’s woodland communities, Thistlefur Village lies north of Astranaar. Corruption has maddened the Thistlefur furbolgs. They guard the paths through their settlement and attack travelers who draw near. Dal Bloodclaw and Rorgish Jowl lead the clan as fierce chieftains. Their aggression threatens nearby settlements and those traveling the roads.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thistlefur-village-da5b25c0add420d0c085/1-0000.mp3", duration = 31.6604082, start = 0},
  },
}
P.transport["subzone:thistlefuzz-arcanery"] = {
  hash = "ee19f7",
  fullHash = "ee19f7",
  text = "Thistlefuzz Arcanery. East of the Great Forge, Thistlefuzz Arcanery draws enchanters and scholars to a prominent gnome-run workshop and academy. Its chambers hum with arcane energy beside the fires of dwarven industry, offering a haven to those who weave magic into metal and parchment. East of the Great Forge, Thistlefuzz Arcanery offers a quieter craft beside the clanging anvils of dwarven smiths. Across its two levels, scholars, practitioners, and apprentices gather to study enchanting and the arcane arts. Dwarves reshape steel with muscle and fire, while the gnomes bind raw arcane energy into weapons, armor, and curious tools. For spellcasters making their way through the mountain stronghold, the Arcanery remains an essential sanctuary.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thistlefuzz-arcanery-f6dfab61a8e205726d53/1-0000.mp3", duration = 44.1991837, start = 0},
  },
}
P.transport["subzone:three-corners"] = {
  hash = "3d62a3",
  fullHash = "3d62a3",
  text = "Three Corners. At Three Corners, guards watch the western edge of the Redridge Mountains. Roads run from there to Goldshire, Lakeshire, and Darkshire, while gnolls threaten travelers and supply wagons. Three roads meet here, linking the southern settlements of Stormwind. Goldshire lies west in Elwynn Forest, Lakeshire northeast in Redridge, and Darkshire south in Duskwood. Stormwind built Tower Watch at the junction, where guards and scouts work to keep the roads clear. Gnolls from Redridge threaten travelers and supply wagons moving between the regions.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_three-corners-90896900db1e3434e6d8/1-0000.mp3", duration = 33.5412245, start = 0},
  },
}
P.transport["subzone:thunder-falls"] = {
  hash = "5b6646",
  fullHash = "5b6646",
  text = "Thunder Falls. Bandits now hold a cottage beside the stream at Thunder Falls, high in northwestern Elwynn Forest. Above Mirror Lake, a mountain stream runs between the steep cliffs of Thunder Falls. From an unreachable cascade in the north, it spills down in falls on both sides. One pours into Mirror Lake, while the stream runs west toward Westfall’s rugged border.\n\nA cottage, a dock, and an outdoor forge stand beside the water. Bandits now claim the clearing.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thunder-falls-da47b8fdde5be83093ca/1-0000.mp3", duration = 28.7608163, start = 0},
  },
}
P.transport["subzone:thunderbrew-distillery"] = {
  hash = "4464b9",
  fullHash = "9432e7",
  text = "Thunderbrew Distillery. In Kharanos, Thunderbrew Distillery offers travelers ale and shelter. Its brewhouse and tavern draw mountain travelers, while mentors and tradesfolk share their skills within. The Thunderbrew Distillery anchors Kharanos in southern Dun Morogh. Arkilus Thunderbrew founded its brewhouse, and his kin have kept it in the family. Its strong ales are known across Khaz Modan for warming those who face the mountain cold. Innkeeper Belm manages the inn, where weary mountaineers find a fire, hearty food, and beds beyond the blizzards outside. Kharanos is the first major settlement travelers reach after leaving Coldridge Valley. Beneath the distillery’s timber rafters, instructors teach martial arts, holy rites, arcane studies, and roguecraft. Teachers also offer cooking and first aid. The hall pours its well-known stouts and gives travelers a place to prepare for the road ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thunderbrew-distillery-d304ad06f8cf2ca59879/1-0000.mp3", duration = 54.4130612, start = 0},
  },
}
P.transport["subzone:tinker-town"] = {
  hash = "012a90",
  fullHash = "8d5809",
  text = "Tinker Town. Tinker Town is where gnomes make their home in exile beneath Ironforge. Since Gnomeregan fell, it has been the seat of High Tinker Gelbin Mekkatorque’s government and the Ironforge end of the Deeprun Tram. Tinker Town shelters the gnomes who fled Gnomeregan. Troggs overran their high-tech city, so Ironforge’s dwarves opened their gates. They gave the refugees a cavern once used by dwarves, where the Deeprun Tram entrance already stood. High Tinker Gelbin Mekkatorque and his council lead the gnomes from here.\n\nAround a massive spherical contraption, the gnomes have rebuilt a semblance of their civilization. Gears whir, alchemy is tested, and gadgets take shape in the cramped district. Though guests in a stone city, the gnomes remain determined to reclaim their subterranean homeland. Tinker Town holds the Ironforge entrance to the Deeprun Tram. The engineering wonder carries travelers swiftly between the dwarven capital and Stormwind, joining the two cities.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tinker-town-b1fcb460caa5a83c2559/1-0000.mp3", duration = 60.4995918, start = 0},
  },
}
P.transport["subzone:tinkers-court"] = {
  hash = "aa1f33",
  fullHash = "aa1f33",
  text = "Tinkers' Court. In Gnomeregan's heart, Tinkers' Court once brought the city's leaders together. Now Mekgineer Thermaplugg holds the chamber. Before disaster drove the gnomes from Gnomeregan, their leaders gathered in Tinkers' Court. High Tinker Gelbin Mekkatorque met there with advisors and master inventors, among them Tinkmaster Overspark. They debated new technology, governed civic matters, and guided gnomish society. Beyond the Engineering Labs and the Launch Bay, the chamber stood at the heart of gnomish government and invention.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tinkers-court-dca54f9ebb6ff53a3644/1-0000.mp3", duration = 31.2685714, start = 0},
  },
}
P.transport["subzone:tower-of-althalaxx"] = {
  hash = "b0eea6",
  fullHash = "b0eea6",
  text = "Tower of Althalaxx. Dark sorcery stirs at the Tower of Althalaxx on northern Darkshore's coast. Athrikus Narassin once withdrew there, and now demonic cultists and warlocks shelter within its ancient Highborne walls. Queen Azshara settled favored Highborne servants in Ameth'Aran and Bashal'Aran ten thousand years ago. She placed the powerful sorcerer Athrikus Narassin in authority over them. As Athrikus turned from civic governance, he withdrew to the nearby Tower of Althalaxx. The Great Sundering shattered ancient Kalimdor, yet the tower endured on Darkshore's desolate coast, a quiet ruin of forgotten elven magic.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tower-of-althalaxx-a35957ca2c0cde8ec06d/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["subzone:tower-of-azora"] = {
  hash = "1f04e6",
  fullHash = "1f04e6",
  text = "Tower of Azora. At the Tower of Azora, Archmage Theocritus leads a scholarly outpost in eastern Elwynn Forest. The slender spire rises north of the Brackwell Pumpkin Patch, where its human master keeps watch over a silent magical feud with a hostile tower in the Redridge Mountains. The Tower of Azora stands beside the eastern road to the Redridge Mountains. Gnome spellcasters staff most of the spire, where Archmage Theocritus guides their studies of strange curiosities and teaches wandering spellweavers. A wild magical aura surrounds the tower and sometimes warps nearby wildlife. Inside, gnome servants contend with enchanted household items and mutated insects that creep past the doorway.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tower-of-azora-712fd2b125155c780c7a/1-0000.mp3", duration = 42.9453061, start = 0},
  },
}
P.transport["subzone:tower-of-ilgalar"] = {
  hash = "42459b",
  fullHash = "126ec6",
  text = "Tower of Ilgalar. In eastern Redridge, Morganth commands the Shadowhide gnolls from the Tower of Ilgalar. Banished from Stormwind, the sorcerer practices dark magic far from the city. Morganth holds the Tower of Ilgalar above eastern Redridge. Stormwind cast the sorcerer out of its Mage Quarter for forbidden magic. He withdrew to these heights to pursue the dark arts beyond imperial interference. The local Shadowhide gnolls guard the spire's base at his command. Inside, conjured demonic hounds stalk the halls, while shadowy power threatens Lakeshire below. The Tower of Ilgalar is often compared with the Tower of Azora in Elwynn Forest. No one knows who built Ilgalar, and the two towers face one another in quiet magical opposition. From Elwynn, the archmage Theocritus watches Ilgalar through enchanted devices such as the Eye of Azora. He studies Morganth's experiments and seeks to stop the sorcerer's corruption from spreading through the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tower-of-ilgalar-842ed31b61210709f19b/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["subzone:trade-district"] = {
  hash = "ba5adf",
  fullHash = "241681",
  text = "Trade District. Trade District draws merchants and travelers through Stormwind’s busy heart. Its bank, Auction House, guild registry, and shops serve citizens and adventurers alike. You pass beneath the stone arches from the Valley of Heroes into Trade District. The open plaza is Stormwind’s main marketplace and a crossroads for goods and travel. The Auction House stands at its center, with the Stormwind Counting House, the city’s main bank, and The Gilded Rose nearby.\n\nFrom here, roads lead to Old Town, Cathedral Square, and the Mage Quarter. Coin, raw goods, and adventurers’ supplies pass through the district on their way across the realm. Shops line the paved avenues and canals with goods for daily needs and travel. Weller’s Arsenal and Lionheart Armory sell blades and mail, while The Empty Quiver offers bows. Stalls carry fresh flowers and aged vintages from the Gallina Winery.\n\nJust inside the gates, the Stormwind Visitor’s Center handles newly registered guild charters and tabard designs. On the eastern side, an elevated ramp leads to the Gryphon Roost, linking Stormwind’s markets with Alliance territories.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_trade-district-5f443e658b08a285ead0/1-0000.mp3", duration = 69.5118367, start = 0},
  },
}
P.transport["subzone:tradesmen-s-terrace"] = {
  hash = "c5ee29",
  fullHash = "fbb52d",
  text = "Tradesmen's Terrace. Merchants and craftspeople gather in Tradesmen's Terrace along Darnassus's southern edge. Its auction house and shops connect travelers with goods from Teldrassil and beyond. Shops and merchants fill Darnassus's southern stretch in Tradesmen's Terrace. Kaldorei and travelers from across the Alliance find provisions, crafting supplies, and the city's central auction house here. Paths lead north to the Warrior's Terrace and west toward the Temple Gardens and the Temple of the Moon. Travelers bound for the wilds gather what they need here. Kaldorei shops favor quiet stone, timber, and woven goods shaped to live in harmony with nature. No roaring furnaces or smog rise from these workshops as they do in dwarven and human ones. Adventurers seeking trade contracts, repairs, or materials gathered from Teldrassil's boughs find northern Kalimdor's principal center of business here.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tradesmen-s-terrace-ec6fe67303528d991f90/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["subzone:train-depot"] = {
  hash = "5e1b6e",
  fullHash = "5e1b6e",
  text = "Train Depot. Beneath Gnomeregan's entrance in Dun Morogh, the Train Depot lies overrun by leper gnomes and troggs. Once, its rails carried gnomes through the city. Now the depot is in ruin. Beneath the grand elevator from Dun Morogh, the Train Depot's platforms and tracks lie in ruin. Once, rail lines carried gnomes through Gnomeregan. Radiation swept through the city and changed the workers who remained into crazed leper gnomes. Troggs from below have overrun the rails. You must cross the depot to reach deeper parts of the city, including Clockwerk Run, the Loading Room, and the inner engineering facilities.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_train-depot-a652e3d12bdd2a209ce6/1-0000.mp3", duration = 37.877551, start = 0},
  },
}
P.transport["subzone:tranquil-gardens-cemetery"] = {
  hash = "7b6e79",
  fullHash = "c65695",
  text = "Tranquil Gardens Cemetery. Southeast of Darkshire, Tranquil Gardens Cemetery is overrun by shambling skeletons and ghouls. The dead make it a danger to the nearby town. Once the people of Grand Hamlet laid their dead in Tranquil Gardens Cemetery. Then dark curses settled over Duskwood, and the buried began clawing out of their plots. Skeletal warriors and mages haunt the gravestones, along with wandering undead. They are weaker than the horrors deeper in the woods, but their nearness to Darkshire makes them a constant threat to the townsfolk. Tranquil Gardens Cemetery lies near Darkshire's edge, where the Night Watch holds its line. The Watch sends fresh recruits and arriving adventurers to thin the rising dead before they reach the settlement. Yet more dangerous foes lurk among the tumbled headstones and the ruined chapel. The Insane Ghoul is one of them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tranquil-gardens-cemetery-6ab4b387eb11b56a30e8/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["subzone:tundrid-hills"] = {
  hash = "79400d",
  fullHash = "79400d",
  text = "Tundrid Hills. In south-central Dun Morogh, the Tundrid Hills offer a perilous crossing west of Gol'Bolar Quarry. Snowbound ridges and dangerous wildlife make every step off the rocky passes a risk. From Coldridge Valley, the Tundrid Hills give you a rough way into eastern Dun Morogh, away from the main roads through Kharanos. Jagged slopes hold the snow, and the crossing is dangerous. Ferocious predators prowl the hills, so keep a weapon ready if you leave the beaten path.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tundrid-hills-0e3c3415c11e22506806/1-0000.mp3", duration = 28.0293878, start = 0},
  },
}
P.transport["subzone:twilight-grove"] = {
  hash = "40d2dc",
  fullHash = "1ef360",
  text = "Twilight Grove. At Duskwood's center, Twilight Grove shelters lush Kalimdor flora beneath its great tree. A moonwell and ancient night elf architecture surround a massive emerald gateway to the Emerald Dream. Behind steep crater ridges in Duskwood's heart, Twilight Grove seems utterly alien to the Eastern Kingdoms. Night elf gazebos and green meadows surround a serene moonwell. An unnamed great tree towers over the gloomy canopy.\n\nThe tree draws vigor from the Emerald Dream into the waking world. So the crater thrives beneath Duskwood's eternal gloom. At the great tree's base stands a massive stone portal, one of four known gateways linking the physical realm directly to the Emerald Dream. Ysera's green dragonflight traditionally watches over this gateway. Dark whispers say malevolent forces have begun twisting the tranquil realm beyond.\n\nThe gateway remains largely silent. Yet its emerald swirl warns that cosmic corruption may spill into Duskwood from paths deeper than the Scourge or the local worgen.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_twilight-grove-16e98a8f37d3ef5f0b3c/1-0000.mp3", duration = 64.3918367, start = 0},
  },
}
P.transport["subzone:twilight-shore-darkshore"] = {
  hash = "4aa939",
  fullHash = "4aa939",
  text = "Twilight Shore (Darkshore). Murloc tribes and hungry sea creatures crowd Twilight Shore in southern Darkshore. Its rugged coast runs from the Long Wash to Ashenvale, where misty beaches meet cliffs, islets, and dangerous surf. Twilight Shore runs south from the Long Wash, past the ruins of Ameth'Aran, toward Ashenvale. Gray beaches give way to sharp cliffs and rocky islands. Threshadons and sea crawlers prowl the waters, while aggressive murloc camps line the shore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_twilight-shore-darkshore-5c043b832cb961243351/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["subzone:twilight-vale"] = {
  hash = "c51d9f",
  fullHash = "c51d9f",
  text = "Twilight Vale. In Twilight Vale, beasts and furbolgs prowl the dark woods between Darkshore and Ashenvale. The southern forest marks a perilous passage from Darkshore’s tainted coast to Ashenvale’s sacred canopies. Twilight Vale runs south from Ameth'Aran to the Ashenvale border, where dusk hangs over Darkshore’s southern woods. Corruption has spread deep among the wildlife. Rabid bears roam beside feral nightsabers, and hostile furbolg tribes stalk the trees.\n\nSentinels and travelers urge you to stay on the main road. A few paces into the woods can bring a swift, deadly ambush.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_twilight-vale-1ead52419cf2540164aa/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["subzone:valley-of-heroes"] = {
  hash = "7d9bf7",
  fullHash = "94b955",
  text = "Valley of Heroes. In the Valley of Heroes, stone commanders watch the southern road into Stormwind. Guards hold this fortified crossing over the moat, where the city honors the leaders of the Alliance Expedition to Draenor. You cross the moat beneath statues honoring the Alliance Expedition’s commanders. Stormwind raised the monuments along this causeway as the city was rebuilt after the Second War. The champions marched through the Dark Portal into Draenor to seal the rift forever. They gave their lives so Azeroth might survive.\n\nAs you head north toward the Trade District, you pass Archmage Khadgar, Kurdran Wildhammer, Ranger-Captain Alleria Windrunner, Force Commander Danath Trollbane, and High General Turalyon. General Marcus Jonathan watches Stormwind's gates from horseback. He oversees the guards and the traffic passing in and out. The valley is the city's main defense against an overland invasion.\n\nMajor Mattingly, Field Marshal Stonebridge, and rows of seasoned guards keep watch beside him. Together, they guard the capital from threats beyond its walls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-heroes-3bbb4e1c3865d188b878/1-0000.mp3", duration = 61.5183673, start = 0},
  },
}
P.transport["subzone:valley-of-kings"] = {
  hash = "95a679",
  fullHash = "986801",
  text = "Valley of Kings. At Valley of Kings, stone rulers guard the southern road into the Searing Gorge. In southwestern Loch Modan, the canyon lies south of the passage to Dun Morogh. Blackrock forces and troggs threaten travelers beneath the dwarven monuments. Two immense statues watch over the southern pass: King Madoran Bronzebeard and High Thane Khardros Wildhammer. After the kings died, their sons commissioned the carvings together. The statues honor the allied victory in the War of the Three Hammers, and they face the Dark Iron clan. Beyond them, the southern lands still bear the ruin left by Ragnaros's summoning. The valley links South Gate Pass with Stonesplinter Valley, and an iron gate opens into the Searing Gorge. Hostile Blackrock orcs, Dark Iron dwarves, and volcanic dangers make the passage perilous. So Ironforge mountaineers keep the gate locked and guarded, with Mountaineer Pebblebitty watching the threshold. Only the hardiest travelers may pass, after showing they have the strength to survive beyond it.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-kings-f6c74b611140db7cde9e/1-0000.mp3", duration = 60.2122449, start = 0},
  },
}
P.transport["subzone:vault-of-ironforge"] = {
  hash = "cff63e",
  fullHash = "cff63e",
  text = "Vault of Ironforge. In Ironforge's Commons, citizens and Alliance travelers entrust their wealth to the Vault. Dinita and the Stonemantle family oversee its work. Travelers, soldiers, and merchants bring coin, relics, and provisions to the Vault for safekeeping. City guards and tellers watch the deposits, keeping the wealth of citizens and Alliance visitors secure within the mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_vault-of-ironforge-f8b522b89a2b08d03704/1-0000.mp3", duration = 22.5959184, start = 0},
  },
}
P.transport["subzone:vul-gol-ogre-mound"] = {
  hash = "06cb61",
  fullHash = "97d98c",
  text = "Vul'Gol Ogre Mound. In southern Duskwood, Vul'Gol Ogre Mound shelters the Splinter Fist ogres and their chieftain, Zzarc'Vul. Ruined farmhouses and a cavern beneath the basin hold the clan's carcasses and scavenged plunder. Southwest of the fork toward Stranglethorn Vale, the basin belongs to the Splinter Fist clan. Human families once farmed here, but they fled or perished. Hollow cabins remain, and the ogres use them for shelter. In the cavern beneath the rise, slaughtered black bears lie in piles. Zzarc'Vul rules the encampment, keeping odd trinkets beside ordinary goods the clan has scavenged. Darkshire's Night Watch is stretched thin, guarding the town from rabid worgen and restless dead. Commander Althea Ebonlocke and her militia rely on outside mercenaries to thin the Splinter Fist ranks before the ogres push north. The clan has also raided the recluse Abercrombie and stolen a crate of his alchemical tools. Inquisitive mages seek arcane lenses that Zzarc'Vul is rumored to possess.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_vul-gol-ogre-mound-2406d7bb0bc0a6376e60/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["subzone:war-room"] = {
  hash = "d01110",
  fullHash = "d01110",
  text = "War Room. Commanders gather inside Stormwind Keep to plan the Alliance’s defense. The War Room holds weapons, records, and charts for that work. Beyond Stormwind Keep’s grand chambers, commanders plan campaigns and arrange military supplies. Swords, blunderbusses, and heavy artillery cannons line the stone walls. Nearby tables hold military treatises and chronicles of past wars.\n\nAt the center, a large map shows Alliance deployments across Azeroth. The royal court handles affairs of state just steps away.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_war-room-14383254535dc9a63e9e/1-0000.mp3", duration = 33.4367347, start = 0},
  },
}
P.transport["subzone:warrior-s-terrace"] = {
  hash = "bd35e4",
  fullHash = "bd35e4",
  text = "Warrior's Terrace. Sentinels guard the eastern gate at Warrior's Terrace, where drills and duels fill the plazas. The district is Darnassus's military heart, with battlemasters and warrior trainers overlooking the road into greater Teldrassil. Sentinels guard Darnassus from the Warrior's Terrace, also called the Hall of Justice. Mounted on nightsabers, they watch the high arched gates for travelers from Teldrassil's wilds. In the open plazas, aspiring combatants drill beside seasoned veterans on dueling grounds and target ranges.\n\nWeapon smiths and armorers serve practical military needs. Battlemasters coordinate night elf forces across the wider world.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_warrior-s-terrace-843119d028377fb9f484/1-0000.mp3", duration = 40.6987755, start = 0},
  },
}
P.transport["subzone:warsong-labor-camp"] = {
  hash = "c0acc1",
  fullHash = "a1ab0c",
  text = "Warsong Labor Camp. Warsong loggers cut Ashenvale timber at Warsong Labor Camp to supply the growing Horde. They work in the southeast, far from help and under threat from the forest's defenders. East of Fallen Sky Lake and southwest of the Dor'Danil Barrow Den, Warsong loggers cut Ashenvale's dense timber. Durotar's dry plains offer little wood for building cities such as Orgrimmar, so the Warsong clan has entered these contested woods. Far from other Horde settlements, loggers and orcish guards fell ancient trees while night elf scouts and Alliance warbands threaten the camp. Warsong Labor Camp lies far from the main road and fortified bases such as Splintertree Post. Alliance raiders strike its working peons and watchmen, knowing help may be slow to arrive. Night elves see each felled tree as a desecration. So the camp remains a point of conflict in the war.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_warsong-labor-camp-1e1eaaf67b4b84a1b0e3/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["subzone:warsong-lumber-camp"] = {
  hash = "a95ecf",
  fullHash = "c4250b",
  text = "Warsong Lumber Camp. Warsong Lumber Camp cuts Ashenvale timber for the Horde and keeps its conflict with the night elves alive. Kargathia Keep guards the operation. In eastern Ashenvale, Warsong Lumber Camp cuts through the dense canopy for the Horde. Orc peons and hired goblin engineers drive whirring shredders through towering trunks, making lumber for nearby Splintertree Post and the fledgling nation of Durotar.\n\nKargathia Keep anchors the camp's defenses against night elf counterattacks. War wolves wait in an active kennel. To the Warsong, every felled tree means survival and strength. To the native Sentinels, each saw blade is an act of sacrilege. Warsong clan warriors first entered these woods with Grom Hellscream during the Third War, seeking timber for the Horde. Their clearing enraged the demigod Cenarius and drew the ancient wrath of the night elves.\n\nNow Thrall's Horde banners fly over the camp, but old hatreds still burn. Untamed timber, hostile elves, and demonic corruption around neighboring Felfire Hill surround it. Its defenders stay armed around the clock, axes in hand as they harvest, ready to abandon the lumber when the next ambush comes.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_warsong-lumber-camp-3bd5fb360ce8dd12f451/1-0000.mp3", duration = 74.5273469, start = 0},
  },
}
P.transport["subzone:weathered-nook"] = {
  hash = "c8caab",
  fullHash = "c8caab",
  text = "Weathered Nook. High above Thousand Needles, Dorn Plainstalker and Prate Cloudseer make their home in a quiet cliffside shelter. From there, they look out across the stone spires, far from the canyon floor. North of Freewind Post, a narrow ramp climbs the sandstone cliff to a sheltered ledge and cave. From below, travelers can easily miss the Weathered Nook high above the canyon basin. Dorn Plainstalker and Prate Cloudseer live here, away from any large settlement or military post. The ledge shelters them from the prevailing winds and gives them a broad view across the needle plateaus.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_weathered-nook-64fc1928aa95e1c549ed/1-0000.mp3", duration = 34.7428571, start = 0},
  },
}
P.transport["subzone:webwinder-path"] = {
  hash = "a3194e",
  fullHash = "a3194e",
  text = "Webwinder Path. Webwinder Path carries travelers through the lower Stonetalon Mountains, from Malaka'jin toward Mirkfallon Lake. Spiders and native beasts roam its crags and woods. Thick webs hang among the trees and cling to jagged cliffs along Webwinder Path. Mountain spiders prowl the road, while thunder lizards and territorial rams roam nearby. Watch your step as the route winds through the lower Stonetalon Mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_webwinder-path-505630035aada33be0fb/1-0000.mp3", duration = 25.7306122, start = 0},
  },
}
P.transport["subzone:wellspring-lake"] = {
  hash = "1aed9d",
  fullHash = "1aed9d",
  text = "Wellspring Lake. In northern Teldrassil, Wellspring Lake’s waters flow north as corruption troubles the wildlife. Northeast of Darnassus, the lake once offered night elf fishermen a quiet retreat. Beneath Teldrassil’s canopy, Wellspring Lake lies between Darnassus and the Oracle Glade. Night elves once came to its clear waters to fish and sit in quiet thought. Springs deep within the World Tree feed the lake, whose waters flow north through the Wellspring River.\n\nNow a blight troubles the surrounding wilds. Aggressive spiders, prowling nightsabers, and agitated timberlings roam the banks, making the shore dangerous for travelers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_wellspring-lake-f10b48650f92662cec32/1-0000.mp3", duration = 40.0457143, start = 0},
  },
}
P.transport["subzone:wellspring-river"] = {
  hash = "5bdf83",
  fullHash = "5bdf83",
  text = "Wellspring River. In Teldrassil, Wellspring River carries water north from Wellspring Lake and over the World Tree's edge to the sea. Timberlings along its banks have grown dangerous. Wellspring River runs north from Wellspring Lake through Teldrassil's forest. At the edge of the great tree, its waters plunge to the sea below.\n\nThe riverbanks have grown unsafe. Timberlings there have gone crazed, attacking travelers and druids who come near the water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_wellspring-river-4445d5035dfcd2848a6d/1-0000.mp3", duration = 27.4808163, start = 0},
  },
}
P.transport["subzone:westbrook-garrison"] = {
  hash = "75d6dc",
  fullHash = "b12354",
  text = "Westbrook Garrison. At Westbrook Garrison, Deputy Rainer's few guards watch Elwynn's western road. Gnolls and bandits threaten the border, and the outpost lacks the men and supplies to hold it alone. Westbrook Garrison watches the road where Elwynn Forest thins toward Westfall. Deputy Rainer and a handful of guards patrol the western roads, too few to cover them. Much of the Stormwind Army serves abroad, and indecision in the capital leaves the outpost without needed support.\n\nThieves grow bolder, and Riverpaw gnolls have overrun the southern woods. Marshal Dughan in Goldshire has sent no formal reinforcements, so the guards depend on travelers to help secure the highway. Riverpaw gnolls gather south of Forest's Edge, raiding supply lines and homesteads. The packs follow Hogger, a fearsome chieftain whose forces outnumber the garrison and overwhelm its guards with brute strength.\n\nA high bounty is posted across the outpost. It seeks fighters willing to enter the hills and bring down Hogger before the gnolls press farther east.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_westbrook-garrison-2b80b31e6d236e9c9c11/1-0000.mp3", duration = 60.8653061, start = 0},
  },
}
P.transport["subzone:westfall-lighthouse"] = {
  hash = "eb70bc",
  fullHash = "eb70bc",
  text = "Westfall Lighthouse. Westfall Lighthouse stands dark on the rocky isle off Westfall's southwestern shore, and its keepers are gone. Old Murk-Eye led the attack that killed them. Captain Grayson's spirit remains by the tower. Westfall Lighthouse once guided ships past Westfall's dangerous southwestern bluffs and along the coast near Stormwind. As law and order failed across the region, royal patrols dwindled and coastal dangers grew unchecked. Murloc tribes drove the keepers inland. The family returned to relight the beacon, but Old Murk-Eye rallied his kin to attack again. The murlocs killed the keepers and put out the light.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_westfall-lighthouse-cbbe3f2af888a3373493/1-0000.mp3", duration = 36.8326531, start = 0},
  },
}
P.transport["subzone:whelgar-s-excavation-site"] = {
  hash = "c83fe1",
  fullHash = "c83fe1",
  text = "Whelgar's Excavation Site. On a ridge above Whelgar's Excavation Site, dwarven prospectors are cut off from their findings. Mottled raptors overran the quarry where they sought ancient fossils and clues to the distant past. Between Menethil Harbor and Dun Modr, dwarven prospectors dug for ancient fossils and earthen mysteries. Their search stirred the native mottled raptors. Overwhelmed and under-equipped, the archaeologists fled to a ridge overlooking the site. Their tents, tools and unearthed relics remain among the prowling predators.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_whelgar-s-excavation-site-25b0daafc8e3c60efff7/1-0000.mp3", duration = 30.7983673, start = 0},
  },
}
P.transport["subzone:whitereach-post"] = {
  hash = "937fbd",
  fullHash = "937fbd",
  text = "Whitereach Post. Horde travelers find rest at Whitereach Post beside the canyon path in Thousand Needles. Near Camp E'thok, the small camp overlooks the harsh road between Feralas and the salt flats beneath the sandstone pillars. Whitereach Post watches over the canyon road through Thousand Needles. Near Camp E'thok, this modest Horde foothold is one of several posts in the rugged wastes. Scouts monitor travel along the canyon floor between the mesas. Couriers and travelers crossing the contested wastes can stop here, though the post has fewer defenses than the great lift or the major tribal settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_whitereach-post-e6d82cdd7d38fb19bb38/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["subzone:wildbend-river"] = {
  hash = "8406f2",
  fullHash = "8406f2",
  text = "Wildbend River. Near the Grove of the Ancients, Wildbend River carries demonic poison toward the sea. Its waters cross southern Darkshore from the corrupted heights of Felwood and threaten the wilderness. Wildbend River carries corruption through southern Darkshore. It runs west past the Grove of the Ancients and empties into the sea. The stream begins as Felwood's Bloodvenom River, then tumbles through rocky ridges with foul runoff. Night elves watch its banks for twisted wildlife and spreading demonic blight.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_wildbend-river-8608fb5e63bb721d681b/1-0000.mp3", duration = 30.9028571, start = 0},
  },
}
P.transport["subzone:windshear-crag"] = {
  hash = "647da1",
  fullHash = "d30b33",
  text = "Windshear Crag. In central Stonetalon, Windshear Crag lies stripped by the Venture Company's logging. Machinery and muddy runoff have replaced the old forest. Kobolds dig for ore nearby, and a mountain path leads beneath the ridges to Ashenvale. The Venture Company cut down Windshear Crag's old forest for profit. Stumps and machinery now fill the basin. From a platform above Cragpool Lake, Gerenzo Wrenchwhistle oversees the logging. The leper gnome's engineering gave the company the Super Reaper 6000, a machine that fells great trees in moments. As the operation strips the mountain bare, rival engineers and local inhabitants grow angry. Logging is not the only danger or crossing at Windshear Crag. In the southeast, kobolds dig through Windshear Mine for Smoky Iron Ingots. They attack those who come near their haul. From the crag's northeast reaches, the Talondeep Path runs beneath the ridges into Ashenvale. Near its entrance, the tauren elder Braug Dimspirit tests the historical wisdom and resolve of Horde travelers crossing the contested peaks.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_windshear-crag-ebd8386df1eefac68058/1-0000.mp3", duration = 63.9216327, start = 0},
  },
}
P.transport["subzone:xavian"] = {
  hash = "0199e9",
  fullHash = "0199e9",
  text = "Xavian. At Xavian in northeastern Ashenvale, satyrs hold an ancient night elf temple. They make it their chief seat in the forest and use its ruins for dark rites that spread demonic corruption through the woodland. In Ashenvale's northeastern hills, Xavian lies west of Forest Song and north of Satyrnaar. Satyrs hold its ruined temple, once sacred to the night elves, and make it their chief stronghold in the forest. Their leaders, including Prince Raze and Geltharis, direct their followers from its desecrated arches and terraces.\n\nAcross the grounds, satyrs perform rites against the woodland and use stolen Warsong oil to blight it. The place bears the name of Xavius, a highborne councilor who became the first satyr during the War of the Ancients after failing Sargeras.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_xavian-e3d07acac69eeece33d6/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["subzone:yorgen-farmstead"] = {
  hash = "35943b",
  fullHash = "c6c3c6",
  text = "Yorgen Farmstead. Defias outlaws hold Yorgen Farmstead in southern Duskwood. Sven Yorgen fled north to a camp along the Darkened Bank. Yorgen Farmstead lies in southern Duskwood, where Sven Yorgen once worked the land. Danger drove him north to a makeshift camp along the Darkened Bank. Outlaws took the farm after he left, seeking ground beyond Stormwind's reach. The Defias Brotherhood uses Yorgen Farmstead as a staging ground. Masked highwaymen and cutthroats hide among its fences and outbuildings, screened by dense trees. Defias assassins patrol the grounds and ambush travelers who trespass.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_yorgen-farmstead-2d3e25d58523ec4f1d20/1-0000.mp3", duration = 36.9110204, start = 0},
  },
}
P.transport["subzone:zoram-gar-outpost"] = {
  hash = "30471b",
  fullHash = "3d3043",
  text = "Zoram'gar Outpost. Horde forces hold the western shore of Ashenvale at Zoram'gar Outpost. From this fortified beachhead, they watch the Zoram Strand and the dangers beyond it. Zoram'gar Outpost holds Ashenvale's northwestern edge, where forest meets sea. Night elf territory lies inland, and hazards wait offshore. Scouts, hunters, and shaman keep watch from the isolated camp. Naga prowl the shallows, while cultists and primal horrors stir in Blackfathom Deeps, the cavern system down the shore. Zoram'gar Outpost links by flight to other Horde holdings: Splintertree Post, the Crossroads, and Thunder Bluff. Though small, the camp anchors Horde supply lines along Ashenvale's western coast.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_zoram-gar-outpost-48b28ee6ca0fdc5f4c48/1-0000.mp3", duration = 43.3371429, start = 0},
  },
}
P.transport["subzone:zoram-strand"] = {
  hash = "7f56b6",
  fullHash = "a37424",
  text = "Zoram Strand. At Ashenvale's northwestern edge, Zoram Strand faces the Veiled Sea. The shore's ancient night elven ruins now lie beneath Wrathtail naga, shipwrecks, and beached leviathans. Blackfathom Deeps begins in the submerged temple complex nearby. Ten thousand years ago, the night elven city of Zoram stood on this coast. Then the Great Sundering tore Kalimdor apart and sank the settlement beneath the sea. Now the tide carries ancient relics, shattered vessels, and the carcasses of massive sea beasts onto the shore. Wrathtail naga overrun the beaches and tidal pools, guarding the flooded ruins and ancient artifacts from anyone who comes near. Travelers from the mainland and along the coast still come to Zoram Strand despite the naga. South of the shore, the Horde holds Zoram'gar Outpost, where its warriors fight to secure the coast. Nearby, Blackfathom Deeps lies deep within the caverns. The ancient temple of Elune has fallen into dark hands, drawing scouts, scholars, and treasure seekers who brave the surf.",
